 RETURN replace(body,roster,ordered_roster);
END $source_order$;

-- [COMP:api/native-turn-frame] Authenticate the retained guard before invocation.
DO $authenticate_retained_guard$
DECLARE actual pg_proc;reference pg_proc;expected jsonb;relation pg_class;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 body constant text:='
 SELECT native_turn_helpers_current() AND EXISTS(SELECT 1 FROM pg_class r WHERE r.oid=''native_retained_contract_helpers''::regclass
  AND r.relkind=''r'' AND r.relpersistence=''p'' AND r.relrowsecurity AND NOT r.relforcerowsecurity
  AND r.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(r.relacl,acldefault(''r'',r.relowner))) a WHERE a.grantee<>r.relowner OR a.grantor<>r.relowner)
  AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=r.oid)
  AND (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped)=ARRAY[''signature'',''fingerprint'']
  AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped AND (atttypid<>''text''::regtype OR NOT attnotnull)))
 AND array_agg(h.signature ORDER BY h.signature)=ARRAY[''native_retained_helpers_current()'',''native_turn_privacy_edges(uuid,jsonb)'']::text[]
 AND bool_and(p.oid IS NOT NULL AND h.fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex''))
 FROM native_retained_contract_helpers h LEFT JOIN pg_proc p ON p.oid=to_regprocedure(''public.''||h.signature)
';
BEGIN
 -- Reading the private registry must not execute an unreviewed RLS policy/rule.
 SELECT * INTO relation FROM pg_class WHERE oid=to_regclass('public.native_retained_contract_helpers');
 IF relation.oid IS NULL OR relation.relkind<>'r' OR relation.relpersistence<>'p'
  OR relation.relowner<>owner_id OR NOT relation.relrowsecurity OR relation.relforcerowsecurity
  OR coalesce(relation.relacl,acldefault('r',owner_id)) IS DISTINCT FROM acldefault('r',owner_id)
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=relation.oid)
  OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=relation.oid)
  OR (SELECT jsonb_agg(jsonb_build_array(attnum,attname,atttypid,atttypmod,attnotnull,attgenerated,attidentity,attisdropped,attacl) ORDER BY attnum)
   FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0) IS DISTINCT FROM
   '[[1,"signature","25",-1,true,"","",false,null],[2,"fingerprint","25",-1,true,"","",false,null]]'::jsonb
  OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0
   AND (atthasdef OR attcollation<>'pg_catalog."default"'::regcollation))
 THEN RAISE EXCEPTION 'publication_retained_registry_changed';END IF;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.native_retained_helpers_current()');
 IF actual.oid IS NULL THEN RAISE EXCEPTION 'publication_retained_guard_missing';END IF;
 -- This declaration is reconstructed from the immutable source and named
 -- retirement, never from actual.prosrc or an installed registry record.
 EXECUTE format('CREATE FUNCTION pg_temp.publication_retained_guard_reference() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS %L',body);
 SELECT * INTO STRICT reference FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname='publication_retained_guard_reference';
 expected:=(to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])||jsonb_build_object(
  'oid',actual.oid,'proname','native_retained_helpers_current','pronamespace','public'::regnamespace::oid,
  'proowner',owner_id,'proacl',ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)]);
 IF (actual.prosrc COLLATE "C") IS DISTINCT FROM (body COLLATE "C") OR to_jsonb(actual) IS DISTINCT FROM expected
 THEN RAISE EXCEPTION 'publication_retained_guard_changed';END IF;
 INSERT INTO pg_temp.publication_reviewed_contracts VALUES('native_retained_helpers_current()',expected,encode(sha256(convert_to(expected::text,'UTF8')),'hex'));
 INSERT INTO pg_temp.publication_expected_current VALUES('native_retained_helpers_current()',expected);
 INSERT INTO pg_temp.publication_successor_templates VALUES('native_retained_helpers_current()',jsonb_build_array(body));
 DROP FUNCTION pg_temp.publication_retained_guard_reference();
END $authenticate_retained_guard$;

DO $authenticate$ DECLARE expected jsonb;p pg_proc;body text;acl jsonb;owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);runtime_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');BEGIN
 IF EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D') THEN RAISE EXCEPTION 'publication_unreviewed_ddl_trigger';END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements('[{"signature":"agent_read_scope_allows(text,text[],uuid[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"agent_read_scope_allows","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["row_sensitivity","row_teams","row_projects"],"proargtypes":["25","1009","2951"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"PUBLIC","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE clearance text;\nBEGIN\n  clearance=nullif(current_setting(''app.agent_clearance'',true),'''');\n  IF clearance IS NOT NULL AND (sensitivity_rank(clearance) IS NULL OR sensitivity_rank(row_sensitivity) IS NULL\n    OR sensitivity_rank(row_sensitivity)>sensitivity_rank(clearance)) THEN RETURN false; END IF;\n  RETURN agent_scope_grant_allows(''app.agent_compartments'',row_teams)\n    AND agent_scope_grant_allows(''app.agent_project_ids'',row_projects::text[]);\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"agent_scope_grant_allows(text,text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"agent_scope_grant_allows","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["setting_name","required"],"proargtypes":["25","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"PUBLIC","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE raw_grant text; grant_value jsonb;\nBEGIN\n  raw_grant=nullif(current_setting(setting_name,true),'''');\n  IF raw_grant IS NULL THEN RETURN true; END IF;\n  grant_value=raw_grant::jsonb;\n  IF grant_value=''null''::jsonb THEN RETURN true; END IF;\n  IF jsonb_typeof(grant_value)<>''array'' THEN RETURN false; END IF;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(grant_value) value WHERE jsonb_typeof(value)<>''string'') THEN RETURN false; END IF;\n  RETURN NOT EXISTS(SELECT 1 FROM unnest(coalesce(required,''{}'')) value WHERE NOT grant_value ? value);\nEXCEPTION WHEN invalid_text_representation THEN RETURN false;\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"agent_visibility_allows(uuid,uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"agent_visibility_allows","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_workspace","p_user","p_assistant"],"proargtypes":["2950","2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"PUBLIC","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE bound_workspace text; bound_actor text; bound_assistants jsonb;\nBEGIN\n  bound_workspace=nullif(current_setting(''app.agent_workspace_id'',true),'''');\n  bound_actor=nullif(current_setting(''app.agent_actor_id'',true),'''');\n  bound_assistants=nullif(current_setting(''app.agent_visibility_assistants'',true),'''')::jsonb;\n  IF bound_workspace IS NOT NULL AND p_workspace IS NOT NULL AND p_workspace::text<>bound_workspace THEN RETURN false; END IF;\n  IF bound_actor IS NOT NULL AND p_user IS NOT NULL AND p_user::text<>bound_actor THEN RETURN false; END IF;\n  IF bound_assistants IS NOT NULL AND bound_assistants<>''null''::jsonb AND p_assistant IS NOT NULL THEN\n    IF jsonb_typeof(bound_assistants)<>''array'' THEN RETURN false; END IF;\n    RETURN bound_assistants @> jsonb_build_array(p_assistant::text);\n  END IF;\n  RETURN true;\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_canonical_ancestry_allowed(uuid,text,uuid,text,boolean)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"application_canonical_ancestry_allowed","prorows":0,"pronargs":5,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i","v","writing"],"proargtypes":["2950","25","2950","25","16"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":{"$slot":{"kind":"argumentDefaults","identity":"boolean_false","encoding":"string"}},"pronargdefaults":1},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE nodes jsonb;node jsonb;dependency record;current jsonb;policy jsonb;mask jsonb;type_key text;\n resource application_field_resources;observation application_field_observations;envelope jsonb;expanded jsonb;current_roots jsonb;field_anchors jsonb:=''[]'';root jsonb;cursor_index integer:=0;\n history_envelope jsonb;history_proof jsonb;history_own boolean;history_state jsonb;history_version text;\n app_mode boolean:=nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL;\nBEGIN\n -- Recording privacy admission precedes body selection.\n IF NOT recording_source_read_allowed(w,k,i) THEN RETURN false;END IF;\n IF NOT writing AND NOT app_mode THEN\n  IF k=''application_field'' THEN\n   SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=i;\n   IF FOUND AND resource.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND resource.type_key=''memory'' AND resource.selection=''history'' THEN\n    history_envelope:=application_compute_field_envelope(w,resource.origin,resource.type_key,resource.resource_id,''history'',resource.selected_version,resource.fields);\n    IF history_envelope IS NULL OR history_envelope#>>''{source,version}'' IS DISTINCT FROM v THEN RETURN false;END IF;\n   END IF;\n  END IF;\n  history_proof:=history_envelope#>''{state,historyStatus}'';\n END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(l)),''[]'') INTO nodes FROM application_scope_lineage(w,ARRAY[k],ARRAY[i],ARRAY[v]) l;\n IF history_proof IS NOT NULL THEN\n  FOR root IN SELECT value FROM jsonb_array_elements(history_proof->''roots'') LOOP\n   SELECT coalesce(jsonb_agg(to_jsonb(l)),''[]'') INTO expanded FROM application_scope_lineage(w,ARRAY[root->>''kind''],ARRAY[(root->>''id'')::uuid],ARRAY[root->>''version'']) l;\n   SELECT coalesce(jsonb_agg(value),''[]'') INTO expanded FROM jsonb_array_elements(expanded) value WHERE NOT nodes @> jsonb_build_array(value);\n   nodes:=nodes||expanded;IF jsonb_array_length(nodes)>4096 THEN RETURN false;END IF;\n  END LOOP;\n END IF;\n WHILE cursor_index<jsonb_array_length(nodes) LOOP\n  node:=nodes->cursor_index;cursor_index:=cursor_index+1;\n  IF node->>''kind''=''application_field'' THEN\n   SELECT * INTO resource FROM application_field_resources r WHERE r.workspace_id=w AND r.id=(node->>''id'')::uuid;\n   IF NOT FOUND THEN RETURN false;END IF;\n   SELECT * INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=resource.id AND o.version=node->>''version'';\n   IF NOT FOUND THEN RETURN false;END IF;\n   history_own:=history_proof IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(history_proof->''ownFields'') f\n    WHERE f->>''kind''=''application_field'' AND f->>''id''=resource.id::text AND f->>''version''=observation.version\n     AND f->''resource''=to_jsonb(resource) AND f->''observation''=to_jsonb(observation));\n   IF history_own THEN\n    SELECT scope_version::text INTO history_version FROM memories WHERE workspace_id=w AND id=resource.resource_id;\n    history_state:=application_memory_history_field_state(w,resource.resource_id,history_version,resource.fields);\n    IF history_state IS NULL THEN RETURN false;END IF;\n    current:=history_state->''source'';\n   ELSE\n   current:=application_recorded_field_state_before_record_ancestry(w,resource.id,node->>''version'',0);\n   END IF;\n   IF NOT history_own AND (current IS NULL OR current->>''held'' IS DISTINCT FROM ''false'') THEN RETURN false;END IF;\n   IF NOT app_mode AND (application_reader_envelope_visible(w,observation.source_scope) IS NOT TRUE\n    OR application_reader_envelope_visible(w,current) IS NOT TRUE) THEN RETURN false;END IF;\n   -- Current target identities may differ from the immutable original targets.\n   -- Read their metadata through the same selected-field canonical computation,\n   -- then union their physical source lineage into this bounded worklist.\n   IF history_own THEN\n    envelope:=application_compute_field_envelope(w,resource.origin,resource.type_key,resource.resource_id,''history'',history_version,resource.fields);\n   ELSE\n   envelope:=application_compute_field_envelope(w,resource.origin,resource.type_key,resource.resource_id,\n    resource.selection,resource.selected_version,resource.fields);\n   END IF;\n   IF envelope IS NULL THEN RETURN false;END IF;\n   WITH RECURSIVE envelopes(value) AS (\n    SELECT envelope UNION ALL SELECT child.value FROM envelopes e CROSS JOIN LATERAL jsonb_array_elements(e.value->''children'') child(value)\n   ), roots AS (\n    SELECT jsonb_build_object(''kind'',e.value#>>''{state,sourceKind}'',''id'',e.value#>>''{state,sourceId}'',''version'',e.value#>>''{state,sourceVersion}'') AS value\n     FROM envelopes e WHERE scope_source_table(e.value#>>''{state,sourceKind}'') IS NOT NULL OR e.value#>>''{state,sourceKind}''=''entity_instance''\n    UNION SELECT jsonb_build_object(''kind'',''external_source'',''id'',source->>''resourceId'',''version'',source->>''version'')\n     FROM envelopes e CROSS JOIN LATERAL jsonb_array_elements(e.value->''sources'') source WHERE source->>''resourceKind''=''external_source''\n   ) SELECT coalesce(jsonb_agg(value),''[]'') INTO current_roots FROM roots;\n   field_anchors:=field_anchors||current_roots; FOR root IN SELECT value FROM jsonb_array_elements(current_roots) LOOP\n    SELECT coalesce(jsonb_agg(to_jsonb(l)),''[]'') INTO expanded FROM application_scope_lineage(w,ARRAY[root->>''kind''],ARRAY[(root->>''id'')::uuid],ARRAY[root->>''version'']) l;\n    SELECT coalesce(jsonb_agg(value),''[]'') INTO expanded FROM jsonb_array_elements(expanded) value WHERE NOT nodes @> jsonb_build_array(value);\n    nodes:=nodes||expanded;\n    IF jsonb_array_length(nodes)>4096 THEN RETURN false;END IF;\n   END LOOP;\n  ELSIF history_proof IS NOT NULL AND node->>''kind''=''memory'' AND history_proof->''qualifiedAnchors'' @> jsonb_build_array(node) THEN\n   SELECT scope_version::text INTO history_version FROM memories WHERE workspace_id=w AND id=(node->>''id'')::uuid;\n   history_state:=application_memory_history_field_state(w,(node->>''id'')::uuid,history_version,application_memory_field_keys());\n   IF history_state IS NULL THEN RETURN false;END IF;\n  ELSIF history_proof IS NOT NULL AND node->>''kind''=''memory'' AND history_proof->''independentNodes'' @> jsonb_build_array(node) THEN\n   current:=read_admitted_native_scope_snapshot(w,''memory'',(node->>''id'')::uuid);\n   IF current IS NULL OR current->>''held'' IS DISTINCT FROM ''false'' THEN RETURN false;END IF;\n  ELSIF node->>''kind''=''external_source'' THEN\n   current:=external_source_snapshot(w,(node->>''id'')::uuid);\n   IF current IS NULL OR current->>''held'' IS DISTINCT FROM ''false'' OR current->>''version'' IS DISTINCT FROM node->>''version''\n    OR writing AND external_source_retention_allowed(w,(node->>''id'')::uuid,node->>''version'') IS NOT TRUE THEN RETURN false;END IF;\n  -- The root''s own canonical reader/writer owns row authority and refusal\n  -- semantics. Field observations still recheck every native anchor.\n  ELSIF scope_source_table(node->>''kind'') IS NOT NULL AND NOT app_mode AND application_native_same_destination(w,k,i,node->>''kind'',(node->>''id'')::uuid) IS NOT TRUE THEN\n   current:=read_admitted_native_scope_snapshot(w,node->>''kind'',(node->>''id'')::uuid);\n   IF node->>''kind''=''crm_event'' AND current IS NULL OR current IS NOT NULL AND current->>''held'' IS DISTINCT FROM ''false'' THEN RETURN false;END IF;\n  END IF;\n END LOOP;\n IF app_mode THEN\n  FOR node IN SELECT value FROM jsonb_array_elements(nodes) LOOP\n   IF (scope_source_table(node->>''kind'') IS NOT NULL OR node->>''kind''=''entity_instance'')\n    AND application_native_same_destination(w,k,i,node->>''kind'',(node->>''id'')::uuid) IS NOT TRUE\n    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(field_anchors) anchor WHERE anchor->>''kind''=node->>''kind'' AND anchor->>''id''=node->>''id'' AND anchor->>''version''=node->>''version'') THEN\n    current:=read_scope_source(w,node->>''kind'',(node->>''id'')::uuid);\n    IF current IS NULL OR current->>''held'' IS DISTINCT FROM ''false'' OR application_native_source_scope_allowed(w,node->>''kind'',(node->>''id'')::uuid,current) IS NOT TRUE THEN RETURN false;END IF;\n   END IF;\n  END LOOP;\n END IF;\n FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)\n  ON d.resource_kind=ancestor.value->>''kind'' AND d.resource_id=(ancestor.value->>''id'')::uuid WHERE d.workspace_id=w LOOP\n  -- Application source profiles keep their existing hold until their canonical\n  -- native-source port is available. Never impersonate a member to lift it.\n  IF (CASE WHEN app_mode THEN application_native_source_scope_allowed(w,dependency.resource_kind,dependency.resource_id,\n   jsonb_build_object(''workspaceId'',w,''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids),''{}'',CASE WHEN writing AND application_native_same_destination(w,k,i,dependency.resource_kind,dependency.resource_id) THEN ''patch'' ELSE ''read'' END) ELSE application_reader_envelope_visible(w,jsonb_build_object(''workspaceId'',w,\n   ''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids)) END) IS NOT TRUE THEN RETURN false;END IF;\n END LOOP;\n IF app_mode THEN\n  FOR dependency IN SELECT DISTINCT s.source_kind,s.source_id FROM scope_derivation_sources s JOIN scope_derivations d\n   ON d.workspace_id=s.workspace_id AN