NOT FOUND THEN RAISE EXCEPTION ''native_memory_scan_context_unavailable'' USING ERRCODE=''55P03'';END IF;\n  IF NOT EXISTS(SELECT 1 FROM pg_proc canonical_proc JOIN pg_proc candidate_proc\n   ON candidate_proc.oid=''public.application_memory_query_candidate_state(uuid,uuid,text[],jsonb)''::regprocedure\n   WHERE canonical_proc.oid=''public.application_memory_field_state_before_successor(uuid,uuid,text[])''::regprocedure\n    AND array_length(string_to_array(canonical_proc.prosrc,''context:=application_memory_query_context(w);''),1)=2\n    AND candidate_proc.prosrc=replace(canonical_proc.prosrc,''context:=application_memory_query_context(w);'',''context:=admitted_context;'')\n    AND ROW(candidate_proc.proowner,candidate_proc.prosecdef,candidate_proc.proconfig,candidate_proc.prolang,candidate_proc.provolatile,candidate_proc.proparallel,candidate_proc.proisstrict,candidate_proc.prorettype,candidate_proc.proretset,candidate_proc.prokind,candidate_proc.proleakproof)\n     IS NOT DISTINCT FROM ROW(canonical_proc.proowner,canonical_proc.prosecdef,canonical_proc.proconfig,canonical_proc.prolang,canonical_proc.provolatile,canonical_proc.proparallel,canonical_proc.proisstrict,canonical_proc.prorettype,canonical_proc.proretset,canonical_proc.prokind,canonical_proc.proleakproof)) THEN\n   RAISE EXCEPTION ''native_memory_scan_context_unavailable'' USING ERRCODE=''55P03'';END IF;\n  query_context:=application_memory_query_context(w);\n  IF query_context#>>''{policy,nativeDefault}'' IS DISTINCT FROM ''true'' THEN\n   RAISE EXCEPTION ''native_memory_scan_context_unavailable'' USING ERRCODE=''55P03'';END IF;\n  shared_context:=true;\n EXCEPTION WHEN lock_not_available THEN shared_context:=false;query_context:=NULL;\n END;\n WITH RECURSIVE successors(id,depth) AS (\n  SELECT t.successor_id,1 FROM native_memory_successor_transitions t JOIN jsonb_array_elements(frozen->''candidates'') c ON t.predecessor_id=(c->>''id'')::uuid\n   WHERE t.workspace_id=w AND t.predecessor_version=c->>''version''\n  UNION ALL SELECT t.successor_id,s.depth+1 FROM successors s JOIN native_memory_successor_transitions t ON t.workspace_id=w AND t.predecessor_id=s.id WHERE s.depth<100\n ) SELECT coalesce(array_agg(DISTINCT id),''{}'') INTO excluded FROM successors;\n FOR candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w AND NOT id=ANY(excluded)\n  AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text AND c->>''version''=memories.scope_version::text)) ORDER BY id LOOP\n  count_value:=count_value+1;IF count_value>4096 THEN RETURN NULL;END IF;\n  IF NOT include_retained AND EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=candidate.id) THEN CONTINUE;END IF;\n  IF shared_context AND NOT EXISTS(SELECT 1 FROM memories WHERE workspace_id=w AND id=candidate.id AND valid_to IS NOT NULL) THEN\n   state:=application_memory_query_candidate_state(w,candidate.id,fields,query_context);\n  ELSE\n   state:=application_memory_field_state(w,candidate.id,fields);\n  END IF;\n  IF state IS NULL OR application_query_scope_admits_point(bounds,state->''source'') IS NOT TRUE THEN CONTINUE;END IF;\n  candidates:=candidates||jsonb_build_array(jsonb_build_object(''id'',candidate.id,''version'',candidate.scope_version::text,''source'',state->''source''));\n  policies:=policies||jsonb_build_array(jsonb_build_object(''id'',candidate.id,''policy'',\n   CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''policies'') original_policy\n    WHERE original_policy->>''id''=candidate.id::text AND original_policy->''policy''=state->''legacyPolicyVersion'')\n   THEN state->''legacyPolicyVersion'' ELSE state->''policyVersion'' END));\n END LOOP;\n IF shared_context AND (NOT EXISTS(SELECT 1 FROM pg_proc canonical_proc JOIN pg_proc candidate_proc\n   ON candidate_proc.oid=''public.application_memory_query_candidate_state(uuid,uuid,text[],jsonb)''::