"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE selected jsonb:=''[]'';nodes jsonb:=''[]'';part jsonb;root jsonb;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n IF jsonb_typeof(roots) IS DISTINCT FROM ''array'' OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096\n OR EXISTS(SELECT 1 FROM jsonb_array_elements(roots) r WHERE (r->>''kind'' IN(''application_field'',''session_message'',''session_context_revision'',''workspace_file'',''memory'')\n  AND r->>''id'' IS NOT NULL AND r->>''version'' IS NOT NULL) IS NOT TRUE) THEN RETURN NULL;END IF;\n -- Prefer query domains; their exact recorded children often cover the other\n -- original fields. No original declaration or permission floor is removed.\n FOR root IN SELECT r FROM jsonb_array_elements(roots) r LEFT JOIN application_field_resources f\n  ON r->>''kind''=''application_field'' AND f.workspace_id=w AND f.id=(r->>''id'')::uuid\n  ORDER BY (f.selection=''query_domain'') DESC NULLS LAST,r->>''version'',r->>''kind'',r->>''id'' LOOP\n  IF nodes @> jsonb_build_array(root) THEN CONTINUE;END IF;\n  SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO part\n   FROM application_scope_lineage(w,ARRAY[root->>''kind''],ARRAY[(root->>''id'')::uuid],ARRAY[root->>''version'']) n;\n  SELECT jsonb_agg(n ORDER BY n->>''kind'',n->>''id'',n->>''version'') INTO nodes\n   FROM(SELECT DISTINCT n FROM jsonb_array_elements(nodes||part) n LIMIT 4097) bounded;\n  IF jsonb_array_length(nodes)>4096 THEN RETURN NULL;END IF;\n  -- A later domain can subsume earlier representatives. Prune those exact\n  -- roots before applying the execution-input bound, without dropping any\n  -- original declaration or accumulated lineage obligation.\n  SELECT coalesce(jsonb_agg(r ORDER BY r::text),''[]'') INTO selected FROM jsonb_array_elements(selected) r\n   WHERE NOT part @> jsonb_build_array(r);\n  selected:=selected||jsonb_build_array(root);\n  IF jsonb_array_length(selected)>100 THEN RETURN NULL;END IF;\n END LOOP;\n IF native_worklist_edges(w,nodes) IS NULL OR native_turn_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n RETURN jsonb_build_object(''roots'',selected,''lineage'',nodes);\nEXCEPTION WHEN invalid_parameter_value THEN\n IF SQLERRM=''scope_ancestry_unavailable'' THEN RETURN NULL;END IF;RAISE;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_same_destination(uuid,text,uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"application_native_same_destination","prorows":0,"pronargs":5,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i","other_kind","other_id"],"proargtypes":["2950","25","2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\n SELECT k=other_kind AND (i=other_id OR k=''task'' AND EXISTS(SELECT 1 FROM tasks a JOIN tasks b ON b.workspace_id=a.workspace_id AND b.logical_id=a.logical_id\n  WHERE a.workspace_id=w AND a.id=i AND b.id=other_id))\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_source_edges_dispatch(uuid,text,uuid,text)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"application_native_source_edges_dispatch","prorows":1000,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t","t","t"],"proargnames":["w","k","i","v","kind","id","version"],"proargtypes":["2950","25","2950","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","25","2950","25","25","2950","25"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["BEGIN\n IF k=''application_field'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT o.source_kind,o.source_id,o.source_version FROM application_field_observations o\n  WHERE k=''application_field'' AND o.workspace_id=w AND o.resource_id=i AND o.version=v\n UNION\n SELECT s.source_kind,s.source_id,s.source_version FROM application_field_observation_sources s\n  WHERE k=''application_field'' AND s.workspace_id=w AND s.resource_id=i AND s.version=v;\n ELSIF k=''file_segment'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT ''workspace_file'',wf.id,wf.scope_version::text FROM file_segments fs\n  JOIN workspace_files wf ON wf.id=fs.file_id AND wf.workspace_id=fs.workspace_id\n  WHERE k=''file_segment'' AND fs.workspace_id=w AND fs.id=i;\n ELSIF k=''workflow_run'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT observed.value->>''resourceKind'',(observed.value->>''resourceId'')::uuid,observed.value->>''version''\n  FROM jsonb_array_elements(CASE WHEN k=''workflow_run'' THEN read_workflow_derivation_inputs(w,i) ELSE ''[]''::jsonb END) input\n  CROSS JOIN LATERAL jsonb_array_elements(coalesce(input#>''{evidence,sources}'',''[]''::jsonb)\n   ||CASE WHEN jsonb_typeof(input->''blueprintSource'')=''object'' THEN jsonb_build_array(input->''blueprintSource'') ELSE ''[]''::jsonb END) observed(value);\n ELSE\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i;\n END IF;\nEND"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_title_acquisition_helpers_current()","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"application_native_title_acquisition_helpers_current","prorows":0,"pronargs":0,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["BEGIN IF (SELECT count(*)=8 AND coalesce(bool_and(encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'')=pin.fingerprint),false)\n   FROM (VALUES (",{"slot":{"kind":"function","identity":"application_scope_lineage(uuid,text[],uuid[],text[])"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"application_scope_lineage(uuid,text[],uuid[],text[])"}},"''::text),(",{"slot":{"kind":"function","identity":"read_entity_derivation_source(uuid,text,uuid)"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"read_entity_derivation_source(uuid,text,uuid)"}},"''::text),(",{"slot":{"kind":"function","identity":"session_recording_read_allowed(uuid)"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"session_recording_read_allowed(uuid)"}},"''::text),(",{"slot":{"kind":"function","identity":"recording_source_read_allowed(uuid,text,uuid)"}},"::oid,''",{"s