 NOT TRUE OR jsonb_typeof(children) IS DISTINCT FROM ''array''\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT coalesce(jsonb_agg(value ORDER BY value::text),''[]'') INTO sources FROM (\n  SELECT DISTINCT refs.value FROM jsonb_array_elements(children) c CROSS JOIN LATERAL\n   jsonb_array_elements(jsonb_build_array(c->''source'')||coalesce(c->''sources'',''[]'')) refs(value)\n ) distinct_sources;\n identity_value:=application_field_digest(jsonb_build_object(''workspaceId'',w,''origin'',origin,''typeKey'',t,''id'',domain_id,\n  ''selection'',''query_domain'',''selectedVersion'',NULL,''fields'',fields,''fieldIdentity'',state->''fieldIdentity''));\n resource:=application_field_resource_uuid(identity_value);\n version_value:=application_field_digest(jsonb_build_object(''resourceId'',resource,''recordVersion'',state->''recordVersion'',\n  ''sourceVersion'',state->''sourceVersion'',''policyVersion'',state->''policyVersion'',''scope'',scope,''sources'',sources));\n envelope:=jsonb_build_object(''resourceId'',resource,''identity'',identity_value,''origin'',origin,''typeKey'',t,''id'',domain_id,\n  ''selection'',''query_domain'',''selectedVersion'',NULL,''fields'',fields,''fieldIdentity'',state->''fieldIdentity'',''state'',state,\n  ''children'',children,''sources'',sources,''source'',scope||jsonb_build_object(''resourceKind'',''application_field'',''resourceId'',resource,''version'',version_value));\n rows_json:=jsonb_build_array(jsonb_build_object(''row'',NULL,''sources'',jsonb_build_array(envelope->''source'')||sources));\n FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP\n  rows_json:=rows_json||jsonb_build_array(jsonb_build_object(''row'',child#>''{state,values}'',''sources'',jsonb_build_array(child->''source'')||coalesce(child->''sources'',''[]'')));\n END LOOP;\n RETURN jsonb_build_object(''type'',t,''domainId'',domain_id,''domainIdentity'',domain_identity,''domain'',domain,''envelope'',envelope,''rows'',rows