bin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_application_field_dependencies","prorows":1000,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t","t"],"proargnames":["w","kinds","ids","versions","node_version","source"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","1009","2951","1009","25","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF kinds IS NULL OR ids IS NULL OR versions IS NULL\n  OR cardinality(kinds) IS DISTINCT FROM cardinality(ids) OR cardinality(ids) IS DISTINCT FROM cardinality(versions)\n  OR cardinality(ids) NOT BETWEEN 1 AND 100 OR array_position(kinds,NULL) IS NOT NULL\n  OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023''; END IF;\n -- Native roots can acquire field ancestry only through durable lineage edges.\n -- This indexed empty check avoids rewalking every legacy native source in an\n -- installation/workspace that has never produced a field-backed derivative.\n IF NOT ''application_field''=ANY(kinds) AND NOT EXISTS(SELECT 1 FROM scope_derivation_sources s\n  WHERE s.workspace_id=w AND s.source_kind=''application_field'') THEN RETURN; END IF;\n RETURN QUERY SELECT l.version,o.source_scope||jsonb_build_object(''resourceKind'',''application_field'',''resourceId'',o.resource_id,''version'',o.version)\n FROM application_scope_lineage(w,kinds,ids,versions) l\n LEFT JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=l.id AND o.version=l.version\n WHERE l.kind=''application_field'';\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_entity_derivation_source(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_entity_derivation_source","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE actor uuid;\n root jsonb;parent jsonb;context jsonb;policy jsonb;mask jsonb;feedback_message_id uuid;feedback_session_id uuid;expected text;\nBEGIN\n\n IF k=''private_transcript'' THEN\n  IF nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n   OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM private_transcript_observations o WHERE o.workspace_id=w AND o.id=i\n     AND o.user_id=nullif(current_setting(''app.current_user_id'',true),'''')::uuid)\n  THEN RETURN NULL;END IF;\n  RETURN read_private_transcript_source(w,i);\n END IF;\n\n IF k=''office_observation'' THEN\n  IF nullif(current_setting(''app.current_user_id'',true),'''') IS NULL\n   OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n   OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM office_scope_observations o WHERE o.workspace_id=w AND o.id=i\n    AND office_artifact_scope_allows(o.artifact_id,w,false))\n   OR read_office_observation_authority(w,i,nullif(current_setting(''app.current_user_id'',true),'''')::uuid,\n    coalesce(nullif(current_setting(''app.agent_visibility_assistants'',true),''''),''null'')::jsonb) IS NOT TRUE THEN RETURN NULL;END IF;\n  RETURN read_office_observation(w,i);\n END IF;\n -- Recording privacy admission precedes body selection.\n IF NOT recording_source_read_allowed(w,k,i) THEN RETURN NULL;END IF;\n IF k=''feedback_event'' THEN\n  actor:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n  IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n   OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)\n   OR nullif(current_setting(''app.agent_workspace_id'',true),'''') IS NOT NULL AND current_setting(''app.agent_workspace_id'',true)<>w::text\n   OR nullif(current_setting(''app.agent_actor_id'',true),'''') IS NOT NULL AND current_setting(''app.agent_actor_id'',true)<>actor::text\n   OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.analytics_events''::regclass WHERE r.rolname=session_user\n    AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE''))) THEN RETURN NULL;END IF;\n  root:=read_scope_source(w,k,i);\n  IF root IS NULL OR root->>''userId'' IS DISTINCT FROM actor::text OR root->>''held'' IS DISTINCT FROM ''false''\n   OR root->>''version'' IS NULL OR root->>''validTo'' IS NOT NULL OR root->>''retractedAt'' IS NOT NULL\n   OR entity_derivation_envelope_valid(root) IS NOT TRUE OR scope_review_state_held(k,i)\n   OR agent_visibility_allows(w,(root->>''userId'')::uuid,(root->>''assistantId'')::uuid) IS NOT TRUE\n   OR workflow_evidence_envelope_visible(w,root) IS NOT TRUE THEN RETURN NULL;END IF;\n  -- This is only canonical source metadata. The existing negative-only source\n  -- identity, exact own-user floor and full current field masks remain mandatory.\n  context:=application_feedback_query_context(w);\n  IF context IS NULL OR NOT coalesce(to_jsonb(application_feedback_field_keys())<@(context->''read''),false) THEN RETURN NULL;END IF;\n  policy:=application_native_field_contract_for(w,''{\"kind\":\"native\",\"moduleKey\":\"native\"}'',''feedback_event'',i::text);\n  IF policy->>''registered'' IS DISTINCT FROM ''false'' THEN\n   IF policy->>''held'' IS DISTINCT FROM ''false'' OR policy#>>''{metadata,recordVersion}'' IS DISTINCT FROM root->>''version'' THEN RETURN NULL;END IF;\n   mask:=read_native_application_field_mask(w,''{\"kind\":\"native\",\"moduleKey\":\"native\"}'',''feedback_event'',i::text,root->>''version'');\n   IF mask IS NULL OR NOT coalesce(to_jsonb(application_feedback_field_keys())<@(mask->''readFields''),false) THEN RETURN NULL;END IF;\n  END IF;\n  SELECT (a.metadata->>''messageId'')::uuid,a.session_id INTO feedback_message_id,feedback_session_id FROM analytics_events a\n   WHERE a.workspace_id=w AND a.id=i AND a.user_id=actor AND a.scope_version::text=root->>''version'';\n  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM session_messages sm WHERE sm.workspace_id=w AND sm.id=feedback_message_id\n   AND sm.session_id=feedback_session_id AND sm.assistant_id=(root->>''assistantId'')::uuid) THEN RETURN NULL;END IF;\n  SELECT s.source_version INTO expected FROM scope_derivations d JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id\n   WHERE d.workspace_id=w AND d.resource_kind=''feedback_event'' AND d.resource_id=i AND d.resource_version=root->>''version''\n    AND s.source_kind=''session_message'' AND s.source_id=feed