eadable to the canonical validator so holding-state\n  -- rows can reference their exact version. Application validators reject the\n  -- returned `held:true`; only legacy rows with no version are unprovable.\n  IF row_json->>''scope_version'' IS NULL THEN RETURN NULL; END IF;\n  RETURN jsonb_build_object(''workspaceId'',row_json->''workspace_id'',''userId'',row_json->''user_id'',\n    ''assistantId'',row_json->''assistant_id'',''sensitivity'',row_json->''sensitivity'',\n    ''compartments'',row_json->''compartments'',''projectIds'',row_json->''project_ids'',\n    ''resourceKind'',p_kind,''resourceId'',p_id,''version'',row_json->>''scope_version'',\n    ''held'',row_json->''scope_held'',''validTo'',row_json->''valid_to'',''retractedAt'',row_json->''retracted_at'');\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_page(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_page","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF k=''workflow_run'' THEN RETURN workflow_derivation_snapshot(w,i); END IF;\n RETURN read_scope_source_before_workflow_run(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical