h_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2950","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t"],"proargnames":["w","k","i","resource_id"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","25","2950","2950"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n\n IF k=''private_transcript'' THEN\n  RETURN QUERY SELECT id FROM private_transcript_observations WHERE workspace_id=w AND id=i;\n  RETURN;\n END IF;\n\n IF k=''office_observation'' THEN\n  RETURN QUERY SELECT id FROM office_scope_observations WHERE workspace_id=w AND id=i;\n  RETURN;\n END IF;\n IF k=''workflow_run'' THEN\n  RETURN QUERY WITH RECURSIVE consumers(id) AS (\n   SELECT i UNION SELECT s.run_id FROM workflow_run_copy_sources s JOIN consumers c ON c.id=s.source_run_id WHERE s.workspace_id=w\n  ) SELECT id FROM consumers;\n ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_workflow_run(w,k,i); END IF;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"scope_source_ancestors_before_browser_profile(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"scope_source_ancestors_before_browser_profile","prorows":1000,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2950","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t"],"proargnames":["p_workspace","p_kind","p_id","resource_id"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","25","2950","2950"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE tab text; versioned boolean;\nBEGIN\n  -- These are the same workspace-scoped column walks, with static plans.\n  IF p_kind=''memory'' THEN\n    RETURN QUERY WITH RECURSIVE ancestry(id) AS (\n      SELECT id FROM memories WHERE workspace_id=p_workspace AND id=p_id\n      UNION SELECT r.id FROM memories r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace\n    ) SELECT id FROM ancestry;\n    RETURN;\n  ELSIF p_kind=''session_message'' THEN\n    RETURN QUERY SELECT id FROM session_messages WHERE workspace_id=p_workspace AND id=p_id;\n    RETURN;\n  ELSIF p_kind=''session_context_revision'' THEN\n    RETURN QUERY SELECT id FROM session_context_scope_revisions WHERE workspace_id=p_workspace AND id=p_id;\n    RETURN;\n  END IF;\n  IF p_kind IN(''crm_event'',''memory_verification'',''brain_verification'',''correction_audit'') THEN RETURN QUERY SELECT p_id; RETURN; END IF;\n  tab=scope_source_table(p_kind);\n  IF tab IS NULL THEN RAISE EXCEPTION ''scope_evidence_missing''; END IF;\n  SELECT EXISTS(\n    SELECT 1 FROM pg_attribute\n     WHERE attrelid=format(''%I'',tab)::regclass AND attname=''superseded_by'' AND NOT attisdropped\n  ) INTO versioned;\n\n  -- Retain the live canonical mapping and column-shape decision above.\n  -- Schema changes or a replacement mapping use the original dynamic branch.\n  IF p_kind=''workspace_file'' AND tab=''workspace_files'' AND versioned THEN\n    RETURN QUERY WITH RECURSIVE ancestry(id) AS (\n      SELECT id FROM workspace_files WHERE workspace_id=p_workspace AND id=p_id\n      UNION SELECT r.id FROM workspace_files r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace\n    ) SELECT id FROM ancestry;\n    RETURN;\n  END IF;\n  IF NOT versioned THEN\n    RETURN QUERY EXECUTE format(''SELECT id FROM %I WHERE workspace_id=$2 AND id=$1'',tab) USING p_id,p_workspace;\n    RETURN;\n  END IF;\n  RETURN QUERY EXECUTE format(''WITH RECURSIVE ancestry(id) AS (\n    SELECT id FROM %I WHERE workspace_id=$2 AND id=$1\n    UNION SELECT r.id FROM %I r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=$2)\n    SELECT id FROM ancestry'',tab,tab) USING p_id,p_workspace;\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"scope_source_ancestors_before_browser_session(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"scope_source_ancestors_before_browser_session","prorows":1000,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2950","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t"],"proargnames":["w","k","i","resource_id"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","25","2950","2950"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF k=''browser_profile'' THEN\n  RETURN QUERY SELECT id FROM browser_profiles WHERE workspace_id=w AND id=i;\n ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_browser_profile(w,k,i);\n END IF;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"scope_source_ancestors_before_workflow_run(uuid,t