nts'',r.compartments,''projectIds'',r.project_ids)\n   INTO source_row FROM session_context_scope_revisions r JOIN native_turn_frames f ON f.workspace_id=r.workspace_id AND f.id=r.id AND f.session_id=r.session_id\n   WHERE r.workspace_id=NEW.workspace_id AND r.id=expected_id AND r.parent_kind=''turn_frame'' AND r.parent_id=r.id AND NOT r.scope_held;\n  END IF;\n\n  IF TG_RELID=''public.scope_derivation_sources''::regclass AND TG_OP=''INSERT'' AND expected_kind=''application_field'' THEN\n   IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'') FROM pg_proc p WHERE p.oid=''native_turn_field_reference(uuid,uuid,uuid,text)''::regprocedure)=''",{"slot":{"kind":"fingerprint","identity":"native_turn_field_reference(uuid,uuid,uuid,text)"}},"'' THEN\n    source_row:=native_turn_field_reference(NEW.workspace_id,NEW.derivation_id,expected_id,expected_version);\n   END IF;\n  END IF;\n  IF source_row IS NULL THEN\n    source_row=CASE WHEN TG_TABLE_NAME=''scope_resource_states''\n      THEN read_scope_review_source(NEW.workspace_id,expected_kind,expected_id)\n      ELSE read_scope_source(NEW.workspace_id,expected_kind,expected_id) END;\n  END IF;\n  IF source_row IS NULL OR source_row->>''version'' IS DISTINCT FROM expected_version THEN RAISE EXCEPTION ''scope_source_changed''; END IF;\n  IF TG_TABLE_NAME=''scope_derivations'' THEN\n    IF NEW.user_id IS DISTINCT FROM (source_row->>''userId'')::uuid\n      OR NEW.assistant_id IS DISTINCT FROM (source_row->>''assistantId'')::uuid\n      OR NEW.sensitivity<>(source_row->>''sensitivity'')\n      OR NOT(to_jsonb(NEW.compartments) @> (source_row->''compartments'') AND to_jsonb(NEW.compartments) <@ (source_row->''compartments''))\n      OR NOT(to_jsonb(NEW.project_ids) @> (source_row->''projectIds'') AND to_jsonb(NEW.project_ids) <@ (source_row->''projectIds'')) THEN\n      RAISE EXCEPTION ''scope_envelope_mismatch'';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n"],"hashLiteralReview":{"fingerprints":{"native_tur