ad_scope_source_before_application_fields(uuid,text,uuid)','read_scope_source_before_browser_profile(uuid,text,uuid)','read_scope_source_before_browser_session(uuid,text,uuid)','read_scope_source_before_external(uuid,text,uuid)','read_scope_source_before_knowledge_binding(uuid,text,uuid)','read_scope_source_before_page(uuid,text,uuid)','read_scope_source_before_persistent_context(uuid,text,uuid)','read_scope_source_before_routines(uuid,text,uuid)','read_scope_source_before_workflow_run(uuid,text,uuid)','read_session_authority_facts(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean)','read_session_context_revision(uuid,uuid)','read_session_department_facts(uuid,uuid,uuid)','read_session_title_revision(uuid,uuid,uuid)','recording_source_read_allowed(uuid,text,uuid)','recording_transcript_file_allows(uuid)','refuse_quarantined_recording_message()','scope_review_state_held(text,uuid)','scope_source_ancestors(uuid,text,uuid)','scope_source_ancestors_before_browser_profile(uuid,text,uuid)','scope_source_ancestors_before_browser_session(uuid,text,uuid)','scope_source_ancestors_before_workflow_run(uuid,text,uuid)','scope_source_table(text)','scope_source_table_before_knowledge_versions(text)','scope_source_table_before_media(text)','scope_source_table_before_persistent_context(text)','sensitivity_rank(text)','session_context_parent_snapshot(uuid,uuid)','session_context_payload_shape(text,jsonb)','session_context_revision_allowed(uuid,uuid)','session_context_revision_native(uuid,uuid)','session_context_revision_snapshot(uuid,uuid)','session_personal_audience(sessions)','session_project_audience(sessions,boolean)','session_recording_read_allowed(uuid)','session_workspace_audience(sessions)','validate_application_field_dependencies()','validate_page_derivation_dependencies()','validate_scope_resource_reference()','validate_session_context_revision_pair()','validate_workflow_derivation_dependencies()','workflow_evidence_envelope_visible(uuid,jsonb)']::text[]))
 THEN RAISE EXCEPTION 'publication_unreviewed_registry_member';END IF;
 -- Direct source replacements will already equal their successor templates at
 -- the propagation loop. Classify their ORIGINAL consumers before any DDL.
 FOR expected IN SELECT to_jsonb(r) FROM publication_reviewed_contracts r WHERE r.signature IN
  ('publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb)','native_turn_complete_publication()')
  OR EXISTS(SELECT 1 FROM pg_temp.publication_legacy_acl_repairs repair WHERE repair.signature=r.signature) LOOP
  IF EXISTS(SELECT 1 FROM pg_proc c WHERE c.pronamespace<>pg_my_temp_schema() AND NOT pg_is_other_temp_schema(c.pronamespace) AND EXISTS(SELECT 1 FROM pg_namespace caller_namespace WHERE caller_namespace.oid=c.pronamespace AND caller_namespace.nspname NOT IN('pg_catalog','information_schema') AND caller_namespace.nspname!~'^pg_toast')
   AND strpos(c.prosrc,expected->>'fingerprint')>0
   AND NOT EXISTS(SELECT 1 FROM publication_successor_templates t WHERE t.signature=c.oid::regprocedure::text))
  THEN RAISE EXCEPTION 'publication_unreviewed_pin_consumer: %',expected->>'signature';END IF;
 END LOOP;
END $authenticate$;
DO $normalize_legacy_acl$
DECLARE routine record;actual pg_proc;next_row pg_proc;expected jsonb;
BEGIN
 -- The whole predecessor closure and current guards have authenticated, and
 -- ORIGINAL fingerprint consumers have been classified, before this mutation.
 FOR routine IN SELECT repair.signature,repair.canonical_acl,old.metadata,old.fingerprint
  FROM pg_temp.publication_legacy_acl_repairs repair JOIN pg_temp.publication_reviewed_contracts old USING(signature)
  ORDER BY repair.signature COLLATE "C"
 LOOP
  SELECT * INTO STRICT actual FROM pg_proc WHERE oid=to_regprocedure('public.'||routine.signature);
  IF to_jsonb(actual) IS DISTINCT FROM routine.metadata OR EXISTS(SELECT 1 FROM native_turn_contract_helpers h
   WHERE h.signature=routine.signature AND to_jsonb(h.contract) IS DISTINCT FROM routine.metadata)
   OR EXISTS(SELECT 1 FROM native_retained_contract_helpers h WHERE h.signature=routine.signature AND h.fingerprint<>routine.fingerprint)
  THEN RAISE EXCEPTION 'publication_legacy_acl_predecessor_changed: %',routine.signature;END IF;
  expected:=jsonb_set(routine.metadata,'{proacl}',to_jsonb(routine.canonical_acl));
  EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%s FROM app_user',routine.signature);
  SELECT * INTO STRICT next_row FROM pg_proc WHERE oid=(actual).oid;
  IF to_jsonb(next_row) IS DISTINCT FROM expected
  THEN RAISE EXCEPTION 'publication_legacy_acl_successor_changed: %',routine.signature;END IF;
  UPDATE native_turn_contract_helpers h SET contract=next_row WHERE h.signature=routine.signature;
  UPDATE native_retained_contract_helpers h SET fingerprint=encode(sha256(convert_to(expected::text,'UTF8')),'hex')
   WHERE h.signature=routine.signature AND h.fingerprint=routine.fingerprint;
  UPDATE pg_temp.publication_expected_current SET metadata=expected WHERE signature=routine.signature;
 END LOOP;
END $normalize_legacy_acl$;


CREATE TEMP TABLE publication_predecessor_table_snapshot AS SELECT (SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('oid',c.oid,'owner',c.relowner,'kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl) ORDER BY c.oid)
 FROM pg_class c WHERE c.oid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'columns',(SELECT jsonb_agg(jsonb_build_array(attrelid,attnum,attname,atttypid,atttypmod,attnotnull,attidentity,attgenerated,attisdropped,attacl) ORDER BY attrelid,attnum)
 FROM pg_attribute WHERE attnum>0 AND attrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE tgrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE conrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE ev_class=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d WHERE adrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE polrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])))) AS snapshot;
-- [COMP:api/native-turn-frame] Atomic durable publication, attended shared-web slice.
CREATE TABLE public.native_conversation_publications (
 id uuid PRIMARY KEY,
 workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
 session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
 input_message_id uuid NOT NULL REFERENCES session_messages(id) ON DELETE CASCADE,
 actor_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 assistant_id uuid NOT NULL REFERENCES assistants(id) ON DELETE CASCADE,
 turn_token uuid NOT NULL,slot text NOT NULL CHECK(slot='buffered_transcript'),
 command_format integer NOT NULL CHECK(command_format IN(1,2)),
 command_digest text NOT NULL CHECK(command_digest~'^[a-f0-9]{64}$'),
 stopped boolean NOT NULL,
 frame_ids uuid[] NOT NULL CHECK(cardinality(frame_ids) BETWEEN 1 AND 2),
 leader_frame_id uuid NOT NULL,
 expected_output_count integer NOT NULL CHECK(expected_output_count BETWEEN 1 AND 513),
 annotation_user_id uuid,annotation_assistant_id uuid,
 outputs jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,
 requested_stopped boolean,terminal_descriptor jsonb,terminal_outputs jsonb,
 CONSTRAINT native_conversation_terminal_format CHECK(
  command_format=1 AND requested_stopped IS NULL AND terminal_descriptor IS NULL AND terminal_outputs IS NULL
  OR command_format=2 AND requested_stopped IS NOT NULL AND (NOT requested_stopped OR stopped)
   AND (terminal_descriptor IS NULL)=(terminal_outputs IS NULL) AND (NOT stopped OR terminal_descriptor IS NULL)),
 CONSTRAINT native_conversation_publication_slot UNIQUE(workspace_id,session_id,turn_token,slot),
 CONSTRAINT native_conversation_publication_result CHECK((outputs IS NULL)=(completed_at IS NULL))
);
CREATE INDEX native_conversation_publication_discovery ON native_conversation_publications
 (workspace_id,session_id,actor_user_id,assistant_id,created_at,id);
REVOKE ALL ON public.native_conversation_publications FROM PUBLIC,app_user;
ALTER TABLE public.native_conversation_publications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.native_turn_publication_work ADD COLUMN publication_id uuid;
ALTER TABLE public.native_turn_publication_work ADD CONSTRAINT native_turn_publication_operation
 FOREIGN KEY(publication_id) REFERENCES native_conversation_publications(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED;

-- This owner grants neither a serialized invocation nor output delivery authority.
CREATE FUNCTION public.native_conversation_publication_scope(w uuid,s uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 assistant uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;parent jsonb;
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 parent:=lock_native_session_context_publication(w,s);
 IF actor IS NULL OR assistant IS NULL OR NOT EXISTS(SELECT 1 FROM sessions r WHERE r.workspace_id=w AND r.id=s AND (r.visibility = 'workspace' AND r.channel_type = 'web' AND r.anchor_kind = 'none' AND r.app_origin = 'chat' AND r.transient IS NOT TRUE))
  OR NOT EXISTS(SELECT 1 FROM assistants a WHERE a.id=assistant AND a.workspace_id=w)
  OR nullif(current_setting('app.programmatic_candidate',true),'') IS NOT NULL
  OR nullif(current_setting('app.programmatic_publication_batch',true),'') IS NOT NULL
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actorUserId',actor,'assistantId',assistant);
END $body$;

-- Exact output membership and the independent source graph are both required.
-- NULL proof is unavailable, explicit admitted=false is denied. Neither is absence.
CREATE FUNCTION public.native_conversation_publication_result(w uuid,s uuid,i uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r native_conversation_publications;scope jsonb;proof jsonb;roots jsonb;item jsonb;message session_messages;
 revision session_context_scope_revisions;payload jsonb;rows jsonb:='[]';annotation jsonb;source jsonb;
BEGIN
 scope:=native_conversation_publication_scope(w,s);
 SELECT * INTO r FROM native_conversation_publications WHERE workspace_id=w AND session_id=s AND id=i
  AND actor_user_id=(scope->>'actorUserId')::uuid AND assistant_id=(scope->>'assistantId')::uuid;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','unknown');END IF;
 IF r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM 'array' OR jsonb_array_length(r.outputs)<>r.expected_output_count
 THEN RETURN jsonb_build_object('state','unavailable','reason','publication_incomplete');END IF;
 IF EXISTS(SELECT 1 FROM unnest(r.frame_ids) frame WHERE native_turn_frame_pair(w,frame) IS NOT TRUE)
 THEN RETURN jsonb_build_object('state','unavailable','reason','publication_frame_changed');END IF;
 SELECT jsonb_agg(DISTINCT value) INTO roots FROM (
  SELECT jsonb_build_object('kind','session_context_revision','id',frame,'version','1') value FROM unnest(r.frame_ids) frame
  UNION ALL SELECT jsonb_build_object('kind',CASE WHEN n->>'kind'='message_annotation' THEN 'session_context_revision' ELSE 'session_message' END,
   'id',n->'id','version','1') FROM jsonb_array_elements(r.outputs) n
 ) members;
 proof:=capture_conversation_evidence(w,roots);
 IF proof IS NULL THEN RETURN jsonb_build_object('state','unavailable','reason','source_proof_unavailable');END IF;
 IF proof->>'admitted' IS DISTINCT FROM 'true' THEN
  IF proof->>'admitted'='false' THEN RETURN jsonb_build_object('state','denied','reason','source_access_denied');END IF;
  RETURN jsonb_build_object('state','unavailable','reason','source_proof_unavailable');
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(r.outputs) ORDER BY coalesce((value->>'sequence')::integer,0),value->>'id' LOOP
  IF NOT (item->>'frameId')::uuid=ANY(r.frame_ids) THEN RETURN jsonb_build_object('state','unavailable','reason','publication_member_changed');END IF;
  IF item->>'kind'='session_message' THEN
   SELECT * INTO message FROM session_messages WHERE workspace_id=w AND session_id=s AND id=(item->>'id')::uuid;
   payload:=jsonb_build_object('role',message.role,'content',message.content,'channelMessageId',message.channel_message_id,
    'senderUserId',message.sender_user_id,'senderAssistantId',message.sender_assistant_id,'attachments',message.attachments);
   IF message.id IS NULL OR message.scope_version<>1 OR message.scope_held OR message.sequence_num<>(item->>'sequence')::integer
    OR item->>'version'<>'1' OR item->>'payloadDigest' IS DISTINCT FROM encode(sha256(convert_to(payload::text,'UTF8')),'hex')
    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id
     WHERE d.workspace_id=w AND d.id=(item->>'derivationId')::uuid AND d.resource_kind='session_message' AND d.resource_id=message.id
     AND d.resource_version='1' AND e.source_kind='session_context_revision' AND e.source_id=(item->>'frameId')::uuid AND e.source_version='1')
   THEN RETURN jsonb_build_object('state','unavailable','reason','publication_member_changed');END IF;
   source:=jsonb_build_object('workspaceId',w,'userId',message.user_id,'assistantId',message.assistant_id,'sensitivity',message.sensitivity,
    'compartments',message.compartments,'projectIds',message.project_ids,'resourceKind','session_message','resourceId',message.id,'version','1');
   rows:=rows||jsonb_build_array(jsonb_build_object('message',jsonb_build_object('id',message.id,'sessionId',s,'role',message.role,'content',message.content,
    'sequenceNum',message.sequence_num,'createdAt',message.created_at,'replyToText',NULL,'topicLabel',NULL,'topicConfidence',NULL,
    'channelMessageId',message.channel_message_id,'senderUserId',message.sender_user_id,'senderAssistantId',message.sender_assistant_id,'attachments',message.attachments),'source',source));
  ELSIF item->>'kind'='message_annotation' THEN
   SELECT * INTO revision FROM session_context_scope_revisions WHERE workspace_id=w AND session_id=s AND id=(item->>'id')::uuid;
   SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;
   IF revision.id IS NULL OR revision.parent_kind<>'message_annotation' OR revision.parent_id::text IS DISTINCT FROM item->>'parentId'
    OR revision.scope_version<>1 OR revision.scope_held OR item->>'version'<>'1'
    OR item->>'payloadDigest' IS DISTINCT FROM encode(sha256(convert_to(payload::text,'UTF8')),'hex')
    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id
     WHERE d.workspace_id=w AND d.id=(item->>'derivationId')::uuid AND d.resource_kind='session_context_revision' AND d.resource_id=revision.id
     AND d.resource_version='1' AND e.source_kind='session_context_revision' AND e.source_id=(item->>'frameId')::uuid AND e.source_version='1')
   THEN RETURN jsonb_build_object('state','unavailable','reason','publication_member_changed');END IF;
   source:=jsonb_build_object('workspaceId',w,'userId',revision.user_id,'assistantId',revision.assistant_id,'sensitivity',revision.sensitivity,
    'compartments',revision.compartments,'projectIds',revision.project_ids,'resourceKind','session_context_revision','resourceId',revision.id,'version','1');
   annotation:=jsonb_build_object('source',source,'createdAt',revision.created_at,'userId',r.annotation_user_id,'assistantId',r.annotation_assistant_id);
  ELSE RETURN jsonb_build_object('state','unavailable','reason','publication_member_changed');END IF;
 END LOOP;
 RETURN jsonb_build_object('state','committed','outputs',r.outputs,'value',CASE WHEN annotation IS NULL THEN rows ELSE jsonb_build_object('messages',rows,'annotation',annotation) END);
END $body$;

-- Private pre-write identity/digest validation. It cannot register or capture a result.
CREATE FUNCTION public.native_conversation_publication_enter(w uuid,s uuid,operation jsonb,command jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE scope jsonb;r native_conversation_publications;digest text;result jsonb;payloads jsonb;node jsonb;version integer;state text;effective_stopped boolean;
BEGIN
 scope:=native_conversation_publication_scope(w,s);
 version:=CASE operation->'version' WHEN '1'::jsonb THEN 1 WHEN '2'::jsonb THEN 2 END;
 IF version IS NULL OR jsonb_typeof(operation) IS DISTINCT FROM 'object'
  OR operation-(ARRAY['version','operationId','inputMessageId','actorUserId','assistantId','turnToken','slot','stopped']||CASE WHEN version=2 THEN ARRAY['terminalCandidate'] ELSE '{}'::text[] END)<>'{}'
  OR NOT operation ?& (ARRAY['version','operationId','inputMessageId','actorUserId','assistantId','turnToken','slot','stopped']||CASE WHEN version=2 THEN ARRAY['terminalCandidate'] ELSE '{}'::text[] END)
  OR operation->>'slot' IS DISTINCT FROM 'buffered_transcript' OR jsonb_typeof(operation->'stopped') IS DISTINCT FROM 'boolean'
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['operationId','inputMessageId','actorUserId','assistantId','turnToken']) key
   WHERE jsonb_typeof(operation->key) IS DISTINCT FROM 'string' OR NOT pg_input_is_valid(operation->>key,'uuid'))
  OR jsonb_typeof(command) IS DISTINCT FROM 'object' OR command-ARRAY['payloads','producer','sources','target']<>'{}'
  OR NOT command ?& ARRAY['payloads','producer','sources','target']
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 IF operation->>'actorUserId' IS DISTINCT FROM scope->>'actorUserId' OR operation->>'assistantId' IS DISTINCT FROM scope->>'assistantId'
  OR NOT EXISTS(SELECT 1 FROM session_messages m WHERE m.workspace_id=w AND m.session_id=s AND m.id=(operation->>'inputMessageId')::uuid
   AND m.role='user' AND m.sender_user_id=(scope->>'actorUserId')::uuid)
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 payloads:=command->'payloads';
 IF jsonb_typeof(payloads)='object' THEN
  IF payloads-ARRAY['messages','annotation']<>'{}' OR NOT payloads ?& ARRAY['messages','annotation']
   OR jsonb_typeof(payloads->'annotation') IS DISTINCT FROM 'object'
   OR (payloads->'annotation')-ARRAY['kind','parentId','id','content','producer','sources','expectedRevision','expectedGeneration']<>'{}'
   OR NOT (payloads->'annotation') ?& ARRAY['parentId','id','content','producer','sources','expectedRevision','expectedGeneration']
   OR jsonb_typeof(payloads#>'{annotation,sources}') IS DISTINCT FROM 'array'
   OR payloads#>>'{annotation,kind}' IS NOT NULL AND payloads#>>'{annotation,kind}'<>'message_annotation'
   OR payloads#>>'{annotation,parentId}' IS DISTINCT FROM operation->>'inputMessageId'
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  payloads:=payloads->'messages';
 END IF;
 IF jsonb_typeof(payloads) IS DISTINCT FROM 'array' OR jsonb_array_length(payloads)>512
  OR jsonb_array_length(payloads)=0 AND jsonb_typeof(command->'payloads')<>'object'
  OR jsonb_typeof(command->'sources') IS DISTINCT FROM 'array'
  OR jsonb_typeof(command->'target') IS DISTINCT FROM 'object'
  OR (command->'target')-ARRAY['workspaceId','userId','assistantId','sensitivity','compartments','projectIds']<>'{}'
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(command->'sources')
  UNION ALL SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(command->'payloads')='object' THEN command#>'{payloads,annotation,sources}' ELSE '[]'::jsonb END)
 LOOP
  IF jsonb_typeof(node) IS DISTINCT FROM 'object'
   OR NOT node ?& ARRAY['workspaceId','userId','assistantId','sensitivity','compartments','projectIds','resourceKind','resourceId','version']
   OR node-ARRAY['workspaceId','userId','assistantId','sensitivity','compartments','projectIds','resourceKind','resourceId','version']<>'{}'
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 IF version=2 AND native_conversation_terminal_candidate_valid(operation->'terminalCandidate',payloads,(operation->>'assistantId')::uuid) IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 digest:=encode(sha256(convert_to(jsonb_build_object('format',version,'workspaceId',w,'sessionId',s,'operation',operation,'command',command)::text,'UTF8')),'hex');
 SELECT * INTO r FROM native_conversation_publications WHERE id=(operation->>'operationId')::uuid
  OR workspace_id=w AND session_id=s AND turn_token=(operation->>'turnToken')::uuid AND slot='buffered_transcript' FOR UPDATE;
 IF FOUND THEN
  IF r.id<>(operation->>'operationId')::uuid OR r.workspace_id<>w OR r.session_id<>s OR r.input_message_id<>(operation->>'inputMessageId')::uuid
   OR r.actor_user_id<>(scope->>'actorUserId')::uuid OR r.assistant_id<>(scope->>'assistantId')::uuid OR r.turn_token<>(operation->>'turnToken')::uuid OR r.command_digest<>digest
   OR r.command_format<>version OR version=1 AND r.stopped IS DISTINCT FROM (operation->>'stopped')::boolean
   OR version=2 AND r.requested_stopped IS DISTINCT FROM (operation->>'stopped')::boolean
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  result:=native_conversation_publication_result(w,s,r.id);
  IF result->>'state'<>'committed' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  RETURN jsonb_build_object('duplicate',true,'value',CASE WHEN version=2 THEN native_conversation_publication_packet(r.id,result->'value') ELSE result->'value' END);
 END IF;
 IF version=2 THEN
  state:=native_session_turn_publication_state(w,s,(operation->>'turnToken')::uuid);
  IF state NOT IN('active','stopping','stopped') THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  effective_stopped:=(operation->>'stopped')::boolean OR state IN('stopping','stopped');
 ELSE
  IF native_session_turn_publication_allowed(w,s,(operation->>'turnToken')::uuid,(operation->>'stopped')::boolean) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  effective_stopped:=(operation->>'stopped')::boolean;
 END IF;
 RETURN jsonb_build_object('duplicate',false,'digest',digest,'effectiveStopped',effective_stopped);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';
END $body$;

CREATE FUNCTION public.native_conversation_publication_complete() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r native_conversation_publications;
BEGIN
 SELECT * INTO r FROM native_conversation_publications WHERE id=NEW.id;
 IF NOT FOUND THEN RETURN NULL;END IF; -- an authorized cascading erasure owns deletion
 IF r.outputs IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(r.outputs)<>r.expected_output_count OR NOT r.leader_frame_id=ANY(r.frame_ids)
  OR cardinality(r.frame_ids)<>(SELECT count(DISTINCT value) FROM unnest(r.frame_ids) value)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.outputs) n WHERE NOT (n->>'frameId')::uuid=ANY(r.frame_ids))
  OR r.command_format=2 AND (r.stopped AND r.terminal_descriptor IS NOT NULL
   OR native_conversation_terminal_subset(r.terminal_descriptor,r.terminal_outputs,r.outputs) IS NOT TRUE)
  OR native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $body$;
CREATE CONSTRAINT TRIGGER native_conversation_publication_complete AFTER INSERT ON native_conversation_publications
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION native_conversation_publication_complete();

CREATE FUNCTION public.read_native_conversation_publications(w uuid,s uuid,after jsonb DEFAULT NULL,maximum integer DEFAULT 20) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE scope jsonb;cursor_at timestamptz;cursor_id uuid;r native_conversation_publications;result jsonb;items jsonb:='[]';next_cursor jsonb;count integer:=0;diagnostic text;
BEGIN
 scope:=native_conversation_publication_scope(w,s);
 IF maximum IS NULL OR maximum NOT BETWEEN 1 AND 50 OR after IS NOT NULL AND
  (jsonb_typeof(after) IS DISTINCT FROM 'object' OR after-ARRAY['createdAt','operationId']<>'{}' OR NOT after ?& ARRAY['createdAt','operationId']
   OR jsonb_typeof(after->'createdAt') IS DISTINCT FROM 'string' OR jsonb_typeof(after->'operationId') IS DISTINCT FROM 'string'
   OR NOT pg_input_is_valid(after->>'createdAt','timestamptz') OR NOT pg_input_is_valid(after->>'operationId','uuid'))
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 IF after IS NOT NULL THEN cursor_at:=(after->>'createdAt')::timestamptz;cursor_id:=(after->>'operationId')::uuid;END IF;
 FOR r IN SELECT * FROM native_conversation_publications WHERE workspace_id=w AND session_id=s
  AND actor_user_id=(scope->>'actorUserId')::uuid AND assistant_id=(scope->>'assistantId')::uuid
  AND (after IS NULL OR (created_at,id)<(cursor_at,cursor_id)) ORDER BY created_at DESC,id DESC LIMIT maximum+1
 LOOP
  count:=count+1;IF count>maximum THEN EXIT;END IF;
  BEGIN
   result:=native_conversation_publication_result(w,s,r.id)-'value';
   IF result->>'state'='unknown' THEN result:=jsonb_build_object('state','unavailable','reason','publication_changed');END IF;
  EXCEPTION WHEN SQLSTATE '42501' OR SQLSTATE '22023' OR lock_not_available THEN
   GET STACKED DIAGNOSTICS diagnostic=RETURNED_SQLSTATE;
   result:=jsonb_build_object('state','unavailable','reason','source_proof_unavailable:'||diagnostic);
  END;
  items:=items||jsonb_build_array(result||jsonb_build_object('operationId',r.id,'inputMessageId',r.input_message_id,'assistantId',r.assistant_id));
  next_cursor:=jsonb_build_object('createdAt',r.created_at,'operationId',r.id);
 END LOOP;
 IF count<=maximum THEN next_cursor:=NULL;END IF;
 RETURN jsonb_build_object('version',1,'scope',scope,'items',items,'nextCursor',next_cursor);
END $body$;
REVOKE ALL ON FUNCTION native_conversation_publication_scope(uuid,uuid),native_conversation_publication_result(uuid,uuid,uuid),
 native_conversation_publication_enter(uuid,uuid,jsonb,jsonb),native_conversation_publication_complete(),
 read_native_conversation_publications(uuid,uuid,jsonb,integer) FROM PUBLIC,app_user;
GRANT EXECUTE ON FUNCTION read_native_conversation_publications(uuid,uuid,jsonb,integer) TO app_user;
CREATE FUNCTION public.native_conversation_publication_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
BEGIN
 IF (to_jsonb(NEW)-ARRAY['outputs','completed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['outputs','completed_at'])
  OR OLD.outputs IS NOT NULL OR NEW.outputs IS NULL OR NEW.completed_at IS NULL
  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_work work JOIN native_turn_publication_seals seal
   ON seal.transaction_id=work.transaction_id AND seal.frame_id=work.frame_id
   WHERE work.transaction_id=txid_current() AND work.frame_id=OLD.leader_frame_id AND work.publication_id=OLD.id
    AND work.workspace_id=OLD.workspace_id AND work.session_id=OLD.session_id AND work.context=native_turn_context())
  OR native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $body$;
REVOKE ALL ON FUNCTION native_conversation_publication_immutable() FROM PUBLIC,app_user;
CREATE TRIGGER native_conversation_publication_immutable BEFORE UPDATE ON native_conversation_publications
 FOR EACH ROW EXECUTE FUNCTION native_conversation_publication_immutable();

-- Format2 candidate validation and exact native result binding. No text heuristic.
CREATE FUNCTION public.native_session_turn_publication_state(w uuid,s uuid,t uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r sessions;
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 PERFORM lock_native_session_context_publication(w,s);
 SELECT * INTO r FROM sessions WHERE workspace_id=w AND id=s;
 IF NOT FOUND OR t IS NULL OR r.last_turn_lease_token IS DISTINCT FROM t THEN RETURN 'superseded';END IF;
 IF r.turn_lease_token=t AND r.status='running' THEN
  RETURN CASE WHEN r.cancel_requested_at IS NULL THEN 'active' ELSE 'stopping' END;
 END IF;
 IF r.turn_lease_token IS NULL AND r.turn_end_reason='stopped_by_user' THEN RETURN 'stopped';END IF;
 RETURN 'superseded';
END $body$;

CREATE FUNCTION public.native_conversation_terminal_candidate_valid(candidate jsonb,payloads jsonb,answering uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE m jsonb;row jsonb;previous integer:=-1;ordinal integer;origins text[]:='{}';
BEGIN
 IF candidate IS NULL OR candidate='null'::jsonb THEN RETURN true;END IF;
 IF jsonb_typeof(candidate) IS DISTINCT FROM 'object'
  OR candidate-ARRAY['version','disposition','invocationId','projection','formatter','format','textDigest','members']<>'{}'
  OR NOT candidate ?& ARRAY['version','disposition','invocationId','projection','formatter','format','textDigest','members']
  OR candidate->'version'<>'1'::jsonb OR candidate->>'disposition' IS DISTINCT FROM 'reply'
  OR candidate->>'projection' IS DISTINCT FROM 'persistable_response_v1' OR candidate->>'formatter' IS DISTINCT FROM 'turn_output_v1'
  OR candidate->>'format' NOT IN('compact','channel') OR candidate->>'format' IS NULL
  OR jsonb_typeof(candidate->'invocationId') IS DISTINCT FROM 'string' OR NOT pg_input_is_valid(candidate->>'invocationId','uuid') OR length(candidate->>'invocationId')<>36
  OR candidate->>'textDigest' !~ '^[a-f0-9]{64}$' OR candidate->>'textDigest' IS NULL
  OR jsonb_typeof(candidate->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(candidate->'members') NOT BETWEEN 1 AND 512
  OR jsonb_typeof(payloads) IS DISTINCT FROM 'array' OR jsonb_array_length(payloads)>512
 THEN RETURN false;END IF;
 FOR m IN SELECT value FROM jsonb_array_elements(candidate->'members') LOOP
  IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR m-ARRAY['origin','revision','snapshotDigest','contentDigest','commandOrdinal']<>'{}'
   OR NOT m ?& ARRAY['origin','revision','snapshotDigest','contentDigest','commandOrdinal']
   OR jsonb_typeof(m->'origin') IS DISTINCT FROM 'string' OR NOT pg_input_is_valid(m->>'origin','uuid') OR length(m->>'origin')<>36 OR m->>'origin'=ANY(origins)
   OR jsonb_typeof(m->'revision') IS DISTINCT FROM 'number' OR NOT pg_input_is_valid(m->>'revision','integer')
   OR jsonb_typeof(m->'commandOrdinal') IS DISTINCT FROM 'number' OR NOT pg_input_is_valid(m->>'commandOrdinal','integer')
   OR m->>'snapshotDigest' !~ '^[a-f0-9]{64}$' OR m->>'snapshotDigest' IS NULL
   OR m->>'contentDigest' !~ '^[a-f0-9]{64}$' OR m->>'contentDigest' IS NULL
  THEN RETURN false;END IF;
  ordinal:=(m->>'commandOrdinal')::integer;
  IF (m->>'revision')::integer<1 OR ordinal<=previous OR ordinal>=jsonb_array_length(payloads) THEN RETURN false;END IF;
  previous:=ordinal;origins:=origins||(m->>'origin');row:=payloads->ordinal;
  IF row->>'role' IS DISTINCT FROM 'assistant' OR row->>'senderAssistantId' IS DISTINCT FROM answering::text
   OR jsonb_typeof(row->'content') IS DISTINCT FROM 'array'
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(row->'content') b WHERE b->>'type' IN('tool_use','host_observation'))
  THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $body$;

CREATE FUNCTION public.native_conversation_terminal_subset(descriptor jsonb,selected jsonb,outputs jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE m jsonb;n jsonb;position integer:=0;seen uuid[]:='{}';
BEGIN
 IF descriptor IS NULL THEN RETURN selected IS NULL;END IF;
 IF jsonb_typeof(selected) IS DISTINCT FROM 'array' OR jsonb_array_length(selected)<>jsonb_array_length(descriptor->'members')
  OR jsonb_array_length(selected) NOT BETWEEN 1 AND 512 THEN RETURN false;END IF;
 FOR m IN SELECT value FROM jsonb_array_elements(descriptor->'members') LOOP
  n:=selected->position;position:=position+1;
  IF n-ARRAY['origin','revision','commandOrdinal','kind','id','version','frameId','derivationId','sequence','payloadDigest']<>'{}'
   OR NOT n ?& ARRAY['origin','revision','commandOrdinal','kind','id','version','frameId','derivationId','sequence','payloadDigest']
   OR n->'origin' IS DISTINCT FROM m->'origin' OR n->'revision' IS DISTINCT FROM m->'revision'
   OR n->'commandOrdinal' IS DISTINCT FROM m->'commandOrdinal' OR n->>'kind' IS DISTINCT FROM 'session_message'
   OR NOT pg_input_is_valid(n->>'id','uuid') OR (n->>'id')::uuid=ANY(seen)
   OR (SELECT count(*) FROM jsonb_array_elements(outputs) o WHERE o=n-ARRAY['origin','revision','commandOrdinal'])<>1
  THEN RETURN false;END IF;
  seen:=seen||(n->>'id')::uuid;
 END LOOP;
 RETURN true;
END $body$;

CREATE FUNCTION public.native_conversation_publication_packet(i uuid,value jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r native_conversation_publications;
BEGIN
 SELECT * INTO STRICT r FROM native_conversation_publications WHERE id=i;
 IF r.command_format<>2 THEN RETURN value;END IF;
 RETURN jsonb_build_object('value',value,'publication',jsonb_build_object('operationId',r.id,'commandDigest',r.command_digest,
  'requestedStopped',r.requested_stopped,'stopped',r.stopped,'terminalDescriptor',r.terminal_descriptor,'terminalOutputs',r.terminal_outputs));
END $body$;
REVOKE ALL ON FUNCTION public.native_session_turn_publication_state(uuid,uuid,uuid),
 public.native_conversation_terminal_candidate_valid(jsonb,jsonb,uuid),public.native_conversation_terminal_subset(jsonb,jsonb,jsonb),
 public.native_conversation_publication_packet(uuid,jsonb) FROM PUBLIC,app_user;
GRANT EXECUTE ON FUNCTION public.native_session_turn_publication_state(uuid,uuid,uuid) TO app_user;

-- [COMP:api/turn-kernel] Canonical original-token transition owner.
CREATE FUNCTION public.native_session_public_turn_id(w uuid,s uuid,t uuid)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
BEGIN
 RETURN CASE WHEN w IS NULL OR s IS NULL OR t IS NULL THEN NULL ELSE
  encode(sha256(convert_to('use-brian/session-turn/v1:'||w::text||':'||s::text||':'||t::text,'UTF8')),'hex') END;
END $body$;

-- Private immutable-metadata classifier. Call only after locking the exact
-- current session owner; it never reads source graphs or protected content.
CREATE FUNCTION public.native_session_expired_turn_outcome(w uuid,s uuid,t uuid,a uuid,cancelled boolean)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE publication public.native_conversation_publications;
BEGIN
 IF cancelled THEN RETURN 'stopped_by_user';END IF;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE
 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 IF w IS NULL OR t IS NULL OR a IS NULL THEN RETURN 'stalled_reclaimed';END IF;
 SELECT * INTO publication FROM public.native_conversation_publications p
  WHERE p.workspace_id=w AND p.session_id=s AND p.turn_token=t
   AND p.slot='buffered_transcript';
 IF NOT FOUND OR publication.command_format=1 THEN RETURN 'stalled_reclaimed';END IF;
 IF publication.command_format<>2 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 IF publication.completed_at IS NULL OR publication.outputs IS NULL OR jsonb_typeof(publication.outputs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(publication.outputs)<>publication.expected_output_count
 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 IF publication.assistant_id<>a OR publication.stopped OR publication.terminal_descriptor IS NULL THEN RETURN 'stalled_reclaimed';END IF;
 IF publication.outputs IS NULL OR publication.terminal_outputs IS NULL
  OR jsonb_typeof(publication.terminal_outputs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(publication.terminal_outputs)=0
  OR jsonb_array_length(publication.terminal_outputs)<>jsonb_array_length(publication.terminal_descriptor->'members')
 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 -- The authenticated independent completion owner validates descriptor/member
 -- shape, exact roots/native references and the entire actual output closure
 -- before this immutable row can commit. Current access does not alter that fact.
 RETURN 'publication_recovered';
END $body$;

-- One lock/fresh-read owner for claim, explicit reclaim and Stop capture.
-- This does not authorize the requesting user; the existing route/read owner
-- remains mandatory. It is callable only by the existing private owner pool.
CREATE FUNCTION public.native_session_turn_transition(
 s uuid,action text,answering_assistant uuid,started_at timestamp with time zone,
 stale_after_ms integer,expected_token uuid,expected_public_turn_id text,fence_token boolean
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r public.sessions;w uuid;original_token uuid;original_public_id text;outcome text;
 recovered jsonb;next_token uuid;resting text;now_at timestamptz;
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE
 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 IF action IS NULL OR action NOT IN('claim','reclaim','cancel') OR stale_after_ms IS NULL OR stale_after_ms<1
  OR fence_token IS NULL OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'invalid_turn_transition' USING ERRCODE='22023';END IF;
 SELECT workspace_id INTO w FROM public.sessions WHERE id=s;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Same order as canonical native publication, never session then workspace.
 IF w IS NOT NULL THEN
  PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;
  IF NOT FOUND THEN RETURN NULL;END IF;
 END IF;
 -- VOLATILE PL/pgSQL uses a new READ COMMITTED snapshot here after lock wait.
 SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION 'turn_scope_changed' USING ERRCODE='40001';END IF;
 now_at:=clock_timestamp();original_token:=r.turn_lease_token;
 original_public_id:=public.native_session_public_turn_id(w,s,original_token);
 IF fence_token AND original_token IS DISTINCT FROM expected_token
  OR expected_public_turn_id IS NOT NULL AND original_public_id IS DISTINCT FROM expected_public_turn_id
 THEN RETURN jsonb_build_object('state','superseded');END IF;
 IF action='cancel' THEN
  IF r.status<>'running' THEN RETURN jsonb_build_object('state','not_running');END IF;
  IF original_token IS NULL THEN
   UPDATE public.sessions SET status='idle',turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason='stopped_by_user',last_active_at=now_at WHERE id=s;
   RETURN jsonb_build_object('state','stopped_legacy','turnId',NULL,'reason','stopped_by_user');
  END IF;
  UPDATE public.sessions SET cancel_requested_at=coalesce(cancel_requested_at,now_at)
   WHERE id=s AND turn_lease_token=original_token AND status='running';
  RETURN jsonb_build_object('state','cancel_requested','token',original_token,'turnId',original_public_id,
   'stale',coalesce(r.turn_heartbeat_at,r.last_active_at)<now_at-make_interval(secs=>stale_after_ms/1000.0));
 END IF;
 IF r.status='running' THEN
  IF coalesce(r.turn_heartbeat_at,r.last_active_at)>=now_at-make_interval(secs=>stale_after_ms/1000.0)
  THEN RETURN jsonb_build_object('state','busy');END IF;
  outcome:=public.native_session_expired_turn_outcome(r.workspace_id,r.id,r.turn_lease_token,
   CASE WHEN r.last_turn_lease_token=r.turn_lease_token THEN r.turn_assistant_id END,r.cancel_requested_at IS NOT NULL);
  resting:=CASE WHEN outcome IN('publication_recovered','stopped_by_user') THEN 'idle' ELSE 'timeout' END;
  UPDATE public.sessions SET status=resting,turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,
   turn_end_reason=outcome,last_active_at=now_at WHERE id=s;
  recovered:=jsonb_build_object('turnId',original_public_id,'reason',outcome);
 ELSIF action='reclaim' THEN RETURN jsonb_build_object('state','not_running');
 END IF;
 IF action='reclaim' THEN RETURN jsonb_build_object('state','recovered','recovered',recovered);END IF;
 next_token:=gen_random_uuid();
 UPDATE public.sessions SET status='running',last_active_at=now_at,turn_lease_token=next_token,
  turn_started_at=coalesce(started_at,now_at),turn_heartbeat_at=now_at,cancel_requested_at=NULL,
  turn_end_reason=NULL,turn_assistant_id=answering_assistant WHERE id=s;
 RETURN jsonb_build_object('state','claimed','token',next_token,
  'turnId',public.native_session_public_turn_id(w,s,next_token),'recovered',recovered);
END $body$;

-- Release is token-specific and Stop wins even if a remote holder finishes
-- before its next heartbeat has delivered the cancellation to local JS.
CREATE FUNCTION public.native_session_release_turn(s uuid,t uuid,requested_reason text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE r public.sessions;w uuid;reason text;
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE
 THEN RAISE EXCEPTION 'terminal_control_unavailable' USING ERRCODE='55000';END IF;
 IF t IS NULL OR requested_reason IS NULL OR requested_reason NOT IN('completed','failed','stopped_by_user','stalled_reclaimed','timeout')
 THEN RAISE EXCEPTION 'invalid_turn_release' USING ERRCODE='22023';END IF;
 SELECT workspace_id INTO w FROM public.sessions WHERE id=s;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF w IS NOT NULL THEN PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;END IF;
 SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;
 IF NOT FOUND OR r.status<>'running' OR r.turn_lease_token IS DISTINCT FROM t THEN RETURN NULL;END IF;
 IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION 'turn_scope_changed' USING ERRCODE='40001';END IF;
 reason:=CASE WHEN r.cancel_requested_at IS NOT NULL THEN 'stopped_by_user' ELSE requested_reason END;
 UPDATE public.sessions SET status=CASE WHEN reason='failed' THEN 'failed' WHEN reason IN('completed','stopped_by_user','publication_recovered') THEN 'idle' ELSE 'timeout' END,
  turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=reason,last_active_at=clock_timestamp()
  WHERE id=s AND turn_lease_token=t;
 RETURN jsonb_build_object('turnId',public.native_session_public_turn_id(w,s,t),'reason',reason);
END $body$;

REVOKE ALL ON FUNCTION public.native_session_public_turn_id(uuid,uuid,uuid),
 public.native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean),
 public.native_session_turn_transition(uuid,text,uuid,timestamp with time zone,integer,uuid,text,boolean),
 public.native_session_release_turn(uuid,uuid,text) FROM PUBLIC,app_user;

-- [COMP:api/native-turn-frame] One publication owner for an annotation and transcript.
CREATE OR REPLACE FUNCTION public.publish_native_session_message_batch(w uuid,s uuid,payloads jsonb,producer text,sources jsonb,target jsonb,operation jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET plan_cache_mode=force_generic_plan AS $function$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;parent jsonb;payload jsonb;node jsonb;
 envelope boolean:=jsonb_typeof(payloads)='object';annotation_command jsonb;session_row sessions;previous uuid;
 a_kind text:='message_annotation';a_parent uuid;a_id uuid;a_payload jsonb;a_producer text;a_sources jsonb;a_revision uuid;a_generation bigint;a_target jsonb;
 commands jsonb:='[]';prepared jsonb;a_prepared jsonb;t_prepared jsonb;
 a_frame uuid:=gen_random_uuid();t_frame uuid:=gen_random_uuid();leader uuid;compound boolean;
 a_frame_payload jsonb;t_frame_payload jsonb;a_scope jsonb;t_scope jsonb;a_retained jsonb;t_retained jsonb;
 a_tier text;t_tier text;a_teams text[];t_teams text[];a_projects uuid[];t_projects uuid[];
 next_sequence integer;results jsonb;annotation_result jsonb;registration jsonb;original_command jsonb:=jsonb_build_object('payloads',payloads,'producer',producer,'sources',sources,'target',target);
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF operation IS NOT NULL THEN
  registration:=native_conversation_publication_enter(w,s,operation,original_command);
  IF registration->>'duplicate'='true' THEN RETURN registration->'value';END IF;
 END IF;
 IF envelope THEN
  IF payloads-ARRAY['messages','annotation']<>'{}' OR NOT payloads ?& ARRAY['messages','annotation']
   OR jsonb_typeof(payloads->'annotation') IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  annotation_command:=payloads->'annotation';payloads:=payloads->'messages';
  IF annotation_command-ARRAY['kind','parentId','id','content','producer','sources','expectedRevision','expectedGeneration']<>'{}'
   OR NOT annotation_command ?& ARRAY['parentId','id','content','producer','sources','expectedRevision','expectedGeneration']
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  IF annotation_command ? 'kind' THEN a_kind:=annotation_command->>'kind';END IF;
  IF a_kind IS NULL OR a_kind NOT IN('message_annotation','session_title')
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  a_parent:=(annotation_command->>'parentId')::uuid;a_id:=(annotation_command->>'id')::uuid;
  a_payload:=annotation_command->'content';a_producer:=annotation_command->>'producer';a_sources:=annotation_command->'sources';
  a_revision:=(annotation_command->>'expectedRevision')::uuid;a_generation:=(annotation_command->>'expectedGeneration')::bigint;
 END IF;
 IF jsonb_typeof(payloads) IS DISTINCT FROM 'array' OR jsonb_array_length(payloads)>512
  OR jsonb_array_length(payloads)=0 AND annotation_command IS NULL
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 parent:=lock_native_session_context_publication(w,s);
 IF annotation_command IS NOT NULL THEN
 IF a_parent IS NULL OR a_id IS NULL OR session_context_payload_shape(a_kind,a_payload) IS NOT TRUE
  OR length(btrim(a_producer)) NOT BETWEEN 1 AND 256
  OR jsonb_typeof(a_sources) IS DISTINCT FROM 'array' OR jsonb_array_length(a_sources) NOT BETWEEN 1 AND 4096
  OR (SELECT count(DISTINCT(n->>'resourceKind',n->>'resourceId')) FROM jsonb_array_elements(a_sources) n)<>jsonb_array_length(a_sources)
  OR a_kind='session_title' AND jsonb_array_length(payloads)<>0
  OR a_kind='message_annotation' AND (NOT EXISTS(SELECT 1 FROM session_messages WHERE workspace_id=w AND session_id=s AND id=a_parent)
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a_sources) n WHERE n->>'resourceKind'='session_message' AND n->>'resourceId'=a_parent::text))
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT session_row FROM sessions WHERE workspace_id=w AND id=s;
 IF a_kind='session_title' THEN
  IF a_parent<>s OR (a_payload->>'manual')::boolean IS FALSE AND session_row.title_manually_set THEN
   RETURN jsonb_build_object('messages','[]'::jsonb,'annotation',NULL);END IF;
  SELECT scope_revision_id INTO previous FROM session_title_heads WHERE workspace_id=w AND session_id=s;
 ELSE
  SELECT scope_revision_id INTO previous FROM session_message_annotation_heads WHERE workspace_id=w AND session_id=s AND message_id=a_parent;
 END IF;
 IF a_generation IS NOT NULL AND session_row.session_context_generation<>a_generation OR previous IS DISTINCT FROM a_revision
 THEN RETURN jsonb_build_object('messages','[]'::jsonb,'annotation',NULL);END IF;
 SELECT jsonb_agg(jsonb_build_object('workspaceId',n->'workspaceId','userId',n->'userId','assistantId',n->'assistantId',
  'sensitivity',n->'sensitivity','compartments',n->'compartments','projectIds',n->'projectIds',
  'resourceKind',n->'resourceKind','resourceId',n->'resourceId','version',n->'version') ORDER BY ordinal)
 INTO a_sources FROM jsonb_array_elements(a_sources) WITH ORDINALITY original(n,ordinal);

  a_target:=jsonb_build_object('workspaceId',w,'userId',parent->'userId','assistantId',NULL,'sensitivity',parent->'sensitivity','compartments',parent->'compartments','projectIds',parent->'projectIds');
  commands:=commands||jsonb_build_array(jsonb_build_object('producer',a_producer,'sources',a_sources,'target',a_target)
   ||CASE WHEN a_kind='session_title' THEN jsonb_build_object('purpose',a_kind) ELSE '{}'::jsonb END);
 END IF;
 FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR NOT payload ?& ARRAY['role','content','channelMessageId','senderUserId','senderAssistantId','attachments']
  OR payload-ARRAY['role','content','channelMessageId','senderUserId','senderAssistantId','attachments']<>'{}'
  OR payload->>'role' NOT IN('user','assistant') OR jsonb_typeof(payload->'role') IS DISTINCT FROM 'string'
  OR jsonb_typeof(payload->'attachments') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'attachments')>100
  OR jsonb_typeof(payload->'channelMessageId') NOT IN('null','string')
  OR jsonb_typeof(payload->'senderUserId') NOT IN('null','string') OR jsonb_typeof(payload->'senderAssistantId') NOT IN('null','string')
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256
  OR entity_derivation_envelope_valid(target) IS NOT TRUE OR target->>'workspaceId' IS DISTINCT FROM w::text
  OR target->>'assistantId' IS NOT NULL OR target->>'userId' IS NOT NULL AND target->>'userId' IS DISTINCT FROM actor::text
  OR parent->>'userId' IS NOT NULL AND parent->>'userId' IS DISTINCT FROM target->>'userId'
  OR payload->>'senderUserId' IS NOT NULL AND payload->>'senderUserId' IS DISTINCT FROM actor::text
  OR payload->>'senderAssistantId' IS NOT NULL AND (payload->>'role'<>'assistant'
   OR payload->>'senderAssistantId' IS DISTINCT FROM nullif(current_setting('app.v2_assistant_id',true),'')) THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 IF jsonb_array_length(payloads)>0 THEN
 SELECT jsonb_agg(jsonb_build_object('workspaceId',n->'workspaceId','userId',n->'userId','assistantId',n->'assistantId',
  'sensitivity',n->'sensitivity','compartments',n->'compartments','projectIds',n->'projectIds',
  'resourceKind',n->'resourceKind','resourceId',n->'resourceId','version',n->'version') ORDER BY ordinal)
 INTO sources FROM jsonb_array_elements(sources) WITH ORDINALITY original(n,ordinal);
 commands:=commands||jsonb_build_array(jsonb_build_object('producer',producer,'sources',sources,'target',target));
 END IF;
 prepared:=conversation_prepare_publications(w,s,commands);
 IF prepared IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF annotation_command IS NOT NULL THEN
  a_prepared:=prepared->0;a_scope:=a_prepared->'scope';a_retained:=a_prepared->'retained';a_tier:=a_scope->>'sensitivity';
  a_teams:=ARRAY(SELECT jsonb_array_elements_text(a_scope->'compartments'));a_projects:=ARRAY(SELECT jsonb_array_elements_text(a_scope->'projectIds')::uuid);
  a_frame_payload:=jsonb_build_object('kind','native_turn_frame_v2','originalSources',a_sources,'declaredSources',a_retained);
 END IF;
 IF jsonb_array_length(payloads)>0 THEN
  t_prepared:=prepared->(jsonb_array_length(prepared)-1);t_scope:=t_prepared->'scope';t_retained:=t_prepared->'retained';t_tier:=t_scope->>'sensitivity';
  t_teams:=ARRAY(SELECT jsonb_array_elements_text(t_scope->'compartments'));t_projects:=ARRAY(SELECT jsonb_array_elements_text(t_scope->'projectIds')::uuid);
  t_frame_payload:=jsonb_build_object('kind','native_turn_frame_v2','originalSources',sources,'declaredSources',t_retained);
 END IF;
 FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP
 FOR node IN SELECT value FROM jsonb_array_elements(payload->'attachments') LOOP
  IF jsonb_typeof(node) IS DISTINCT FROM 'object' OR node->>'workspaceId' IS DISTINCT FROM w::text
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t_retained) input WHERE input->>'resourceKind'='workspace_file' AND input->>'resourceId'=node->>'fileId') THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 END LOOP;

 compound:=annotation_command IS NOT NULL AND jsonb_array_length(payloads)>0;
 leader:=CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame ELSE a_frame END;
 IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation DEFERRED;END IF;
 INSERT INTO native_turn_publication_work(transaction_id,workspace_id,frame_id,session_id,context,original_sources,prepared,completion_owner,publication_id)
 SELECT txid_current(),w,a_frame,s,native_turn_context(),a_sources,a_prepared-'proof',CASE WHEN compound THEN leader END,(operation->>'operationId')::uuid WHERE annotation_command IS NOT NULL
 UNION ALL SELECT txid_current(),w,t_frame,s,native_turn_context(),sources,t_prepared-'proof',CASE WHEN compound THEN leader END,(operation->>'operationId')::uuid WHERE jsonb_array_length(payloads)>0;
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 SELECT coalesce(max(sequence_num),0) INTO next_sequence FROM session_messages WHERE session_id=s;
 WITH a_frame_revision AS (
  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)
  SELECT a_frame,w,s,'turn_frame',a_frame,(a_scope->>'userId')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_frame_payload::text,'UTF8')),'hex') WHERE annotation_command IS NOT NULL RETURNING id
 ), a_frame_record AS (
  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)
  SELECT id_workspace,id_frame,s,2,encode(sha256(convert_to(a_frame_payload::text,'UTF8')),'hex') FROM (SELECT w id_workspace,id id_frame FROM a_frame_revision) ready RETURNING id
 ), a_frame_contents AS (
  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)
  SELECT w,id,a_frame_payload FROM a_frame_record RETURNING revision_id
 ), a_frame_declaration AS (
  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'session_context_revision',a_frame,'1',a_producer,(a_scope->>'userId')::uuid,NULL,a_tier,a_teams,a_projects,revision
  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_frame_contents) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id
 ), a_frame_edges AS (
  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,d.id,n->>'resourceKind',(n->>'resourceId')::uuid,n->>'version' FROM a_frame_declaration d CROSS JOIN jsonb_array_elements(a_retained) n
  ORDER BY n->>'resourceKind',n->>'resourceId' RETURNING derivation_id
 ), a_annotation AS (
  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)
  SELECT a_id,w,s,a_kind,a_parent,(a_scope->>'userId')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_payload::text,'UTF8')),'hex')
  FROM(SELECT count(*) FROM a_frame_edges) ready WHERE annotation_command IS NOT NULL RETURNING id,created_at
 ), a_annotation_content AS (
  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content) SELECT w,id,a_payload FROM a_annotation RETURNING revision_id
 ), a_head AS (
  INSERT INTO session_message_annotation_heads(message_id,workspace_id,session_id,scope_revision_id)
  SELECT a_parent,w,s,revision_id FROM a_annotation_content WHERE a_kind='message_annotation' ON CONFLICT(message_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING message_id
 ), a_title_head AS (
  INSERT INTO session_title_heads(workspace_id,session_id,scope_revision_id)
  SELECT w,s,revision_id FROM a_annotation_content WHERE a_kind='session_title'
  ON CONFLICT(session_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING session_id
 ), a_generation AS (
  UPDATE sessions SET session_context_generation=session_context_generation+1,
   title=CASE WHEN a_kind='session_title' THEN NULL ELSE title END,
   title_manually_set=CASE WHEN a_kind='session_title' THEN (a_payload->>'manual')::boolean ELSE title_manually_set END
  FROM(SELECT count(*) FROM a_head) ready CROSS JOIN(SELECT count(*) FROM a_title_head) title_ready
  WHERE workspace_id=w AND id=s AND annotation_command IS NOT NULL RETURNING id
 ), a_declaration AS (
  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'session_context_revision',a_id,'1',a_producer,(a_scope->>'userId')::uuid,NULL,a_tier,a_teams,a_projects,revision
  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_generation) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id
 ), a_annotation_edge AS (
  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,id,'session_context_revision',a_frame,'1' FROM a_declaration RETURNING derivation_id
 ), t_frame_revision AS (
  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)
  SELECT t_frame,w,s,'turn_frame',t_frame,(t_scope->>'userId')::uuid,NULL,t_tier,t_teams,t_projects,encode(sha256(convert_to(t_frame_payload::text,'UTF8')),'hex') WHERE jsonb_array_length(payloads)>0 RETURNING id
 ), t_frame_record AS (
  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)
  SELECT w,id,s,2,encode(sha256(convert_to(t_frame_payload::text,'UTF8')),'hex') FROM t_frame_revision RETURNING id
 ), t_frame_contents AS (
  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)
  SELECT w,id,t_frame_payload FROM t_frame_record RETURNING revision_id
 ), t_frame_declaration AS (
  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'session_context_revision',t_frame,'1',producer,(t_scope->>'userId')::uuid,NULL,t_tier,t_teams,t_projects,revision
  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM t_frame_contents) ready WHERE workspace_id=w AND jsonb_array_length(payloads)>0 RETURNING id
 ), t_frame_edges AS (
  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,d.id,n->>'resourceKind',(n->>'resourceId')::uuid,n->>'version' FROM t_frame_declaration d CROSS JOIN jsonb_array_elements(t_retained) n
  ORDER BY n->>'resourceKind',n->>'resourceId' RETURNING derivation_id
 ), t_written AS (
  INSERT INTO session_messages(session_id,role,content,sequence_num,channel_message_id,sender_user_id,sender_assistant_id,attachments,
   workspace_id,user_id,assistant_id,sensitivity,compartments,project_ids,scope_version,scope_held)
  SELECT s,n.value->>'role',n.value->'content',next_sequence+n.ordinality,n.value->>'channelMessageId',
   (n.value->>'senderUserId')::uuid,(n.value->>'senderAssistantId')::uuid,n.value->'attachments',w,(target->>'userId')::uuid,NULL,t_tier,t_teams,t_projects,1,false
  FROM jsonb_array_elements(payloads) WITH ORDINALITY n(value,ordinality) CROSS JOIN(SELECT count(*) FROM t_frame_edges) ready
  ORDER BY n.ordinality RETURNING *
 ), t_declarations AS (
  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'session_message',m.id,'1',producer,(target->>'userId')::uuid,NULL,t_tier,t_teams,t_projects,p.revision
  FROM t_written m CROSS JOIN workspace_access_policies p WHERE p.workspace_id=w RETURNING id,resource_id
 ), t_message_edges AS (
  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,id,'session_context_revision',t_frame,'1' FROM t_declarations RETURNING derivation_id
 ), output_rows AS (
  SELECT a_frame frame_id,jsonb_build_object('kind',a_kind,'id',a_id,'parentId',a_parent,'derivationId',d.id,
   'payloadDigest',encode(sha256(convert_to(a_payload::text,'UTF8')),'hex')) value
  FROM a_declaration d CROSS JOIN(SELECT count(*) FROM a_annotation_edge) ready
  UNION ALL SELECT t_frame,jsonb_build_object('id',m.id,'derivationId',d.id,'sequence',m.sequence_num,
   'payloadDigest',encode(sha256(convert_to(jsonb_build_object('role',m.role,'content',m.content,'channelMessageId',m.channel_message_id,
    'senderUserId',m.sender_user_id,'senderAssistantId',m.sender_assistant_id,'attachments',m.attachments)::text,'UTF8')),'hex'))
  FROM t_written m JOIN t_declarations d ON d.resource_id=m.id CROSS JOIN(SELECT count(*) FROM t_message_edges) ready
 ), seal AS (
  INSERT INTO native_turn_publication_seals(transaction_id,frame_id,outputs)
  SELECT txid_current(),leader,jsonb_agg(value||CASE WHEN compound THEN jsonb_build_object('frameId',frame_id) ELSE '{}'::jsonb END ORDER BY frame_id,value::text) FROM output_rows
  RETURNING native_turn_publication_seals.transaction_id,native_turn_publication_seals.frame_id
 ), debt AS (
  INSERT INTO native_turn_publication_debt SELECT seal.transaction_id,o.frame_id FROM seal CROSS JOIN(SELECT DISTINCT frame_id FROM output_rows) o
  RETURNING native_turn_publication_debt.frame_id
 ), registration AS (
  INSERT INTO native_conversation_publications(id,workspace_id,session_id,input_message_id,actor_user_id,assistant_id,turn_token,slot,
   command_format,command_digest,stopped,frame_ids,leader_frame_id,expected_output_count,annotation_user_id,annotation_assistant_id,requested_stopped,terminal_descriptor,terminal_outputs)
  SELECT (operation->>'operationId')::uuid,w,s,(operation->>'inputMessageId')::uuid,(operation->>'actorUserId')::uuid,(operation->>'assistantId')::uuid,
   (operation->>'turnToken')::uuid,'buffered_transcript',(operation->>'version')::integer,registration->>'digest',(registration->>'effectiveStopped')::boolean,
   ARRAY(SELECT frame FROM unnest(ARRAY[CASE WHEN annotation_command IS NOT NULL THEN a_frame END,CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame END]) frame WHERE frame IS NOT NULL ORDER BY frame),
   leader,jsonb_array_length(payloads)+CASE WHEN annotation_command IS NOT NULL THEN 1 ELSE 0 END,session_row.user_id,session_row.assistant_id,
   CASE WHEN operation->'version'='2'::jsonb THEN (operation->>'stopped')::boolean END,
   CASE WHEN operation->'version'='2'::jsonb AND registration->>'effectiveStopped'='false' THEN nullif(operation->'terminalCandidate','null'::jsonb) END,
   CASE WHEN operation->'version'='2'::jsonb AND registration->>'effectiveStopped'='false' AND nullif(operation->'terminalCandidate','null'::jsonb) IS NOT NULL THEN
    (SELECT jsonb_agg(jsonb_build_object('origin',m.n->'origin','revision',m.n->'revision','commandOrdinal',m.n->'commandOrdinal',
      'kind','session_message','version','1','id',written.id,'frameId',t_frame,'derivationId',d.id,'sequence',written.sequence_num,
      'payloadDigest',o.value->'payloadDigest') ORDER BY m.ordinal)
     FROM jsonb_array_elements(operation#>'{terminalCandidate,members}') WITH ORDINALITY m(n,ordinal)
     JOIN t_written written ON written.sequence_num=next_sequence+(m.n->>'commandOrdinal')::integer+1
     JOIN t_declarations d ON d.resource_id=written.id JOIN output_rows o ON o.frame_id=t_frame AND o.value->>'id'=written.id::text) END
  FROM seal CROSS JOIN(SELECT count(*) FROM debt) ready WHERE operation IS NOT NULL RETURNING id
 ) SELECT
  (SELECT coalesce(jsonb_agg(jsonb_build_object('message',jsonb_build_object('id',m.id,'sessionId',s,'role',m.role,'content',m.content,
   'sequenceNum',m.sequence_num,'createdAt',m.created_at,'replyToText',NULL,'topicLabel',NULL,'topicConfidence',NULL,
   'channelMessageId',m.channel_message_id,'senderUserId',m.sender_user_id,'senderAssistantId',m.sender_assistant_id,'attachments',m.attachments),
   'source',t_scope||jsonb_build_object('resourceKind','session_message','resourceId',m.id,'version','1')) ORDER BY m.sequence_num),'[]') FROM t_written m),
  (SELECT jsonb_build_object('source',a_scope||jsonb_build_object('resourceKind','session_context_revision','resourceId',a_id,'version','1'),
   'createdAt',a.created_at,'userId',session_row.user_id,'assistantId',session_row.assistant_id) FROM a_annotation a)
 INTO results,annotation_result FROM(SELECT count(*) FROM debt) ready CROSS JOIN(SELECT count(*) FROM registration) registered;
 IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation IMMEDIATE;END IF;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN CASE WHEN operation->'version'='2'::jsonb THEN native_conversation_publication_packet((operation->>'operationId')::uuid,CASE WHEN envelope THEN jsonb_build_object('messages',results,'annotation',annotation_result) ELSE results END) ELSE CASE WHEN envelope THEN jsonb_build_object('messages',results,'annotation',annotation_result) ELSE results END END;
EXCEPTION WHEN SQLSTATE 'PNT02' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';
END $function$;

CREATE OR REPLACE FUNCTION public.publish_native_session_message_batch(w uuid,s uuid,payloads jsonb,producer text,sources jsonb,target jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET plan_cache_mode=force_generic_plan AS $legacy$
BEGIN RETURN publish_native_session_message_batch(w,s,payloads,producer,sources,target,NULL);END $legacy$;
REVOKE ALL ON FUNCTION publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb) FROM PUBLIC,app_user;
GRANT EXECUTE ON FUNCTION publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb) TO app_user;
-- [COMP:api/native-turn-frame] Fresh completion belongs to the whole physical publication.
CREATE OR REPLACE FUNCTION public.native_turn_complete_publication() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $function$
DECLARE work native_turn_publication_work;leader native_turn_publication_work;fresh jsonb;item jsonb;message session_messages;d scope_derivations;
 expected_scope jsonb;actual_scope jsonb;actual_payload jsonb;events jsonb;actual_events jsonb;frame_content jsonb;frame_scope jsonb;annotation session_context_scope_revisions;
 members uuid[];cohort_outputs jsonb;commands jsonb;proofs jsonb;ordinal integer:=0;publication native_conversation_publications;committed_outputs jsonb;
BEGIN
 SELECT * INTO leader FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=NEW.frame_id;
 IF leader.frame_id IS NULL OR NEW.transaction_id<>txid_current() OR native_turn_helpers_current() IS NOT TRUE
  OR native_turn_context() IS DISTINCT FROM leader.context OR leader.completion_owner IS NOT NULL AND leader.completion_owner<>leader.frame_id
  OR jsonb_typeof(NEW.outputs) IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 SELECT array_agg(frame_id ORDER BY frame_id),jsonb_agg(jsonb_build_object('producer','native:turn-frame','sources',original_sources,'target',prepared->'scope')
  ||CASE WHEN prepared ? 'purpose' THEN jsonb_build_object('purpose',prepared->'purpose') ELSE '{}'::jsonb END ORDER BY frame_id)
 INTO members,commands FROM native_turn_publication_work
 WHERE transaction_id=txid_current() AND (leader.completion_owner IS NULL AND frame_id=leader.frame_id OR completion_owner=leader.frame_id);
 IF leader.completion_owner IS NULL THEN
  IF cardinality(members)<>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.outputs) n WHERE n ? 'frameId')
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 ELSE
  IF cardinality(members)<>2 OR jsonb_array_length(NEW.outputs) NOT BETWEEN 2 AND 513
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.outputs) n WHERE NOT n ? 'frameId' OR NOT (n->>'frameId')::uuid=ANY(members))
   OR (SELECT count(*) FROM jsonb_array_elements(NEW.outputs) n WHERE n->>'kind'='message_annotation')<>1
   OR EXISTS(SELECT 1 FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=ANY(members) AND frame_id<>leader.frame_id)
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END IF;
 -- The independent completion command observes every payload/head mutation.
 proofs:=conversation_prepare_publications(leader.workspace_id,leader.session_id,commands);
 FOR work IN SELECT * FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=ANY(members) ORDER BY frame_id LOOP
  IF (work.workspace_id,work.session_id,work.context,work.completion_owner,work.publication_id) IS DISTINCT FROM
   (leader.workspace_id,leader.session_id,leader.context,leader.completion_owner,leader.publication_id)
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  SELECT jsonb_agg(n) INTO cohort_outputs FROM jsonb_array_elements(NEW.outputs) n
   WHERE leader.completion_owner IS NULL OR n->>'frameId'=work.frame_id::text;
  IF leader.completion_owner IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(cohort_outputs) n WHERE n ? 'kind')
   AND (jsonb_array_length(cohort_outputs)<>1 OR cohort_outputs->0->>'kind' IS DISTINCT FROM 'message_annotation')
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 IF work.frame_id IS NULL OR NEW.transaction_id<>txid_current()
  OR native_turn_context() IS DISTINCT FROM work.context OR native_turn_frame_pair(work.workspace_id,work.frame_id) IS NOT TRUE
  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=work.frame_id)
  OR EXISTS(SELECT 1 FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id AND NOT fired)
  OR jsonb_typeof(cohort_outputs) IS DISTINCT FROM 'array' OR jsonb_array_length(cohort_outputs) NOT BETWEEN 1 AND 512
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 expected_scope:=work.prepared->'scope';
 SELECT c.content,jsonb_build_object('workspaceId',r.workspace_id,'userId',r.user_id,'assistantId',r.assistant_id,
  'sensitivity',r.sensitivity,'compartments',r.compartments,'projectIds',r.project_ids)
 INTO frame_content,frame_scope FROM session_context_scope_revisions r JOIN session_context_revision_contents c
 ON c.workspace_id=r.workspace_id AND c.revision_id=r.id WHERE r.workspace_id=work.workspace_id AND r.id=work.frame_id;
 IF frame_content->'originalSources' IS DISTINCT FROM work.original_sources
  OR frame_content->'declaredSources' IS DISTINCT FROM work.prepared->'retained' OR frame_scope IS DISTINCT FROM expected_scope
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(cohort_outputs) LOOP
  IF item->>'kind' IN('message_annotation','session_title') THEN
   SELECT * INTO annotation FROM session_context_scope_revisions WHERE workspace_id=work.workspace_id AND session_id=work.session_id AND id=(item->>'id')::uuid;
   SELECT * INTO d FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(item->>'derivationId')::uuid;
   SELECT c.content INTO actual_payload FROM session_context_revision_contents c WHERE c.workspace_id=work.workspace_id AND c.revision_id=annotation.id;
   actual_scope:=jsonb_build_object('workspaceId',annotation.workspace_id,'userId',annotation.user_id,'assistantId',annotation.assistant_id,
    'sensitivity',annotation.sensitivity,'compartments',annotation.compartments,'projectIds',annotation.project_ids);
   IF annotation.id IS NULL OR annotation.parent_kind IS DISTINCT FROM item->>'kind' OR annotation.parent_id::text IS DISTINCT FROM item->>'parentId'
    OR annotation.scope_version<>1 OR annotation.scope_held OR scope_review_state_held('session_context_revision',annotation.id)
    OR actual_scope IS DISTINCT FROM expected_scope OR actual_payload IS NULL OR session_context_payload_shape(item->>'kind',actual_payload) IS NOT TRUE
    OR annotation.payload_sha256 IS DISTINCT FROM item->>'payloadDigest' OR item->>'payloadDigest' IS DISTINCT FROM encode(sha256(convert_to(actual_payload::text,'UTF8')),'hex')
    OR item->>'kind'='message_annotation' AND (NOT EXISTS(SELECT 1 FROM session_messages m JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id
     WHERE m.workspace_id=work.workspace_id AND m.session_id=work.session_id AND m.id=annotation.parent_id AND h.scope_revision_id=annotation.id)
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(work.original_sources) n WHERE n->>'resourceKind'='session_message' AND n->>'resourceId'=annotation.parent_id::text))
    OR item->>'kind'='session_title' AND (work.prepared->>'purpose' IS DISTINCT FROM 'session_title'
     OR annotation.parent_id IS DISTINCT FROM work.session_id
     OR NOT EXISTS(SELECT 1 FROM session_title_heads h JOIN sessions s ON s.workspace_id=h.workspace_id AND s.id=h.session_id
      WHERE h.workspace_id=work.workspace_id AND h.session_id=work.session_id AND h.scope_revision_id=annotation.id
       AND s.title IS NULL AND s.title_manually_set IS NOT DISTINCT FROM (actual_payload->>'manual')::boolean))
    OR d.id IS NULL OR d.resource_kind IS DISTINCT FROM 'session_context_revision' OR d.resource_id IS DISTINCT FROM annotation.id OR d.resource_version IS DISTINCT FROM '1'
    OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM
      (annotation.user_id,annotation.assistant_id,annotation.sensitivity,annotation.compartments,annotation.project_ids)
    OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id)<>1
    OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id AND source_kind='session_context_revision' AND source_id=work.frame_id AND source_version='1')
   THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   CONTINUE;
  END IF;
  IF item ? 'kind' THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  SELECT * INTO message FROM session_messages WHERE workspace_id=work.workspace_id AND session_id=work.session_id AND id=(item->>'id')::uuid;
  SELECT * INTO d FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(item->>'derivationId')::uuid;
  actual_scope:=jsonb_build_object('workspaceId',message.workspace_id,'userId',message.user_id,'assistantId',message.assistant_id,
   'sensitivity',message.sensitivity,'compartments',message.compartments,'projectIds',message.project_ids);
  actual_payload:=jsonb_build_object('role',message.role,'content',message.content,'channelMessageId',message.channel_message_id,
   'senderUserId',message.sender_user_id,'senderAssistantId',message.sender_assistant_id,'attachments',message.attachments);
  IF message.id IS NULL OR message.scope_held OR scope_review_state_held('session_message',message.id) OR message.scope_version<>1 OR message.sequence_num IS DISTINCT FROM (item->>'sequence')::integer
   OR actual_scope IS DISTINCT FROM expected_scope OR item->>'payloadDigest' IS DISTINCT FROM encode(sha256(convert_to(actual_payload::text,'UTF8')),'hex')
   OR d.id IS NULL OR d.resource_kind IS DISTINCT FROM 'session_message' OR d.resource_id IS DISTINCT FROM message.id OR d.resource_version IS DISTINCT FROM '1'
   OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM
      (message.user_id,message.assistant_id,message.sensitivity,message.compartments,message.project_ids)
   OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id)<>1
   OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id
    AND source_kind='session_context_revision' AND source_id=work.frame_id AND source_version='1') THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT jsonb_agg(event ORDER BY event::text) INTO events FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 SELECT jsonb_agg(to_jsonb(e) ORDER BY to_jsonb(e)::text) INTO actual_events FROM scope_derivation_sources e JOIN scope_derivations actual_derivation ON actual_derivation.workspace_id=e.workspace_id AND actual_derivation.id=e.derivation_id
 WHERE actual_derivation.workspace_id=work.workspace_id AND (actual_derivation.resource_kind='session_context_revision' AND actual_derivation.resource_id=work.frame_id
  OR actual_derivation.id IN(SELECT (n->>'derivationId')::uuid FROM jsonb_array_elements(cohort_outputs) n));
 IF events IS NULL OR events IS DISTINCT FROM actual_events THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;

  fresh:=proofs->ordinal;ordinal:=ordinal+1;
  IF fresh IS NULL OR (fresh-'proof') IS DISTINCT FROM work.prepared OR native_turn_context() IS DISTINCT FROM work.context
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF fresh#>>'{proof,validUntil}' IS NULL OR clock_timestamp()>=(fresh#>>'{proof,validUntil}')::timestamptz
  THEN RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
 END LOOP;
 IF ordinal<>cardinality(members) OR native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF leader.publication_id IS NOT NULL THEN
  SELECT * INTO publication FROM native_conversation_publications WHERE id=leader.publication_id FOR UPDATE;
  IF publication.id IS NULL OR publication.workspace_id<>leader.workspace_id OR publication.session_id<>leader.session_id
   OR publication.leader_frame_id<>leader.frame_id OR publication.frame_ids IS DISTINCT FROM members
   OR publication.expected_output_count<>jsonb_array_length(NEW.outputs) OR publication.completed_at IS NOT NULL
   OR publication.actor_user_id::text IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),'')
   OR publication.assistant_id::text IS DISTINCT FROM nullif(current_setting('app.v2_assistant_id',true),'')
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  SELECT jsonb_agg(output.n||jsonb_build_object('kind',coalesce(output.n->>'kind','session_message'),'version','1',
   'frameId',coalesce(output.n->>'frameId',leader.frame_id::text)) ORDER BY output.ordinal) INTO committed_outputs
   FROM jsonb_array_elements(NEW.outputs) WITH ORDINALITY output(n,ordinal);
  IF publication.command_format=2 AND native_conversation_terminal_subset(publication.terminal_descriptor,publication.terminal_outputs,committed_outputs) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  UPDATE native_conversation_publications SET outputs=committed_outputs,completed_at=clock_timestamp() WHERE id=publication.id;
 END IF;
 UPDATE native_turn_publication_work SET completion_ready=true WHERE transaction_id=txid_current() AND frame_id=ANY(members);
 DELETE FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=ANY(members);
 DELETE FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=ANY(members);
 DELETE FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=leader.frame_id;
 DELETE FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=ANY(members);
 RETURN NULL;
END $function$;

CREATE TEMP TABLE publication_source_functions(
 signature text PRIMARY KEY,metadata jsonb NOT NULL,body_parts jsonb NOT NULL
) ON COMMIT DROP;
CREATE TEMP TABLE publication_verified_table_snapshot(snapshot jsonb NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE publication_before_installer_schema(snapshot jsonb NOT NULL) ON COMMIT DROP;

CREATE FUNCTION pg_temp.publication_assert_expected_functions() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $check$
DECLARE expected record;actual pg_proc;
BEGIN
 FOR expected IN SELECT signature,metadata FROM publication_expected_current ORDER BY signature COLLATE "C" LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||expected.signature);
  IF actual.oid IS NULL OR to_jsonb(actual) IS DISTINCT FROM expected.metadata THEN
   RAISE EXCEPTION 'publication_unreviewed_successor: %',expected.signature USING ERRCODE='55000';
  END IF;
 END LOOP;
END $check$;

DO $source_functions$
DECLARE specs constant jsonb:='[{"profile":"new","name":"native_conversation_publication_scope","signature":"native_conversation_publication_scope(uuid,uuid)","argNames":["w","s"],"argTypes":["uuid","uuid"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n assistant uuid:=nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid;parent jsonb;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF actor IS NULL OR assistant IS NULL OR NOT EXISTS(SELECT 1 FROM sessions r WHERE r.workspace_id=w AND r.id=s AND (r.visibility = ''workspace'' AND r.channel_type = ''web'' AND r.anchor_kind = ''none'' AND r.app_origin = ''chat'' AND r.transient IS NOT TRUE))\n  OR NOT EXISTS(SELECT 1 FROM assistants a WHERE a.id=assistant AND a.workspace_id=w)\n  OR nullif(current_setting(''app.programmatic_candidate'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.programmatic_publication_batch'',true),'''') IS NOT NULL\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN jsonb_build_object(''actorUserId'',actor,''assistantId'',assistant);\nEND "},{"profile":"new","name":"native_conversation_publication_result","signature":"native_conversation_publication_result(uuid,uuid,uuid)","argNames":["w","s","i"],"argTypes":["uuid","uuid","uuid"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;scope jsonb;proof jsonb;roots jsonb;item jsonb;message session_messages;\n revision session_context_scope_revisions;payload jsonb;rows jsonb:=''[]'';annotation jsonb;source jsonb;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n SELECT * INTO r FROM native_conversation_publications WHERE workspace_id=w AND session_id=s AND id=i\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid;\n IF NOT FOUND THEN RETURN jsonb_build_object(''state'',''unknown'');END IF;\n IF r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array'' OR jsonb_array_length(r.outputs)<>r.expected_output_count\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_incomplete'');END IF;\n IF EXISTS(SELECT 1 FROM unnest(r.frame_ids) frame WHERE native_turn_frame_pair(w,frame) IS NOT TRUE)\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_frame_changed'');END IF;\n SELECT jsonb_agg(DISTINCT value) INTO roots FROM (\n  SELECT jsonb_build_object(''kind'',''session_context_revision'',''id'',frame,''version'',''1'') value FROM unnest(r.frame_ids) frame\n  UNION ALL SELECT jsonb_build_object(''kind'',CASE WHEN n->>''kind''=''message_annotation'' THEN ''session_context_revision'' ELSE ''session_message'' END,\n   ''id'',n->''id'',''version'',''1'') FROM jsonb_array_elements(r.outputs) n\n ) members;\n proof:=capture_conversation_evidence(w,roots);\n IF proof IS NULL THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');END IF;\n IF proof->>''admitted'' IS DISTINCT FROM ''true'' THEN\n  IF proof->>''admitted''=''false'' THEN RETURN jsonb_build_object(''state'',''denied'',''reason'',''source_access_denied'');END IF;\n  RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');\n END IF;\n FOR item IN SELECT value FROM jsonb_array_elements(r.outputs) ORDER BY coalesce((value->>''sequence'')::integer,0),value->>''id'' LOOP\n  IF NOT (item->>''frameId'')::uuid=ANY(r.frame_ids) THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n  IF item->>''kind''=''session_message'' THEN\n   SELECT * INTO message FROM session_messages WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   payload:=jsonb_build_object(''role'',message.role,''content'',message.content,''channelMessageId'',message.channel_message_id,\n    ''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments);\n   IF message.id IS NULL OR message.scope_version<>1 OR message.scope_held OR message.sequence_num<>(item->>''sequence'')::integer\n    OR item->>''version''<>''1'' OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_message'' AND d.resource_id=message.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',message.user_id,''assistantId'',message.assistant_id,''sensitivity'',message.sensitivity,\n    ''compartments'',message.compartments,''projectIds'',message.project_ids,''resourceKind'',''session_message'',''resourceId'',message.id,''version'',''1'');\n   rows:=rows||jsonb_build_array(jsonb_build_object(''message'',jsonb_build_object(''id'',message.id,''sessionId'',s,''role'',message.role,''content'',message.content,\n    ''sequenceNum'',message.sequence_num,''createdAt'',message.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n    ''channelMessageId'',message.channel_message_id,''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments),''source'',source));\n  ELSIF item->>''kind''=''message_annotation'' THEN\n   SELECT * INTO revision FROM session_context_scope_revisions WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;\n   IF revision.id IS NULL OR revision.parent_kind<>''message_annotation'' OR revision.parent_id::text IS DISTINCT FROM item->>''parentId''\n    OR revision.scope_version<>1 OR revision.scope_held OR item->>''version''<>''1''\n    OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_context_revision'' AND d.resource_id=revision.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',revision.user_id,''assistantId'',revision.assistant_id,''sensitivity'',revision.sensitivity,\n    ''compartments'',revision.compartments,''projectIds'',revision.project_ids,''resourceKind'',''session_context_revision'',''resourceId'',revision.id,''version'',''1'');\n   annotation:=jsonb_build_object(''source'',source,''createdAt'',revision.created_at,''userId'',r.annotation_user_id,''assistantId'',r.annotation_assistant_id);\n  ELSE RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n END LOOP;\n RETURN jsonb_build_object(''state'',''committed'',''outputs'',r.outputs,''value'',CASE WHEN annotation IS NULL THEN rows ELSE jsonb_build_object(''messages'',rows,''annotation'',annotation) END);\nEND "},{"profile":"new","name":"native_conversation_publication_enter","signature":"native_conversation_publication_enter(uuid,uuid,jsonb,jsonb)","argNames":["w","s","operation","command"],"argTypes":["uuid","uuid","jsonb","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE scope jsonb;r native_conversation_publications;digest text;result jsonb;payloads jsonb;node jsonb;version integer;state text;effective_stopped boolean;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n version:=CASE operation->''version'' WHEN ''1''::jsonb THEN 1 WHEN ''2''::jsonb THEN 2 END;\n IF version IS NULL OR jsonb_typeof(operation) IS DISTINCT FROM ''object''\n  OR operation-(ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)<>''{}''\n  OR NOT operation ?& (ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)\n  OR operation->>''slot'' IS DISTINCT FROM ''buffered_transcript'' OR jsonb_typeof(operation->''stopped'') IS DISTINCT FROM ''boolean''\n  OR EXISTS(SELECT 1 FROM unnest(ARRAY[''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'']) key\n   WHERE jsonb_typeof(operation->key) IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(operation->>key,''uuid''))\n  OR jsonb_typeof(command) IS DISTINCT FROM ''object'' OR command-ARRAY[''payloads'',''producer'',''sources'',''target'']<>''{}''\n  OR NOT command ?& ARRAY[''payloads'',''producer'',''sources'',''target'']\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF operation->>''actorUserId'' IS DISTINCT FROM scope->>''actorUserId'' OR operation->>''assistantId'' IS DISTINCT FROM scope->>''assistantId''\n  OR NOT EXISTS(SELECT 1 FROM session_messages m WHERE m.workspace_id=w AND m.session_id=s AND m.id=(operation->>''inputMessageId'')::uuid\n   AND m.role=''user'' AND m.sender_user_id=(scope->>''actorUserId'')::uuid)\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n payloads:=command->''payloads'';\n IF jsonb_typeof(payloads)=''object'' THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n   OR (payloads->''annotation'')-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT (payloads->''annotation'') ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n   OR jsonb_typeof(payloads#>''{annotation,sources}'') IS DISTINCT FROM ''array''\n   OR payloads#>>''{annotation,kind}'' IS NOT NULL AND payloads#>>''{annotation,kind}''<>''message_annotation''\n   OR payloads#>>''{annotation,parentId}'' IS DISTINCT FROM operation->>''inputMessageId''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  payloads:=payloads->''messages'';\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND jsonb_typeof(command->''payloads'')<>''object''\n  OR jsonb_typeof(command->''sources'') IS DISTINCT FROM ''array''\n  OR jsonb_typeof(command->''target'') IS DISTINCT FROM ''object''\n  OR (command->''target'')-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'']<>''{}''\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n FOR node IN SELECT value FROM jsonb_array_elements(command->''sources'')\n  UNION ALL SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(command->''payloads'')=''object'' THEN command#>''{payloads,annotation,sources}'' ELSE ''[]''::jsonb END)\n LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object''\n   OR NOT node ?& ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']\n   OR node-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']<>''{}''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF version=2 AND native_conversation_terminal_candidate_valid(operation->''terminalCandidate'',payloads,(operation->>''assistantId'')::uuid) IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n digest:=encode(sha256(convert_to(jsonb_build_object(''format'',version,''workspaceId'',w,''sessionId'',s,''operation'',operation,''command'',command)::text,''UTF8'')),''hex'');\n SELECT * INTO r FROM native_conversation_publications WHERE id=(operation->>''operationId'')::uuid\n  OR workspace_id=w AND session_id=s AND turn_token=(operation->>''turnToken'')::uuid AND slot=''buffered_transcript'' FOR UPDATE;\n IF FOUND THEN\n  IF r.id<>(operation->>''operationId'')::uuid OR r.workspace_id<>w OR r.session_id<>s OR r.input_message_id<>(operation->>''inputMessageId'')::uuid\n   OR r.actor_user_id<>(scope->>''actorUserId'')::uuid OR r.assistant_id<>(scope->>''assistantId'')::uuid OR r.turn_token<>(operation->>''turnToken'')::uuid OR r.command_digest<>digest\n   OR r.command_format<>version OR version=1 AND r.stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n   OR version=2 AND r.requested_stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  result:=native_conversation_publication_result(w,s,r.id);\n  IF result->>''state''<>''committed'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  RETURN jsonb_build_object(''duplicate'',true,''value'',CASE WHEN version=2 THEN native_conversation_publication_packet(r.id,result->''value'') ELSE result->''value'' END);\n END IF;\n IF version=2 THEN\n  state:=native_session_turn_publication_state(w,s,(operation->>''turnToken'')::uuid);\n  IF state NOT IN(''active'',''stopping'',''stopped'') THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean OR state IN(''stopping'',''stopped'');\n ELSE\n  IF native_session_turn_publication_allowed(w,s,(operation->>''turnToken'')::uuid,(operation->>''stopped'')::boolean) IS NOT TRUE\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean;\n END IF;\n RETURN jsonb_build_object(''duplicate'',false,''digest'',digest,''effectiveStopped'',effective_stopped);\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';\nEND "},{"profile":"new","name":"native_conversation_publication_complete","signature":"native_conversation_publication_complete()","argNames":[],"argTypes":[],"returnType":"trigger","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO r FROM native_conversation_publications WHERE id=NEW.id;\n IF NOT FOUND THEN RETURN NULL;END IF; -- an authorized cascading erasure owns deletion\n IF r.outputs IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(r.outputs)<>r.expected_output_count OR NOT r.leader_frame_id=ANY(r.frame_ids)\n  OR cardinality(r.frame_ids)<>(SELECT count(DISTINCT value) FROM unnest(r.frame_ids) value)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.outputs) n WHERE NOT (n->>''frameId'')::uuid=ANY(r.frame_ids))\n  OR r.command_format=2 AND (r.stopped AND r.terminal_descriptor IS NOT NULL\n   OR native_conversation_terminal_subset(r.terminal_descriptor,r.terminal_outputs,r.outputs) IS NOT TRUE)\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NULL;\nEND "},{"profile":"new","name":"native_conversation_publication_immutable","signature":"native_conversation_publication_immutable()","argNames":[],"argTypes":[],"returnType":"trigger","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nBEGIN\n IF (to_jsonb(NEW)-ARRAY[''outputs'',''completed_at'']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY[''outputs'',''completed_at''])\n  OR OLD.outputs IS NOT NULL OR NEW.outputs IS NULL OR NEW.completed_at IS NULL\n  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_work work JOIN native_turn_publication_seals seal\n   ON seal.transaction_id=work.transaction_id AND seal.frame_id=work.frame_id\n   WHERE work.transaction_id=txid_current() AND work.frame_id=OLD.leader_frame_id AND work.publication_id=OLD.id\n    AND work.workspace_id=OLD.workspace_id AND work.session_id=OLD.session_id AND work.context=native_turn_context())\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NEW;\nEND "},{"profile":"new","name":"read_native_conversation_publications","signature":"read_native_conversation_publications(uuid,uuid,jsonb,integer)","argNames":["w","s","after","maximum"],"argTypes":["uuid","uuid","jsonb","integer"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":"NULL::jsonb, 20","appExecute":true,"body":"\nDECLARE scope jsonb;cursor_at timestamptz;cursor_id uuid;r native_conversation_publications;result jsonb;items jsonb:=''[]'';next_cursor jsonb;count integer:=0;diagnostic text;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n IF maximum IS NULL OR maximum NOT BETWEEN 1 AND 50 OR after IS NOT NULL AND\n  (jsonb_typeof(after) IS DISTINCT FROM ''object'' OR after-ARRAY[''createdAt'',''operationId'']<>''{}'' OR NOT after ?& ARRAY[''createdAt'',''operationId'']\n   OR jsonb_typeof(after->''createdAt'') IS DISTINCT FROM ''string'' OR jsonb_typeof(after->''operationId'') IS DISTINCT FROM ''string''\n   OR NOT pg_input_is_valid(after->>''createdAt'',''timestamptz'') OR NOT pg_input_is_valid(after->>''operationId'',''uuid''))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF after IS NOT NULL THEN cursor_at:=(after->>''createdAt'')::timestamptz;cursor_id:=(after->>''operationId'')::uuid;END IF;\n FOR r IN SELECT * FROM native_conversation_publications WHERE workspace_id=w AND session_id=s\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid\n  AND (after IS NULL OR (created_at,id)<(cursor_at,cursor_id)) ORDER BY created_at DESC,id DESC LIMIT maximum+1\n LOOP\n  count:=count+1;IF count>maximum THEN EXIT;END IF;\n  BEGIN\n   result:=native_conversation_publication_result(w,s,r.id)-''value'';\n   IF result->>''state''=''unknown'' THEN result:=jsonb_build_object(''state'',''unavailable'',''reason'',''publication_changed'');END IF;\n  EXCEPTION WHEN SQLSTATE ''42501'' OR SQLSTATE ''22023'' OR lock_not_available THEN\n   GET STACKED DIAGNOSTICS diagnostic=RETURNED_SQLSTATE;\n   result:=jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable:''||diagnostic);\n  END;\n  items:=items||jsonb_build_array(result||jsonb_build_object(''operationId'',r.id,''inputMessageId'',r.input_message_id,''assistantId'',r.assistant_id));\n  next_cursor:=jsonb_build_object(''createdAt'',r.created_at,''operationId'',r.id);\n END LOOP;\n IF count<=maximum THEN next_cursor:=NULL;END IF;\n RETURN jsonb_build_object(''version'',1,''scope'',scope,''items'',items,''nextCursor'',next_cursor);\nEND "},{"profile":"new","name":"native_session_turn_publication_state","signature":"native_session_turn_publication_state(uuid,uuid,uuid)","argNames":["w","s","t"],"argTypes":["uuid","uuid","uuid"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":true,"body":"\nDECLARE r sessions;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n PERFORM lock_native_session_context_publication(w,s);\n SELECT * INTO r FROM sessions WHERE workspace_id=w AND id=s;\n IF NOT FOUND OR t IS NULL OR r.last_turn_lease_token IS DISTINCT FROM t THEN RETURN ''superseded'';END IF;\n IF r.turn_lease_token=t AND r.status=''running'' THEN\n  RETURN CASE WHEN r.cancel_requested_at IS NULL THEN ''active'' ELSE ''stopping'' END;\n END IF;\n IF r.turn_lease_token IS NULL AND r.turn_end_reason=''stopped_by_user'' THEN RETURN ''stopped'';END IF;\n RETURN ''superseded'';\nEND "},{"profile":"new","name":"native_conversation_terminal_candidate_valid","signature":"native_conversation_terminal_candidate_valid(jsonb,jsonb,uuid)","argNames":["candidate","payloads","answering"],"argTypes":["jsonb","jsonb","uuid"],"returnType":"boolean","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE m jsonb;row jsonb;previous integer:=-1;ordinal integer;origins text[]:=''{}'';\nBEGIN\n IF candidate IS NULL OR candidate=''null''::jsonb THEN RETURN true;END IF;\n IF jsonb_typeof(candidate) IS DISTINCT FROM ''object''\n  OR candidate-ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']<>''{}''\n  OR NOT candidate ?& ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']\n  OR candidate->''version''<>''1''::jsonb OR candidate->>''disposition'' IS DISTINCT FROM ''reply''\n  OR candidate->>''projection'' IS DISTINCT FROM ''persistable_response_v1'' OR candidate->>''formatter'' IS DISTINCT FROM ''turn_output_v1''\n  OR candidate->>''format'' NOT IN(''compact'',''channel'') OR candidate->>''format'' IS NULL\n  OR jsonb_typeof(candidate->''invocationId'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(candidate->>''invocationId'',''uuid'') OR length(candidate->>''invocationId'')<>36\n  OR candidate->>''textDigest'' !~ ''^[a-f0-9]{64}$'' OR candidate->>''textDigest'' IS NULL\n  OR jsonb_typeof(candidate->''members'') IS DISTINCT FROM ''array'' OR jsonb_array_length(candidate->''members'') NOT BETWEEN 1 AND 512\n  OR jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(candidate->''members'') LOOP\n  IF jsonb_typeof(m) IS DISTINCT FROM ''object'' OR m-ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']<>''{}''\n   OR NOT m ?& ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']\n   OR jsonb_typeof(m->''origin'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(m->>''origin'',''uuid'') OR length(m->>''origin'')<>36 OR m->>''origin''=ANY(origins)\n   OR jsonb_typeof(m->''revision'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''revision'',''integer'')\n   OR jsonb_typeof(m->''commandOrdinal'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''commandOrdinal'',''integer'')\n   OR m->>''snapshotDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''snapshotDigest'' IS NULL\n   OR m->>''contentDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''contentDigest'' IS NULL\n  THEN RETURN false;END IF;\n  ordinal:=(m->>''commandOrdinal'')::integer;\n  IF (m->>''revision'')::integer<1 OR ordinal<=previous OR ordinal>=jsonb_array_length(payloads) THEN RETURN false;END IF;\n  previous:=ordinal;origins:=origins||(m->>''origin'');row:=payloads->ordinal;\n  IF row->>''role'' IS DISTINCT FROM ''assistant'' OR row->>''senderAssistantId'' IS DISTINCT FROM answering::text\n   OR jsonb_typeof(row->''content'') IS DISTINCT FROM ''array''\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(row->''content'') b WHERE b->>''type'' IN(''tool_use'',''host_observation''))\n  THEN RETURN false;END IF;\n END LOOP;\n RETURN true;\nEND "},{"profile":"new","name":"native_conversation_terminal_subset","signature":"native_conversation_terminal_subset(jsonb,jsonb,jsonb)","argNames":["descriptor","selected","outputs"],"argTypes":["jsonb","jsonb","jsonb"],"returnType":"boolean","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE m jsonb;n jsonb;position integer:=0;seen uuid[]:=''{}'';\nBEGIN\n IF descriptor IS NULL THEN RETURN selected IS NULL;END IF;\n IF jsonb_typeof(selected) IS DISTINCT FROM ''array'' OR jsonb_array_length(selected)<>jsonb_array_length(descriptor->''members'')\n  OR jsonb_array_length(selected) NOT BETWEEN 1 AND 512 THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(descriptor->''members'') LOOP\n  n:=selected->position;position:=position+1;\n  IF n-ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']<>''{}''\n   OR NOT n ?& ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']\n   OR n->''origin'' IS DISTINCT FROM m->''origin'' OR n->''revision'' IS DISTINCT FROM m->''revision''\n   OR n->''commandOrdinal'' IS DISTINCT FROM m->''commandOrdinal'' OR n->>''kind'' IS DISTINCT FROM ''session_message''\n   OR NOT pg_input_is_valid(n->>''id'',''uuid'') OR (n->>''id'')::uuid=ANY(seen)\n   OR (SELECT count(*) FROM jsonb_array_elements(outputs) o WHERE o=n-ARRAY[''origin'',''revision'',''commandOrdinal''])<>1\n  THEN RETURN false;END IF;\n  seen:=seen||(n->>''id'')::uuid;\n END LOOP;\n RETURN true;\nEND "},{"profile":"new","name":"native_conversation_publication_packet","signature":"native_conversation_publication_packet(uuid,jsonb)","argNames":["i","value"],"argTypes":["uuid","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO STRICT r FROM native_conversation_publications WHERE id=i;\n IF r.command_format<>2 THEN RETURN value;END IF;\n RETURN jsonb_build_object(''value'',value,''publication'',jsonb_build_object(''operationId'',r.id,''commandDigest'',r.command_digest,\n  ''requestedStopped'',r.requested_stopped,''stopped'',r.stopped,''terminalDescriptor'',r.terminal_descriptor,''terminalOutputs'',r.terminal_outputs));\nEND "},{"profile":"new","name":"native_session_public_turn_id","signature":"native_session_public_turn_id(uuid,uuid,uuid)","argNames":["w","s","t"],"argTypes":["uuid","uuid","uuid"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nBEGIN\n RETURN CASE WHEN w IS NULL OR s IS NULL OR t IS NULL THEN NULL ELSE\n  encode(sha256(convert_to(''use-brian/session-turn/v1:''||w::text||'':''||s::text||'':''||t::text,''UTF8'')),''hex'') END;\nEND "},{"profile":"new","name":"native_session_expired_turn_outcome","signature":"native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)","argNames":["w","s","t","a","cancelled"],"argTypes":["uuid","uuid","uuid","uuid","boolean"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE publication public.native_conversation_publications;\nBEGIN\n IF cancelled THEN RETURN ''stopped_by_user'';END IF;\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF w IS NULL OR t IS NULL OR a IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n SELECT * INTO publication FROM public.native_conversation_publications p\n  WHERE p.workspace_id=w AND p.session_id=s AND p.turn_token=t\n   AND p.slot=''buffered_transcript'';\n IF NOT FOUND OR publication.command_format=1 THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.command_format<>2 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.completed_at IS NULL OR publication.outputs IS NULL OR jsonb_typeof(publication.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.outputs)<>publication.expected_output_count\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.assistant_id<>a OR publication.stopped OR publication.terminal_descriptor IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.outputs IS NULL OR publication.terminal_outputs IS NULL\n  OR jsonb_typeof(publication.terminal_outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.terminal_outputs)=0\n  OR jsonb_array_length(publication.terminal_outputs)<>jsonb_array_length(publication.terminal_descriptor->''members'')\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n -- The authenticated independent completion owner validates descriptor/member\n -- shape, exact roots/native references and the entire actual output closure\n -- before this immutable row can commit. Current access does not alter that fact.\n RETURN ''publication_recovered'';\nEND "},{"profile":"new","name":"native_session_turn_transition","signature":"native_session_turn_transition(uuid,text,uuid,timestamp with time zone,integer,uuid,text,boolean)","argNames":["s","action","answering_assistant","started_at","stale_after_ms","expected_token","expected_public_turn_id","fence_token"],"argTypes":["uuid","text","uuid","timestamp with time zone","integer","uuid","text","boolean"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r public.sessions;w uuid;original_token uuid;original_public_id text;outcome text;\n recovered jsonb;next_token uuid;resting text;now_at timestamptz;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF action IS NULL OR action NOT IN(''claim'',''reclaim'',''cancel'') OR stale_after_ms IS NULL OR stale_after_ms<1\n  OR fence_token IS NULL OR current_setting(''transaction_isolation'')<>''read committed''\n THEN RAISE EXCEPTION ''invalid_turn_transition'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n -- Same order as canonical native publication, never session then workspace.\n IF w IS NOT NULL THEN\n  PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;\n  IF NOT FOUND THEN RETURN NULL;END IF;\n END IF;\n -- VOLATILE PL/pgSQL uses a new READ COMMITTED snapshot here after lock wait.\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n now_at:=clock_timestamp();original_token:=r.turn_lease_token;\n original_public_id:=public.native_session_public_turn_id(w,s,original_token);\n IF fence_token AND original_token IS DISTINCT FROM expected_token\n  OR expected_public_turn_id IS NOT NULL AND original_public_id IS DISTINCT FROM expected_public_turn_id\n THEN RETURN jsonb_build_object(''state'',''superseded'');END IF;\n IF action=''cancel'' THEN\n  IF r.status<>''running'' THEN RETURN jsonb_build_object(''state'',''not_running'');END IF;\n  IF original_token IS NULL THEN\n   UPDATE public.sessions SET status=''idle'',turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=''stopped_by_user'',last_active_at=now_at WHERE id=s;\n   RETURN jsonb_build_object(''state'',''stopped_legacy'',''turnId'',NULL,''reason'',''stopped_by_user'');\n  END IF;\n  UPDATE public.sessions SET cancel_requested_at=coalesce(cancel_requested_at,now_at)\n   WHERE id=s AND turn_lease_token=original_token AND status=''running'';\n  RETURN jsonb_build_object(''state'',''cancel_requested'',''token'',original_token,''turnId'',original_public_id,\n   ''stale'',coalesce(r.turn_heartbeat_at,r.last_active_at)<now_at-make_interval(secs=>stale_after_ms/1000.0));\n END IF;\n IF r.status=''running'' THEN\n  IF coalesce(r.turn_heartbeat_at,r.last_active_at)>=now_at-make_interval(secs=>stale_after_ms/1000.0)\n  THEN RETURN jsonb_build_object(''state'',''busy'');END IF;\n  outcome:=public.native_session_expired_turn_outcome(r.workspace_id,r.id,r.turn_lease_token,\n   CASE WHEN r.last_turn_lease_token=r.turn_lease_token THEN r.turn_assistant_id END,r.cancel_requested_at IS NOT NULL);\n  resting:=CASE WHEN outcome IN(''publication_recovered'',''stopped_by_user'') THEN ''idle'' ELSE ''timeout'' END;\n  UPDATE public.sessions SET status=resting,turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,\n   turn_end_reason=outcome,last_active_at=now_at WHERE id=s;\n  recovered:=jsonb_build_object(''turnId'',original_public_id,''reason'',outcome);\n ELSIF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''not_running'');\n END IF;\n IF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''recovered'',''recovered'',recovered);END IF;\n next_token:=gen_random_uuid();\n UPDATE public.sessions SET status=''running'',last_active_at=now_at,turn_lease_token=next_token,\n  turn_started_at=coalesce(started_at,now_at),turn_heartbeat_at=now_at,cancel_requested_at=NULL,\n  turn_end_reason=NULL,turn_assistant_id=answering_assistant WHERE id=s;\n RETURN jsonb_build_object(''state'',''claimed'',''token'',next_token,\n  ''turnId'',public.native_session_public_turn_id(w,s,next_token),''recovered'',recovered);\nEND "},{"profile":"new","name":"native_session_release_turn","signature":"native_session_release_turn(uuid,uuid,text)","argNames":["s","t","requested_reason"],"argTypes":["uuid","uuid","text"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r public.sessions;w uuid;reason text;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF t IS NULL OR requested_reason IS NULL OR requested_reason NOT IN(''completed'',''failed'',''stopped_by_user'',''stalled_reclaimed'',''timeout'')\n THEN RAISE EXCEPTION ''invalid_turn_release'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF w IS NOT NULL THEN PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;END IF;\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND OR r.status<>''running'' OR r.turn_lease_token IS DISTINCT FROM t THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n reason:=CASE WHEN r.cancel_requested_at IS NOT NULL THEN ''stopped_by_user'' ELSE requested_reason END;\n UPDATE public.sessions SET status=CASE WHEN reason=''failed'' THEN ''failed'' WHEN reason IN(''completed'',''stopped_by_user'',''publication_recovered'') THEN ''idle'' ELSE ''timeout'' END,\n  turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=reason,last_active_at=clock_timestamp()\n  WHERE id=s AND turn_lease_token=t;\n RETURN jsonb_build_object(''turnId'',public.native_session_public_turn_id(w,s,t),''reason'',reason);\nEND "},{"profile":"new","name":"publish_native_session_message_batch","signature":"publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)","argNames":["w","s","payloads","producer","sources","target","operation"],"argTypes":["uuid","uuid","jsonb","text","jsonb","jsonb","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp","plan_cache_mode=force_generic_plan"],"defaultsSQL":null,"appExecute":true,"body":"\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;parent jsonb;payload jsonb;node jsonb;\n envelope boolean:=jsonb_typeof(payloads)=''object'';annotation_command jsonb;session_row sessions;previous uuid;\n a_kind text:=''message_annotation'';a_parent uuid;a_id uuid;a_payload jsonb;a_producer text;a_sources jsonb;a_revision uuid;a_generation bigint;a_target jsonb;\n commands jsonb:=''[]'';prepared jsonb;a_prepared jsonb;t_prepared jsonb;\n a_frame uuid:=gen_random_uuid();t_frame uuid:=gen_random_uuid();leader uuid;compound boolean;\n a_frame_payload jsonb;t_frame_payload jsonb;a_scope jsonb;t_scope jsonb;a_retained jsonb;t_retained jsonb;\n a_tier text;t_tier text;a_teams text[];t_teams text[];a_projects uuid[];t_projects uuid[];\n next_sequence integer;results jsonb;annotation_result jsonb;registration jsonb;original_command jsonb:=jsonb_build_object(''payloads'',payloads,''producer'',producer,''sources'',sources,''target'',target);\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF operation IS NOT NULL THEN\n  registration:=native_conversation_publication_enter(w,s,operation,original_command);\n  IF registration->>''duplicate''=''true'' THEN RETURN registration->''value'';END IF;\n END IF;\n IF envelope THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  annotation_command:=payloads->''annotation'';payloads:=payloads->''messages'';\n  IF annotation_command-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT annotation_command ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  IF annotation_command ? ''kind'' THEN a_kind:=annotation_command->>''kind'';END IF;\n  IF a_kind IS NULL OR a_kind NOT IN(''message_annotation'',''session_title'')\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  a_parent:=(annotation_command->>''parentId'')::uuid;a_id:=(annotation_command->>''id'')::uuid;\n  a_payload:=annotation_command->''content'';a_producer:=annotation_command->>''producer'';a_sources:=annotation_command->''sources'';\n  a_revision:=(annotation_command->>''expectedRevision'')::uuid;a_generation:=(annotation_command->>''expectedGeneration'')::bigint;\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND annotation_command IS NULL\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF annotation_command IS NOT NULL THEN\n IF a_parent IS NULL OR a_id IS NULL OR session_context_payload_shape(a_kind,a_payload) IS NOT TRUE\n  OR length(btrim(a_producer)) NOT BETWEEN 1 AND 256\n  OR jsonb_typeof(a_sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(a_sources) NOT BETWEEN 1 AND 4096\n  OR (SELECT count(DISTINCT(n->>''resourceKind'',n->>''resourceId'')) FROM jsonb_array_elements(a_sources) n)<>jsonb_array_length(a_sources)\n  OR a_kind=''session_title'' AND jsonb_array_length(payloads)<>0\n  OR a_kind=''message_annotation'' AND (NOT EXISTS(SELECT 1 FROM session_messages WHERE workspace_id=w AND session_id=s AND id=a_parent)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a_sources) n WHERE n->>''resourceKind''=''session_message'' AND n->>''resourceId''=a_parent::text))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO STRICT session_row FROM sessions WHERE workspace_id=w AND id=s;\n IF a_kind=''session_title'' THEN\n  IF a_parent<>s OR (a_payload->>''manual'')::boolean IS FALSE AND session_row.title_manually_set THEN\n   RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n  SELECT scope_revision_id INTO previous FROM session_title_heads WHERE workspace_id=w AND session_id=s;\n ELSE\n  SELECT scope_revision_id INTO previous FROM session_message_annotation_heads WHERE workspace_id=w AND session_id=s AND message_id=a_parent;\n END IF;\n IF a_generation IS NOT NULL AND session_row.session_context_generation<>a_generation OR previous IS DISTINCT FROM a_revision\n THEN RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO a_sources FROM jsonb_array_elements(a_sources) WITH ORDINALITY original(n,ordinal);\n\n  a_target:=jsonb_build_object(''workspaceId'',w,''userId'',parent->''userId'',''assistantId'',NULL,''sensitivity'',parent->''sensitivity'',''compartments'',parent->''compartments'',''projectIds'',parent->''projectIds'');\n  commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',a_producer,''sources'',a_sources,''target'',a_target)\n   ||CASE WHEN a_kind=''session_title'' THEN jsonb_build_object(''purpose'',a_kind) ELSE ''{}''::jsonb END);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n IF jsonb_typeof(payload) IS DISTINCT FROM ''object'' OR NOT payload ?& ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']\n  OR payload-ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']<>''{}''\n  OR payload->>''role'' NOT IN(''user'',''assistant'') OR jsonb_typeof(payload->''role'') IS DISTINCT FROM ''string''\n  OR jsonb_typeof(payload->''attachments'') IS DISTINCT FROM ''array'' OR jsonb_array_length(payload->''attachments'')>100\n  OR jsonb_typeof(payload->''channelMessageId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(payload->''senderUserId'') NOT IN(''null'',''string'') OR jsonb_typeof(payload->''senderAssistantId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096\n  OR length(btrim(producer)) NOT BETWEEN 1 AND 256\n  OR entity_derivation_envelope_valid(target) IS NOT TRUE OR target->>''workspaceId'' IS DISTINCT FROM w::text\n  OR target->>''assistantId'' IS NOT NULL OR target->>''userId'' IS NOT NULL AND target->>''userId'' IS DISTINCT FROM actor::text\n  OR parent->>''userId'' IS NOT NULL AND parent->>''userId'' IS DISTINCT FROM target->>''userId''\n  OR payload->>''senderUserId'' IS NOT NULL AND payload->>''senderUserId'' IS DISTINCT FROM actor::text\n  OR payload->>''senderAssistantId'' IS NOT NULL AND (payload->>''role''<>''assistant''\n   OR payload->>''senderAssistantId'' IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')) THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF jsonb_array_length(payloads)>0 THEN\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO sources FROM jsonb_array_elements(sources) WITH ORDINALITY original(n,ordinal);\n commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',producer,''sources'',sources,''target'',target));\n END IF;\n prepared:=conversation_prepare_publications(w,s,commands);\n IF prepared IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF annotation_command IS NOT NULL THEN\n  a_prepared:=prepared->0;a_scope:=a_prepared->''scope'';a_retained:=a_prepared->''retained'';a_tier:=a_scope->>''sensitivity'';\n  a_teams:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''compartments''));a_projects:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''projectIds'')::uuid);\n  a_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',a_sources,''declaredSources'',a_retained);\n END IF;\n IF jsonb_array_length(payloads)>0 THEN\n  t_prepared:=prepared->(jsonb_array_length(prepared)-1);t_scope:=t_prepared->''scope'';t_retained:=t_prepared->''retained'';t_tier:=t_scope->>''sensitivity'';\n  t_teams:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''compartments''));t_projects:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''projectIds'')::uuid);\n  t_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',sources,''declaredSources'',t_retained);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n FOR node IN SELECT value FROM jsonb_array_elements(payload->''attachments'') LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object'' OR node->>''workspaceId'' IS DISTINCT FROM w::text\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t_retained) input WHERE input->>''resourceKind''=''workspace_file'' AND input->>''resourceId''=node->>''fileId'') THEN\n   RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n END LOOP;\n\n compound:=annotation_command IS NOT NULL AND jsonb_array_length(payloads)>0;\n leader:=CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame ELSE a_frame END;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation DEFERRED;END IF;\n INSERT INTO native_turn_publication_work(transaction_id,workspace_id,frame_id,session_id,context,original_sources,prepared,completion_owner,publication_id)\n SELECT txid_current(),w,a_frame,s,native_turn_context(),a_sources,a_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE annotation_command IS NOT NULL\n UNION ALL SELECT txid_current(),w,t_frame,s,native_turn_context(),sources,t_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE jsonb_array_length(payloads)>0;\n INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;\n SELECT coalesce(max(sequence_num),0) INTO next_sequence FROM session_messages WHERE session_id=s;\n WITH a_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_frame,w,s,''turn_frame'',a_frame,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') WHERE annotation_command IS NOT NULL RETURNING id\n ), a_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT id_workspace,id_frame,s,2,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') FROM (SELECT w id_workspace,id id_frame FROM a_frame_revision) ready RETURNING id\n ), a_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,a_frame_payload FROM a_frame_record RETURNING revision_id\n ), a_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_frame,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_frame_contents) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM a_frame_declaration d CROSS JOIN jsonb_array_elements(a_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), a_annotation AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_id,w,s,a_kind,a_parent,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')\n  FROM(SELECT count(*) FROM a_frame_edges) ready WHERE annotation_command IS NOT NULL RETURNING id,created_at\n ), a_annotation_content AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content) SELECT w,id,a_payload FROM a_annotation RETURNING revision_id\n ), a_head AS (\n  INSERT INTO session_message_annotation_heads(message_id,workspace_id,session_id,scope_revision_id)\n  SELECT a_parent,w,s,revision_id FROM a_annotation_content WHERE a_kind=''message_annotation'' ON CONFLICT(message_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING message_id\n ), a_title_head AS (\n  INSERT INTO session_title_heads(workspace_id,session_id,scope_revision_id)\n  SELECT w,s,revision_id FROM a_annotation_content WHERE a_kind=''session_title''\n  ON CONFLICT(session_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING session_id\n ), a_generation AS (\n  UPDATE sessions SET session_context_generation=session_context_generation+1,\n   title=CASE WHEN a_kind=''session_title'' THEN NULL ELSE title END,\n   title_manually_set=CASE WHEN a_kind=''session_title'' THEN (a_payload->>''manual'')::boolean ELSE title_manually_set END\n  FROM(SELECT count(*) FROM a_head) ready CROSS JOIN(SELECT count(*) FROM a_title_head) title_ready\n  WHERE workspace_id=w AND id=s AND annotation_command IS NOT NULL RETURNING id\n ), a_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_id,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_generation) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_annotation_edge AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',a_frame,''1'' FROM a_declaration RETURNING derivation_id\n ), t_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT t_frame,w,s,''turn_frame'',t_frame,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') WHERE jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT w,id,s,2,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') FROM t_frame_revision RETURNING id\n ), t_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,t_frame_payload FROM t_frame_record RETURNING revision_id\n ), t_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',t_frame,''1'',producer,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM t_frame_contents) ready WHERE workspace_id=w AND jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM t_frame_declaration d CROSS JOIN jsonb_array_elements(t_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), t_written AS (\n  INSERT INTO session_messages(session_id,role,content,sequence_num,channel_message_id,sender_user_id,sender_assistant_id,attachments,\n   workspace_id,user_id,assistant_id,sensitivity,compartments,project_ids,scope_version,scope_held)\n  SELECT s,n.value->>''role'',n.value->''content'',next_sequence+n.ordinality,n.value->>''channelMessageId'',\n   (n.value->>''senderUserId'')::uuid,(n.value->>''senderAssistantId'')::uuid,n.value->''attachments'',w,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,1,false\n  FROM jsonb_array_elements(payloads) WITH ORDINALITY n(value,ordinality) CROSS JOIN(SELECT count(*) FROM t_frame_edges) ready\n  ORDER BY n.ordinality RETURNING *\n ), t_declarations AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_message'',m.id,''1'',producer,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,p.revision\n  FROM t_written m CROSS JOIN workspace_access_policies p WHERE p.workspace_id=w RETURNING id,resource_id\n ), t_message_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',t_frame,''1'' FROM t_declarations RETURNING derivation_id\n ), output_rows AS (\n  SELECT a_frame frame_id,jsonb_build_object(''kind'',a_kind,''id'',a_id,''parentId'',a_parent,''derivationId'',d.id,\n   ''payloadDigest'',encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')) value\n  FROM a_declaration d CROSS JOIN(SELECT count(*) FROM a_annotation_edge) ready\n  UNION ALL SELECT t_frame,jsonb_build_object(''id'',m.id,''derivationId'',d.id,''sequence'',m.sequence_num,\n   ''payloadDigest'',encode(sha256(convert_to(jsonb_build_object(''role'',m.role,''content'',m.content,''channelMessageId'',m.channel_message_id,\n    ''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments)::text,''UTF8'')),''hex''))\n  FROM t_written m JOIN t_declarations d ON d.resource_id=m.id CROSS JOIN(SELECT count(*) FROM t_message_edges) ready\n ), seal AS (\n  INSERT INTO native_turn_publication_seals(transaction_id,frame_id,outputs)\n  SELECT txid_current(),leader,jsonb_agg(value||CASE WHEN compound THEN jsonb_build_object(''frameId'',frame_id) ELSE ''{}''::jsonb END ORDER BY frame_id,value::text) FROM output_rows\n  RETURNING native_turn_publication_seals.transaction_id,native_turn_publication_seals.frame_id\n ), debt AS (\n  INSERT INTO native_turn_publication_debt SELECT seal.transaction_id,o.frame_id FROM seal CROSS JOIN(SELECT DISTINCT frame_id FROM output_rows) o\n  RETURNING native_turn_publication_debt.frame_id\n ), registration AS (\n  INSERT INTO native_conversation_publications(id,workspace_id,session_id,input_message_id,actor_user_id,assistant_id,turn_token,slot,\n   command_format,command_digest,stopped,frame_ids,leader_frame_id,expected_output_count,annotation_user_id,annotation_assistant_id,requested_stopped,terminal_descriptor,terminal_outputs)\n  SELECT (operation->>''operationId'')::uuid,w,s,(operation->>''inputMessageId'')::uuid,(operation->>''actorUserId'')::uuid,(operation->>''assistantId'')::uuid,\n   (operation->>''turnToken'')::uuid,''buffered_transcript'',(operation->>''version'')::integer,registration->>''digest'',(registration->>''effectiveStopped'')::boolean,\n   ARRAY(SELECT frame FROM unnest(ARRAY[CASE WHEN annotation_command IS NOT NULL THEN a_frame END,CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame END]) frame WHERE frame IS NOT NULL ORDER BY frame),\n   leader,jsonb_array_length(payloads)+CASE WHEN annotation_command IS NOT NULL THEN 1 ELSE 0 END,session_row.user_id,session_row.assistant_id,\n   CASE WHEN operation->''version''=''2''::jsonb THEN (operation->>''stopped'')::boolean END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' THEN nullif(operation->''terminalCandidate'',''null''::jsonb) END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' AND nullif(operation->''terminalCandidate'',''null''::jsonb) IS NOT NULL THEN\n    (SELECT jsonb_agg(jsonb_build_object(''origin'',m.n->''origin'',''revision'',m.n->''revision'',''commandOrdinal'',m.n->''commandOrdinal'',\n      ''kind'',''session_message'',''version'',''1'',''id'',written.id,''frameId'',t_frame,''derivationId'',d.id,''sequence'',written.sequence_num,\n      ''payloadDigest'',o.value->''payloadDigest'') ORDER BY m.ordinal)\n     FROM jsonb_array_elements(operation#>''{terminalCandidate,members}'') WITH ORDINALITY m(n,ordinal)\n     JOIN t_written written ON written.sequence_num=next_sequence+(m.n->>''commandOrdinal'')::integer+1\n     JOIN t_declarations d ON d.resource_id=written.id JOIN output_rows o ON o.frame_id=t_frame AND o.value->>''id''=written.id::text) END\n  FROM seal CROSS JOIN(SELECT count(*) FROM debt) ready WHERE operation IS NOT NULL RETURNING id\n ) SELECT\n  (SELECT coalesce(jsonb_agg(jsonb_build_object(''message'',jsonb_build_object(''id'',m.id,''sessionId'',s,''role'',m.role,''content'',m.content,\n   ''sequenceNum'',m.sequence_num,''createdAt'',m.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n   ''channelMessageId'',m.channel_message_id,''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments),\n   ''source'',t_scope||jsonb_build_object(''resourceKind'',''session_message'',''resourceId'',m.id,''version'',''1'')) ORDER BY m.sequence_num),''[]'') FROM t_written m),\n  (SELECT jsonb_build_object(''source'',a_scope||jsonb_build_object(''resourceKind'',''session_context_revision'',''resourceId'',a_id,''version'',''1''),\n   ''createdAt'',a.created_at,''userId'',session_row.user_id,''assistantId'',session_row.assistant_id) FROM a_annotation a)\n INTO results,annotation_result FROM(SELECT count(*) FROM debt) ready CROSS JOIN(SELECT count(*) FROM registration) registered;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation IMMEDIATE;END IF;\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN CASE WHEN operation->''version''=''2''::jsonb THEN native_conversation_publication_packet((operation->>''operationId'')::uuid,CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END) ELSE CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END END;\nEXCEPTION WHEN SQLSTATE ''PNT02'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';\nEND "},{"profile":"replace","name":"publish_native_session_message_batch","signature":"publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb)","argNames":["w","s","payloads","producer","sources","target"],"argTypes":["uuid","uuid","jsonb","text","jsonb","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp","plan_cache_mode=force_generic_plan"],"defaultsSQL":null,"appExecute":true,"body":"\nBEGIN RETURN publish_native_session_message_batch(w,s,payloads,producer,sources,target,NULL);END "},{"profile":"replace","name":"native_turn_complete_publication","signature":"native_turn_complete_publication()","argNames":[],"argTypes":[],"returnType":"trigger","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE work native_turn_publication_work;leader native_turn_publication_work;fresh jsonb;item jsonb;message session_messages;d scope_derivations;\n expected_scope jsonb;actual_scope jsonb;actual_payload jsonb;events jsonb;actual_events jsonb;frame_content jsonb;frame_scope jsonb;annotation session_context_scope_revisions;\n members uuid[];cohort_outputs jsonb;commands jsonb;proofs jsonb;ordinal integer:=0;publication native_conversation_publications;committed_outputs jsonb;\nBEGIN\n SELECT * INTO leader FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=NEW.frame_id;\n IF leader.frame_id IS NULL OR NEW.transaction_id<>txid_current() OR native_turn_helpers_current() IS NOT TRUE\n  OR native_turn_context() IS DISTINCT FROM leader.context OR leader.completion_owner IS NOT NULL AND leader.completion_owner<>leader.frame_id\n  OR jsonb_typeof(NEW.outputs) IS DISTINCT FROM ''array''\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT array_agg(frame_id ORDER BY frame_id),jsonb_agg(jsonb_build_object(''producer'',''native:turn-frame'',''sources'',original_sources,''target'',prepared->''scope'')\n  ||CASE WHEN prepared ? ''purpose'' THEN jsonb_build_object(''purpose'',prepared->''purpose'') ELSE ''{}''::jsonb END ORDER BY frame_id)\n INTO members,commands FROM native_turn_publication_work\n WHERE transaction_id=txid_current() AND (leader.completion_owner IS NULL AND frame_id=leader.frame_id OR completion_owner=leader.frame_id);\n IF leader.completion_owner IS NULL THEN\n  IF cardinality(members)<>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.outputs) n WHERE n ? ''frameId'')\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n ELSE\n  IF cardinality(members)<>2 OR jsonb_array_length(NEW.outputs) NOT BETWEEN 2 AND 513\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.outputs) n WHERE NOT n ? ''frameId'' OR NOT (n->>''frameId'')::uuid=ANY(members))\n   OR (SELECT count(*) FROM jsonb_array_elements(NEW.outputs) n WHERE n->>''kind''=''message_annotation'')<>1\n   OR EXISTS(SELECT 1 FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=ANY(members) AND frame_id<>leader.frame_id)\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END IF;\n -- The independent completion command observes every payload/head mutation.\n proofs:=conversation_prepare_publications(leader.workspace_id,leader.session_id,commands);\n FOR work IN SELECT * FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=ANY(members) ORDER BY frame_id LOOP\n  IF (work.workspace_id,work.session_id,work.context,work.completion_owner,work.publication_id) IS DISTINCT FROM\n   (leader.workspace_id,leader.session_id,leader.context,leader.completion_owner,leader.publication_id)\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  SELECT jsonb_agg(n) INTO cohort_outputs FROM jsonb_array_elements(NEW.outputs) n\n   WHERE leader.completion_owner IS NULL OR n->>''frameId''=work.frame_id::text;\n  IF leader.completion_owner IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(cohort_outputs) n WHERE n ? ''kind'')\n   AND (jsonb_array_length(cohort_outputs)<>1 OR cohort_outputs->0->>''kind'' IS DISTINCT FROM ''message_annotation'')\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF work.frame_id IS NULL OR NEW.transaction_id<>txid_current()\n  OR native_turn_context() IS DISTINCT FROM work.context OR native_turn_frame_pair(work.workspace_id,work.frame_id) IS NOT TRUE\n  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=work.frame_id)\n  OR EXISTS(SELECT 1 FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id AND NOT fired)\n  OR jsonb_typeof(cohort_outputs) IS DISTINCT FROM ''array'' OR jsonb_array_length(cohort_outputs) NOT BETWEEN 1 AND 512\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n expected_scope:=work.prepared->''scope'';\n SELECT c.content,jsonb_build_object(''workspaceId'',r.workspace_id,''userId'',r.user_id,''assistantId'',r.assistant_id,\n  ''sensitivity'',r.sensitivity,''compartments'',r.compartments,''projectIds'',r.project_ids)\n INTO frame_content,frame_scope FROM session_context_scope_revisions r JOIN session_context_revision_contents c\n ON c.workspace_id=r.workspace_id AND c.revision_id=r.id WHERE r.workspace_id=work.workspace_id AND r.id=work.frame_id;\n IF frame_content->''originalSources'' IS DISTINCT FROM work.original_sources\n  OR frame_content->''declaredSources'' IS DISTINCT FROM work.prepared->''retained'' OR frame_scope IS DISTINCT FROM expected_scope\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n FOR item IN SELECT value FROM jsonb_array_elements(cohort_outputs) LOOP\n  IF item->>''kind'' IN(''message_annotation'',''session_title'') THEN\n   SELECT * INTO annotation FROM session_context_scope_revisions WHERE workspace_id=work.workspace_id AND session_id=work.session_id AND id=(item->>''id'')::uuid;\n   SELECT * INTO d FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(item->>''derivationId'')::uuid;\n   SELECT c.content INTO actual_payload FROM session_context_revision_contents c WHERE c.workspace_id=work.workspace_id AND c.revision_id=annotation.id;\n   actual_scope:=jsonb_build_object(''workspaceId'',annotation.workspace_id,''userId'',annotation.user_id,''assistantId'',annotation.assistant_id,\n    ''sensitivity'',annotation.sensitivity,''compartments'',annotation.compartments,''projectIds'',annotation.project_ids);\n   IF annotation.id IS NULL OR annotation.parent_kind IS DISTINCT FROM item->>''kind'' OR annotation.parent_id::text IS DISTINCT FROM item->>''parentId''\n    OR annotation.scope_version<>1 OR annotation.scope_held OR scope_review_state_held(''session_context_revision'',annotation.id)\n    OR actual_scope IS DISTINCT FROM expected_scope OR actual_payload IS NULL OR session_context_payload_shape(item->>''kind'',actual_payload) IS NOT TRUE\n    OR annotation.payload_sha256 IS DISTINCT FROM item->>''payloadDigest'' OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(actual_payload::text,''UTF8'')),''hex'')\n    OR item->>''kind''=''message_annotation'' AND (NOT EXISTS(SELECT 1 FROM session_messages m JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id\n     WHERE m.workspace_id=work.workspace_id AND m.session_id=work.session_id AND m.id=annotation.parent_id AND h.scope_revision_id=annotation.id)\n    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(work.original_sources) n WHERE n->>''resourceKind''=''session_message'' AND n->>''resourceId''=annotation.parent_id::text))\n    OR item->>''kind''=''session_title'' AND (work.prepared->>''purpose'' IS DISTINCT FROM ''session_title''\n     OR annotation.parent_id IS DISTINCT FROM work.session_id\n     OR NOT EXISTS(SELECT 1 FROM session_title_heads h JOIN sessions s ON s.workspace_id=h.workspace_id AND s.id=h.session_id\n      WHERE h.workspace_id=work.workspace_id AND h.session_id=work.session_id AND h.scope_revision_id=annotation.id\n       AND s.title IS NULL AND s.title_manually_set IS NOT DISTINCT FROM (actual_payload->>''manual'')::boolean))\n    OR d.id IS NULL OR d.resource_kind IS DISTINCT FROM ''session_context_revision'' OR d.resource_id IS DISTINCT FROM annotation.id OR d.resource_version IS DISTINCT FROM ''1''\n    OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM\n      (annotation.user_id,annotation.assistant_id,annotation.sensitivity,annotation.compartments,annotation.project_ids)\n    OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id)<>1\n    OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id AND source_kind=''session_context_revision'' AND source_id=work.frame_id AND source_version=''1'')\n   THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n   CONTINUE;\n  END IF;\n  IF item ? ''kind'' THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  SELECT * INTO message FROM session_messages WHERE workspace_id=work.workspace_id AND session_id=work.session_id AND id=(item->>''id'')::uuid;\n  SELECT * INTO d FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(item->>''derivationId'')::uuid;\n  actual_scope:=jsonb_build_object(''workspaceId'',message.workspace_id,''userId'',message.user_id,''assistantId'',message.assistant_id,\n   ''sensitivity'',message.sensitivity,''compartments'',message.compartments,''projectIds'',message.project_ids);\n  actual_payload:=jsonb_build_object(''role'',message.role,''content'',message.content,''channelMessageId'',message.channel_message_id,\n   ''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments);\n  IF message.id IS NULL OR message.scope_held OR scope_review_state_held(''session_message'',message.id) OR message.scope_version<>1 OR message.sequence_num IS DISTINCT FROM (item->>''sequence'')::integer\n   OR actual_scope IS DISTINCT FROM expected_scope OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(actual_payload::text,''UTF8'')),''hex'')\n   OR d.id IS NULL OR d.resource_kind IS DISTINCT FROM ''session_message'' OR d.resource_id IS DISTINCT FROM message.id OR d.resource_version IS DISTINCT FROM ''1''\n   OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM\n      (message.user_id,message.assistant_id,message.sensitivity,message.compartments,message.project_ids)\n   OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id)<>1\n   OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id\n    AND source_kind=''session_context_revision'' AND source_id=work.frame_id AND source_version=''1'') THEN\n   RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n END LOOP;\n SELECT jsonb_agg(event ORDER BY event::text) INTO events FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id;\n SELECT jsonb_agg(to_jsonb(e) ORDER BY to_jsonb(e)::text) INTO actual_events FROM scope_derivation_sources e JOIN scope_derivations actual_derivation ON actual_derivation.workspace_id=e.workspace_id AND actual_derivation.id=e.derivation_id\n WHERE actual_derivation.workspace_id=work.workspace_id AND (actual_derivation.resource_kind=''session_context_revision'' AND actual_derivation.resource_id=work.frame_id\n  OR actual_derivation.id IN(SELECT (n->>''derivationId'')::uuid FROM jsonb_array_elements(cohort_outputs) n));\n IF events IS NULL OR events IS DISTINCT FROM actual_events THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n\n  fresh:=proofs->ordinal;ordinal:=ordinal+1;\n  IF fresh IS NULL OR (fresh-''proof'') IS DISTINCT FROM work.prepared OR native_turn_context() IS DISTINCT FROM work.context\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  IF fresh#>>''{proof,validUntil}'' IS NULL OR clock_timestamp()>=(fresh#>>''{proof,validUntil}'')::timestamptz\n  THEN RAISE EXCEPTION ''native_turn_policy_expired'' USING ERRCODE=''42501'';END IF;\n END LOOP;\n IF ordinal<>cardinality(members) OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF leader.publication_id IS NOT NULL THEN\n  SELECT * INTO publication FROM native_conversation_publications WHERE id=leader.publication_id FOR UPDATE;\n  IF publication.id IS NULL OR publication.workspace_id<>leader.workspace_id OR publication.session_id<>leader.session_id\n   OR publication.leader_frame_id<>leader.frame_id OR publication.frame_ids IS DISTINCT FROM members\n   OR publication.expected_output_count<>jsonb_array_length(NEW.outputs) OR publication.completed_at IS NOT NULL\n   OR publication.actor_user_id::text IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')\n   OR publication.assistant_id::text IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  SELECT jsonb_agg(output.n||jsonb_build_object(''kind'',coalesce(output.n->>''kind'',''session_message''),''version'',''1'',\n   ''frameId'',coalesce(output.n->>''frameId'',leader.frame_id::text)) ORDER BY output.ordinal) INTO committed_outputs\n   FROM jsonb_array_elements(NEW.outputs) WITH ORDINALITY output(n,ordinal);\n  IF publication.command_format=2 AND native_conversation_terminal_subset(publication.terminal_descriptor,publication.terminal_outputs,committed_outputs) IS NOT TRUE\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  UPDATE native_conversation_publications SET outputs=committed_outputs,completed_at=clock_timestamp() WHERE id=publication.id;\n END IF;\n UPDATE native_turn_publication_work SET completion_ready=true WHERE transaction_id=txid_current() AND frame_id=ANY(members);\n DELETE FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=ANY(members);\n DELETE FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=ANY(members);\n DELETE FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=leader.frame_id;\n DELETE FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=ANY(members);\n RETURN NULL;\nEND "}]'::jsonb;
 spec jsonb;actual pg_proc;reference pg_proc;expected jsonb;prior jsonb;declaration text;
 argument text;type_name text;argument_name text;defaults text[];reference_name text;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 runtime_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
 expected_acl aclitem[];ordinal integer:=0;arg_position integer;argument_count integer;
 required constant text[]:=ARRAY[
  'native_conversation_publication_scope(uuid,uuid)',
  'native_conversation_publication_result(uuid,uuid,uuid)',
  'native_conversation_publication_enter(uuid,uuid,jsonb,jsonb)',
  'native_conversation_publication_complete()',
  'native_conversation_publication_immutable()',
  'read_native_conversation_publications(uuid,uuid,jsonb,integer)',
  'publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)',
  'publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb)',
  'native_turn_complete_publication()',
  'native_session_turn_publication_state(uuid,uuid,uuid)',  'native_conversation_terminal_candidate_valid(jsonb,jsonb,uuid)',  'native_conversation_terminal_subset(jsonb,jsonb,jsonb)',  'native_conversation_publication_packet(uuid,jsonb)',  'native_session_public_turn_id(uuid,uuid,uuid)',  'native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)',  'native_session_turn_transition(uuid,text,uuid,timestamp with time zone,integer,uuid,text,boolean)',  'native_session_release_turn(uuid,uuid,text)'];
BEGIN
 IF jsonb_typeof(specs) IS DISTINCT FROM 'array'
  OR (SELECT count(*) FROM jsonb_array_elements(specs))<>cardinality(required)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(specs) s WHERE NOT(s->>'signature'=ANY(required)))
  OR (SELECT count(DISTINCT s->>'signature') FROM jsonb_array_elements(specs) s)<>cardinality(required)
  OR runtime_id IS NULL OR EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D')
 THEN RAISE EXCEPTION 'publication_source_spec_roster_changed' USING ERRCODE='55000';END IF;
 FOR spec IN SELECT value FROM jsonb_array_elements(specs) LOOP
  IF spec-ARRAY['profile','name','signature','argNames','argTypes','returnType','language','volatility','secdef','config','defaultsSQL','appExecute','body']<>'{}'
   OR NOT spec ?& ARRAY['profile','name','signature','argNames','argTypes','returnType','language','volatility','secdef','config','defaultsSQL','appExecute','body']
   OR spec->>'language'<>'plpgsql' OR spec->>'volatility'<>'v' OR spec->'secdef'<>'true'::jsonb
   OR spec->>'returnType' NOT IN('jsonb','trigger','text','boolean') OR jsonb_typeof(spec->'body') IS DISTINCT FROM 'string'
   OR spec->>'name' IS DISTINCT FROM split_part(spec->>'signature','(',1)
   OR jsonb_typeof(spec->'argNames') IS DISTINCT FROM 'array' OR jsonb_typeof(spec->'argTypes') IS DISTINCT FROM 'array'
   OR jsonb_array_length(spec->'argNames')<>jsonb_array_length(spec->'argTypes')
   OR (spec->>'profile'='replace') IS DISTINCT FROM ((spec->>'signature')=ANY(ARRAY[
    'publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb)','native_turn_complete_publication()']))
   OR spec->>'profile' NOT IN('new','replace')
   OR (spec->'appExecute'='true'::jsonb) IS DISTINCT FROM ((spec->>'signature')=ANY(ARRAY[
    'native_session_turn_publication_state(uuid,uuid,uuid)',
    'read_native_conversation_publications(uuid,uuid,jsonb,integer)',
    'publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)',
    'publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb)']))
  THEN RAISE EXCEPTION 'publication_source_spec_changed: %',spec->>'signature' USING ERRCODE='55000';END IF;
  IF spec->'config' IS DISTINCT FROM (CASE WHEN spec->>'name'='publish_native_session_message_batch'
   THEN '["search_path=pg_catalog, public, pg_temp","plan_cache_mode=force_generic_plan"]'::jsonb
   ELSE '["search_path=pg_catalog, public, pg_temp"]'::jsonb END)
  THEN RAISE EXCEPTION 'publication_source_config_changed: %',spec->>'signature';END IF;
  defaults:=NULL;
  IF spec->>'signature'='read_native_conversation_publications(uuid,uuid,jsonb,integer)' THEN
   IF spec->>'defaultsSQL' IS DISTINCT FROM 'NULL::jsonb, 20' THEN RAISE EXCEPTION 'publication_source_defaults_changed';END IF;
   defaults:=ARRAY['NULL::jsonb','20'];
  ELSIF spec->'defaultsSQL' IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION 'publication_source_defaults_changed';
  END IF;
  declaration:='';argument_count:=jsonb_array_length(spec->'argTypes');
  FOR arg_position IN 0..argument_count-1 LOOP
   type_name:=spec#>>ARRAY['argTypes',arg_position::text];argument_name:=spec#>>ARRAY['argNames',arg_position::text];
   IF type_name NOT IN('uuid','jsonb','text','integer','boolean','timestamp with time zone') OR argument_name IS NULL OR argument_name='' THEN
    RAISE EXCEPTION 'publication_source_argument_changed';END IF;
   argument:=format('%I %s',argument_name,type_name);
   IF defaults IS NOT NULL AND arg_position>=argument_count-cardinality(defaults) THEN
    argument:=argument||' DEFAULT '||defaults[arg_position-(argument_count-cardinality(defaults))+1];
   END IF;
   declaration:=declaration||CASE WHEN arg_position=0 THEN '' ELSE ',' END||argument;
  END LOOP;
  ordinal:=ordinal+1;reference_name:='publication_source_reference_'||ordinal;
  IF to_regprocedure('pg_temp.'||reference_name||'('||
   (SELECT coalesce(string_agg(value,',' ORDER BY n),'') FROM jsonb_array_elements_text(spec->'argTypes') WITH ORDINALITY x(value,n))||')') IS NOT NULL
  THEN RAISE EXCEPTION 'publication_source_reference_exists';END IF;
  EXECUTE format('CREATE FUNCTION pg_temp.%I(%s) RETURNS %s LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp %s AS %L',
   reference_name,declaration,spec->>'returnType',
   CASE WHEN spec->>'name'='publish_native_session_message_batch' THEN 'SET plan_cache_mode=force_generic_plan' ELSE '' END,spec->>'body');
  SELECT * INTO STRICT reference FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=reference_name;
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(spec->>'signature'));
  IF actual.oid IS NULL THEN RAISE EXCEPTION 'publication_source_function_missing: %',spec->>'signature';END IF;
  IF spec->>'profile'='replace' THEN
   SELECT metadata INTO prior FROM publication_reviewed_contracts WHERE signature=spec->>'signature';
   IF prior IS NULL THEN RAISE EXCEPTION 'publication_source_predecessor_missing';END IF;
   -- An existing signature keeps its exact authenticated raw ACL, including order.
   expected:=prior->'proacl';
  ELSE
   expected_acl:=ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)];
   IF (spec->>'appExecute')::boolean THEN expected_acl:=expected_acl||makeaclitem(runtime_id,owner_id,'EXECUTE',false);END IF;
   expected:=to_jsonb(expected_acl);
  END IF;
  expected:=(to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])||jsonb_build_object(
   'oid',actual.oid,'proname',spec->>'name','pronamespace','public'::regnamespace::oid,'proowner',owner_id,'proacl',expected);
  IF to_jsonb(actual) IS DISTINCT FROM expected OR (actual.prosrc COLLATE "C") IS DISTINCT FROM ((spec->>'body') COLLATE "C") THEN
   RAISE EXCEPTION 'publication_source_successor_changed: %',spec->>'signature' USING ERRCODE='55000';
  END IF;
  INSERT INTO publication_source_functions VALUES(spec->>'signature',expected,jsonb_build_array(spec->>'body'));
  EXECUTE format('DROP FUNCTION pg_temp.%I(%s)',reference_name,
   (SELECT coalesce(string_agg(value,',' ORDER BY n),'') FROM jsonb_array_elements_text(spec->'argTypes') WITH ORDINALITY x(value,n)));
 END LOOP;
 INSERT INTO publication_expected_current SELECT signature,metadata FROM publication_source_functions
  ON CONFLICT(signature) DO UPDATE SET metadata=EXCLUDED.metadata;
 INSERT INTO publication_successor_templates SELECT signature,body_parts FROM publication_source_functions
  ON CONFLICT(signature) DO UPDATE SET parts=EXCLUDED.parts;
 PERFORM pg_temp.publication_assert_expected_functions();
END $source_functions$;

-- These compiler references are source declarations, not LIKE/copies of target tables.
CREATE FUNCTION pg_temp.publication_reference_schema() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $reference$
BEGIN
 IF to_regnamespace('publication_source_reference') IS NOT NULL THEN
  RAISE EXCEPTION 'publication_source_reference_schema_exists';END IF;
 EXECUTE 'CREATE SCHEMA publication_source_reference';
 IF NOT EXISTS(SELECT FROM pg_namespace WHERE nspname='publication_source_reference'
  AND nspowner=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  AND coalesce(nspacl,acldefault('n',nspowner)) IS NOT DISTINCT FROM acldefault('n',nspowner))
 THEN RAISE EXCEPTION 'publication_reference_schema_private_profile_changed';END IF;
 EXECUTE $ddl$CREATE TABLE publication_source_reference.native_conversation_publications(
 id uuid PRIMARY KEY,
 workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
 session_id uuid NOT NULL REFERENCES public.sessions(id) ON DELETE CASCADE,
 input_message_id uuid NOT NULL REFERENCES public.session_messages(id) ON DELETE CASCADE,
 actor_user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
 assistant_id uuid NOT NULL REFERENCES public.assistants(id) ON DELETE CASCADE,
 turn_token uuid NOT NULL,slot text NOT NULL CHECK(slot='buffered_transcript'),
 command_format integer NOT NULL CHECK(command_format IN(1,2)),command_digest text NOT NULL CHECK(command_digest~'^[a-f0-9]{64}$'),
 stopped boolean NOT NULL,frame_ids uuid[] NOT NULL CHECK(cardinality(frame_ids) BETWEEN 1 AND 2),
 leader_frame_id uuid NOT NULL,expected_output_count integer NOT NULL CHECK(expected_output_count BETWEEN 1 AND 513),
 annotation_user_id uuid,annotation_assistant_id uuid,outputs jsonb,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,
 requested_stopped boolean,terminal_descriptor jsonb,terminal_outputs jsonb,
 CONSTRAINT native_conversation_terminal_format CHECK(
  command_format=1 AND requested_stopped IS NULL AND terminal_descriptor IS NULL AND terminal_outputs IS NULL
  OR command_format=2 AND requested_stopped IS NOT NULL AND (NOT requested_stopped OR stopped)
   AND (terminal_descriptor IS NULL)=(terminal_outputs IS NULL) AND (NOT stopped OR terminal_descriptor IS NULL)),
 CONSTRAINT native_conversation_publication_slot UNIQUE(workspace_id,session_id,turn_token,slot),
 CONSTRAINT native_conversation_publication_result CHECK((outputs IS NULL)=(completed_at IS NULL)))$ddl$;
 EXECUTE 'CREATE INDEX native_conversation_publication_discovery ON publication_source_reference.native_conversation_publications(workspace_id,session_id,actor_user_id,assistant_id,created_at,id)';
 EXECUTE 'REVOKE ALL ON publication_source_reference.native_conversation_publications FROM PUBLIC,app_user';
 EXECUTE 'ALTER TABLE publication_source_reference.native_conversation_publications ENABLE ROW LEVEL SECURITY';
 EXECUTE $ddl$CREATE TABLE publication_source_reference.native_turn_publication_work(publication_id uuid,
  CONSTRAINT native_turn_publication_operation FOREIGN KEY(publication_id)
  REFERENCES publication_source_reference.native_conversation_publications(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED)$ddl$;
 EXECUTE 'REVOKE ALL ON publication_source_reference.native_turn_publication_work FROM PUBLIC,app_user';
 IF EXISTS(SELECT FROM pg_class WHERE relnamespace='publication_source_reference'::regnamespace
  AND relkind='r' AND (relowner<>(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
   OR relacl IS DISTINCT FROM acldefault('r',relowner)))
 THEN RAISE EXCEPTION 'publication_reference_table_private_profile_changed';END IF;
 EXECUTE 'CREATE CONSTRAINT TRIGGER native_conversation_publication_complete AFTER INSERT ON publication_source_reference.native_conversation_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.native_conversation_publication_complete()';
 EXECUTE 'CREATE TRIGGER native_conversation_publication_immutable BEFORE UPDATE ON publication_source_reference.native_conversation_publications FOR EACH ROW EXECUTE FUNCTION public.native_conversation_publication_immutable()';
END $reference$;

CREATE FUNCTION pg_temp.publication_map_reference_relation(relation_id oid) RETURNS oid
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE relation_name name;namespace_name name;mapped oid;
BEGIN
 IF relation_id=0 THEN RETURN 0;END IF;
 SELECT c.relname,n.nspname INTO STRICT relation_name,namespace_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=relation_id;
 IF namespace_name<>'publication_source_reference' THEN RETURN relation_id;END IF;
 mapped:=to_regclass(format('public.%I',relation_name));
 IF mapped IS NULL THEN RAISE EXCEPTION 'publication_reference_relation_missing: %',relation_name;END IF;
 RETURN mapped;
END $map$;
CREATE FUNCTION pg_temp.publication_map_reference_constraint(constraint_id oid) RETURNS oid
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE original pg_constraint;mapped oid;
BEGIN
 IF constraint_id=0 THEN RETURN 0;END IF;
 SELECT * INTO STRICT original FROM pg_constraint WHERE oid=constraint_id;
 SELECT oid INTO STRICT mapped FROM pg_constraint WHERE conrelid=pg_temp.publication_map_reference_relation((original).conrelid) AND conname=(original).conname;
 RETURN mapped;
END $map$;
CREATE FUNCTION pg_temp.publication_map_reference_attributes(relation_id oid,attributes smallint[]) RETURNS smallint[]
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE mapped smallint;
BEGIN
 IF relation_id<>'publication_source_reference.native_turn_publication_work'::regclass OR attributes IS NULL THEN RETURN attributes;END IF;
 IF attributes<>ARRAY[1]::smallint[] THEN RAISE EXCEPTION 'publication_reference_attribute_shape';END IF;
 SELECT attnum INTO STRICT mapped FROM pg_attribute WHERE attrelid='public.native_turn_publication_work'::regclass AND attname='publication_id' AND NOT attisdropped;
 RETURN ARRAY[mapped];
END $map$;
CREATE FUNCTION pg_temp.publication_reference_constraint_record(original pg_constraint) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
 SELECT (to_jsonb(original)-ARRAY['oid','connamespace','conrelid','conindid','confrelid','conkey','confkey'])||jsonb_build_object(
  'oid',pg_temp.publication_map_reference_constraint((original).oid),'connamespace','public'::regnamespace::oid,
  'conrelid',pg_temp.publication_map_reference_relation((original).conrelid),
  'conindid',pg_temp.publication_map_reference_relation((original).conindid),
  'confrelid',pg_temp.publication_map_reference_relation((original).confrelid),
  'conkey',pg_temp.publication_map_reference_attributes((original).conrelid,(original).conkey),
  'confkey',pg_temp.publication_map_reference_attributes((original).confrelid,(original).confkey))
$map$;
CREATE FUNCTION pg_temp.publication_reference_trigger_record(original pg_trigger) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE mapped oid;trigger_name text;prefix text;
BEGIN
 IF (original).tgisinternal THEN
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.publication_map_reference_relation((original).tgrelid)
   AND tgconstraint=pg_temp.publication_map_reference_constraint((original).tgconstraint) AND tgtype=(original).tgtype AND tgisinternal;
  IF right((original).tgname::text,length((original).oid::text))<>(original).oid::text THEN RAISE EXCEPTION 'publication_reference_internal_name';END IF;
  prefix:=left((original).tgname::text,length((original).tgname::text)-length((original).oid::text));
  IF prefix NOT IN('RI_ConstraintTrigger_a_','RI_ConstraintTrigger_c_') THEN RAISE EXCEPTION 'publication_reference_internal_kind';END IF;
  trigger_name:=prefix||mapped::text;
 ELSE
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.publication_map_reference_relation((original).tgrelid) AND tgname=(original).tgname;
  trigger_name:=(original).tgname;
 END IF;
 RETURN (to_jsonb(original)-ARRAY['oid','tgname','tgrelid','tgconstraint','tgconstrrelid','tgconstrindid'])||jsonb_build_object(
  'oid',mapped,'tgname',trigger_name,'tgrelid',pg_temp.publication_map_reference_relation((original).tgrelid),
  'tgconstraint',pg_temp.publication_map_reference_constraint((original).tgconstraint),
  'tgconstrrelid',pg_temp.publication_map_reference_relation((original).tgconstrrelid),
  'tgconstrindid',pg_temp.publication_map_reference_relation((original).tgconstrindid));
END $map$;

CREATE FUNCTION pg_temp.publication_relation_semantics(relation_record pg_class) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $shape$
 SELECT jsonb_build_object('name',(relation_record).relname,'owner',(relation_record).relowner,'kind',(relation_record).relkind,
  'persistence',(relation_record).relpersistence,'am',(relation_record).relam,'tablespace',(relation_record).reltablespace,
  'options',(relation_record).reloptions,'replicaIdentity',(relation_record).relreplident,'ofType',(relation_record).reloftype,
  'attributes',(relation_record).relnatts,'checks',(relation_record).relchecks,'hasIndex',(relation_record).relhasindex,
  'hasRules',(relation_record).relhasrules,'hasTriggers',(relation_record).relhastriggers,'hasSubclass',(relation_record).relhassubclass,
  'rls',(relation_record).relrowsecurity,'forceRls',(relation_record).relforcerowsecurity,'partition',(relation_record).relispartition,
  'partitionBound',(relation_record).relpartbound,'acl',(relation_record).relacl)
$shape$;

CREATE FUNCTION pg_temp.publication_schema_details() RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $details$
 SELECT jsonb_build_object(
  'header',pg_temp.publication_relation_semantics(c),
  'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0),
  'constraints',(SELECT jsonb_agg(to_jsonb(k) ORDER BY k.conname COLLATE "C") FROM pg_constraint k WHERE k.conrelid=c.oid),
  'indexes',(SELECT jsonb_agg(jsonb_build_object('index',to_jsonb(i),'relation',pg_temp.publication_relation_semantics(r)) ORDER BY r.relname COLLATE "C")
   FROM pg_index i JOIN pg_class r ON r.oid=i.indexrelid WHERE i.indrelid=c.oid),
  'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.adnum) FROM pg_attrdef d WHERE d.adrelid=c.oid),
  'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid=c.oid),
  'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE r.ev_class=c.oid),
  'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE p.polrelid=c.oid),
  'inheritance',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhseqno) FROM pg_inherits i WHERE i.inhrelid=c.oid OR i.inhparent=c.oid),
  'workColumn',(SELECT to_jsonb(a) FROM pg_attribute a WHERE a.attrelid='public.native_turn_publication_work'::regclass AND a.attname='publication_id' AND NOT a.attisdropped),
  'workConstraint',(SELECT to_jsonb(k) FROM pg_constraint k WHERE k.conrelid='public.native_turn_publication_work'::regclass AND k.conname='native_turn_publication_operation'),
  'workTriggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
   WHERE k.conrelid='public.native_turn_publication_work'::regclass AND k.conname='native_turn_publication_operation' AND t.tgrelid=k.conrelid))
 FROM pg_class c WHERE c.oid='public.native_conversation_publications'::regclass
$details$;
CREATE TEMP TABLE publication_before_installer_details(snapshot jsonb NOT NULL) ON COMMIT DROP;

-- PG18 back branches reserve pg_attver for the engine's durable attribute
-- version (XLogRecPtr/uint64). Only this typed installation identity differs
-- between independently compiled objects. Every other option stays literal;
-- the authenticated before/after snapshot below retains the FULL actual value.
CREATE FUNCTION pg_temp.publication_attribute_semantics(attribute_record pg_attribute) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $attribute$
DECLARE option_value text;options text[];versions integer:=0;decimal_value text;
BEGIN
 IF (attribute_record).attoptions IS NULL THEN RETURN to_jsonb(attribute_record);END IF;
 options:=ARRAY[]::text[];
 FOREACH option_value IN ARRAY (attribute_record).attoptions LOOP
  IF split_part(option_value,'=',1)='pg_attver' THEN
   versions:=versions+1;decimal_value:=substring(option_value FROM length('pg_attver=')+1);
   IF versions>1 OR option_value!~'^pg_attver=(0|[1-9][0-9]{0,19})$' THEN
    RAISE EXCEPTION 'publication_attribute_version_option_changed' USING ERRCODE='55000';END IF;
   IF decimal_value::numeric>18446744073709551615::numeric THEN
    RAISE EXCEPTION 'publication_attribute_version_option_changed' USING ERRCODE='55000';END IF;
   options:=array_append(options,'pg_attver=__ENGINE_ATTRIBUTE_VERSION__');
  ELSE options:=array_append(options,option_value);END IF;
 END LOOP;
 RETURN jsonb_set(to_jsonb(attribute_record),'{attoptions}',to_jsonb(options));
END $attribute$;

CREATE FUNCTION pg_temp.publication_assert_source_schema() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $schema$
DECLARE actual jsonb;expected jsonb;item record;original pg_attribute;attribute_json jsonb;
 actual_header oid:='public.native_conversation_publications'::regclass;
 actual_work oid:='public.native_turn_publication_work'::regclass;
 reference_header oid;reference_work oid;new_attribute integer;old_snapshot jsonb;
BEGIN
 -- Reference equality must not bless ambient third-party default grants.
 IF NOT EXISTS(SELECT FROM pg_class WHERE oid=actual_header
  AND relowner=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  AND relacl IS NOT DISTINCT FROM acldefault('r',relowner)
  AND relkind='r' AND relpersistence='p' AND relrowsecurity AND NOT relforcerowsecurity)
 THEN RAISE EXCEPTION 'publication_header_private_profile_changed' USING ERRCODE='55000';END IF;
 PERFORM pg_temp.publication_reference_schema();
 reference_header:='publication_source_reference.native_conversation_publications'::regclass;
 reference_work:='publication_source_reference.native_turn_publication_work'::regclass;
 SELECT snapshot INTO STRICT old_snapshot FROM publication_predecessor_table_snapshot;
 SELECT coalesce(max((value->>1)::integer),0)+1 INTO new_attribute FROM jsonb_array_elements(old_snapshot->'columns')
  WHERE value->>0=actual_work::text;
 IF (SELECT count(*) FROM pg_attribute WHERE attrelid=actual_work AND attname='publication_id' AND attnum=new_attribute AND NOT attisdropped)<>1
 THEN RAISE EXCEPTION 'publication_work_column_position_changed';END IF;

 SELECT pg_temp.publication_relation_semantics(c) INTO actual FROM pg_class c WHERE oid=actual_header;
 SELECT pg_temp.publication_relation_semantics(c) INTO expected FROM pg_class c WHERE oid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_relation_changed' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM pg_rewrite WHERE ev_class=actual_header) OR EXISTS(SELECT FROM pg_policy WHERE polrelid=actual_header)
  OR EXISTS(SELECT FROM pg_inherits WHERE inhrelid=actual_header OR inhparent=actual_header)
 THEN RAISE EXCEPTION 'publication_header_extra_schema';END IF;
 SELECT jsonb_agg(pg_temp.publication_attribute_semantics(a) ORDER BY a.attnum) INTO actual FROM pg_attribute a WHERE a.attrelid=actual_header AND a.attnum>0;
 SELECT jsonb_agg((pg_temp.publication_attribute_semantics(a)-'attrelid')||jsonb_build_object('attrelid',actual_header) ORDER BY a.attnum) INTO expected
  FROM pg_attribute a WHERE a.attrelid=reference_header AND a.attnum>0;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'publication_header_columns_changed' USING DETAIL=(SELECT jsonb_agg(jsonb_build_object('attribute',coalesce(a.value->>'attname',e.value->>'attname'),'actual',a.value,'expected',e.value))::text
   FROM jsonb_array_elements(actual) WITH ORDINALITY a(value,n) FULL JOIN jsonb_array_elements(expected) WITH ORDINALITY e(value,n) ON a.n=e.n WHERE a.value IS DISTINCT FROM e.value);
 END IF;
 SELECT * INTO STRICT original FROM pg_attribute WHERE attrelid=reference_work AND attname='publication_id' AND NOT attisdropped;
 attribute_json:=(pg_temp.publication_attribute_semantics(original)-ARRAY['attrelid','attnum'])||jsonb_build_object('attrelid',actual_work,'attnum',new_attribute);
 IF attribute_json IS DISTINCT FROM (SELECT pg_temp.publication_attribute_semantics(a) FROM pg_attribute a WHERE a.attrelid=actual_work AND a.attnum=new_attribute)
 THEN RAISE EXCEPTION 'publication_work_column_changed';END IF;

 SELECT jsonb_agg(jsonb_build_object('index',to_jsonb(i),'relation',pg_temp.publication_relation_semantics(c)) ORDER BY c.relname COLLATE "C") INTO actual
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=actual_header;
 SELECT jsonb_agg(jsonb_build_object('index',(to_jsonb(i)-ARRAY['indexrelid','indrelid'])||jsonb_build_object(
  'indexrelid',pg_temp.publication_map_reference_relation(i.indexrelid),'indrelid',actual_header),
  'relation',pg_temp.publication_relation_semantics(c)) ORDER BY c.relname COLLATE "C") INTO expected
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_indexes_changed';END IF;
 SELECT jsonb_agg(to_jsonb(k) ORDER BY k.conname COLLATE "C") INTO actual FROM pg_constraint k WHERE k.conrelid=actual_header;
 SELECT jsonb_agg(pg_temp.publication_reference_constraint_record(k) ORDER BY k.conname COLLATE "C") INTO expected FROM pg_constraint k WHERE k.conrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_constraints_changed';END IF;
 SELECT to_jsonb(k) INTO actual FROM pg_constraint k WHERE k.conrelid=actual_work AND k.conname='native_turn_publication_operation';
 SELECT pg_temp.publication_reference_constraint_record(k) INTO expected FROM pg_constraint k WHERE k.conrelid=reference_work AND k.conname='native_turn_publication_operation';
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_work_foreign_key_changed';END IF;

 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO actual FROM pg_trigger t WHERE t.tgrelid=actual_header;
 SELECT jsonb_agg(mapped ORDER BY (mapped->>'oid')::oid) INTO expected FROM(
  SELECT pg_temp.publication_reference_trigger_record(t) mapped FROM pg_trigger t WHERE t.tgrelid=reference_header) mapped;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_triggers_changed';END IF;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO actual FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
  WHERE k.conrelid=actual_work AND k.conname='native_turn_publication_operation' AND t.tgrelid=actual_work;
 SELECT jsonb_agg(mapped ORDER BY (mapped->>'oid')::oid) INTO expected FROM(
  SELECT pg_temp.publication_reference_trigger_record(t) mapped FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
  WHERE k.conrelid=reference_work AND k.conname='native_turn_publication_operation' AND t.tgrelid=reference_work) mapped;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_work_constraint_triggers_changed';END IF;

 SELECT jsonb_agg(to_jsonb(d) ORDER BY d.adnum) INTO actual FROM pg_attrdef d WHERE d.adrelid=actual_header;
 SELECT jsonb_agg((to_jsonb(d)-ARRAY['oid','adrelid'])||jsonb_build_object('adrelid',actual_header,
  'oid',(SELECT a.oid FROM pg_attrdef a WHERE a.adrelid=actual_header AND a.adnum=d.adnum)) ORDER BY d.adnum)
  INTO expected FROM pg_attrdef d WHERE d.adrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_defaults_changed';END IF;
 IF EXISTS(SELECT FROM pg_attrdef WHERE adrelid=actual_work AND adnum=new_attribute)
 THEN RAISE EXCEPTION 'publication_work_column_default_changed';END IF;
 EXECUTE 'DROP SCHEMA publication_source_reference CASCADE';
END $schema$;

CREATE FUNCTION pg_temp.publication_table_snapshot() RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $snapshot$
SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('oid',c.oid,'owner',c.relowner,'kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl) ORDER BY c.oid)
 FROM pg_class c WHERE c.oid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'columns',(SELECT jsonb_agg(jsonb_build_array(attrelid,attnum,attname,atttypid,atttypmod,attnotnull,attidentity,attgenerated,attisdropped,attacl) ORDER BY attrelid,attnum)
 FROM pg_attribute WHERE attnum>0 AND attrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE tgrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE conrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE ev_class=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d WHERE adrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE polrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass,'native_conversation_publications'::regclass])))
$snapshot$;

DO $before_installer$
DECLARE old_snapshot jsonb;current_snapshot jsonb;remaining jsonb;old_rows jsonb;key text;
 header_id oid:='public.native_conversation_publications'::regclass;
 work_id oid:='public.native_turn_publication_work'::regclass;
 foreign_key oid:=(SELECT oid FROM pg_constraint WHERE conrelid='public.native_turn_publication_work'::regclass AND conname='native_turn_publication_operation');
BEGIN
 PERFORM pg_temp.publication_assert_source_schema();
 SELECT snapshot INTO STRICT old_snapshot FROM publication_predecessor_table_snapshot;
 current_snapshot:=pg_temp.publication_table_snapshot();
 FOREACH key IN ARRAY ARRAY['tables','columns','constraints','triggers','defaults','rules','policies'] LOOP
  SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]') INTO remaining
  FROM jsonb_array_elements(coalesce(nullif(current_snapshot->key,'null'::jsonb),'[]')) WITH ORDINALITY input(value,ordinal)
  WHERE NOT(
   key='tables' AND value->>'oid'=header_id::text
   OR key='columns' AND value->>0=header_id::text
   OR key='constraints' AND value->>'conrelid'=header_id::text
   OR key='triggers' AND value->>'tgrelid'=header_id::text
   OR key='defaults' AND value->>'adrelid'=header_id::text
   OR key='columns' AND value->>0=work_id::text AND value->>2='publication_id'
   OR key='constraints' AND value->>'oid'=foreign_key::text
   OR key='triggers' AND value->>'tgrelid'=work_id::text AND value->>'tgconstraint'=foreign_key::text);
  old_rows:=coalesce(nullif(old_snapshot->key,'null'::jsonb),'[]');
  IF remaining IS DISTINCT FROM old_rows THEN RAISE EXCEPTION 'publication_existing_schema_changed: %',key USING ERRCODE='55000';END IF;
 END LOOP;
 INSERT INTO publication_before_installer_schema VALUES(current_snapshot);
 INSERT INTO publication_before_installer_details SELECT pg_temp.publication_schema_details();
 PERFORM pg_temp.publication_assert_expected_functions();
END $before_installer$;

CREATE FUNCTION pg_temp.publication_successors_after_install() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $after$
DECLARE before_snapshot jsonb;after_snapshot jsonb;before_details jsonb;after_details jsonb;trigger_record pg_trigger;
 reference_record pg_trigger;expected_trigger jsonb;remaining jsonb;key text;header_id oid:='public.native_conversation_publications'::regclass;
BEGIN
 IF EXISTS(SELECT 1 FROM publication_verified_table_snapshot) OR EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D') THEN
  RAISE EXCEPTION 'publication_successor_phase_changed';END IF;
 -- The authenticated installer may add only the declared capture trigger.
 PERFORM pg_temp.publication_assert_expected_functions();
 IF (SELECT to_jsonb(t) FROM public.crm_erasure_journal_targets t WHERE table_name='native_conversation_publications')
  IS DISTINCT FROM jsonb_build_object('table_name','native_conversation_publications','key_columns',ARRAY['id']::text[],'capture_inserts',false)
 THEN RAISE EXCEPTION 'publication_recovery_target_changed' USING ERRCODE='55000';END IF;
 SELECT snapshot INTO STRICT before_snapshot FROM publication_before_installer_schema;
 SELECT snapshot INTO STRICT before_details FROM publication_before_installer_details;
 SELECT * INTO STRICT trigger_record FROM pg_trigger WHERE tgrelid=header_id AND tgname='crm_recovery_capture';
 IF to_regclass('pg_temp.publication_recovery_trigger_reference') IS NOT NULL THEN RAISE EXCEPTION 'publication_trigger_reference_exists';END IF;
 CREATE TEMP TABLE publication_recovery_trigger_reference(id uuid);
 CREATE TRIGGER crm_recovery_capture AFTER INSERT OR UPDATE OR DELETE ON publication_recovery_trigger_reference
  FOR EACH ROW EXECUTE FUNCTION public.crm_capture_erasure_effect();
 SELECT * INTO STRICT reference_record FROM pg_trigger WHERE tgrelid='pg_temp.publication_recovery_trigger_reference'::regclass AND tgname='crm_recovery_capture';
 expected_trigger:=(to_jsonb(reference_record)-ARRAY['oid','tgrelid'])||jsonb_build_object('oid',trigger_record.oid,'tgrelid',header_id);
 IF to_jsonb(trigger_record) IS DISTINCT FROM expected_trigger THEN RAISE EXCEPTION 'publication_recovery_trigger_changed' USING ERRCODE='55000';END IF;
 DROP TABLE pg_temp.publication_recovery_trigger_reference;
 after_snapshot:=pg_temp.publication_table_snapshot();
 SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]') INTO remaining FROM
  jsonb_array_elements(after_snapshot->'triggers') WITH ORDINALITY input(value,ordinal) WHERE value->>'oid'<>trigger_record.oid::text;
 after_snapshot:=jsonb_set(after_snapshot,'{triggers}',remaining);
 IF after_snapshot IS DISTINCT FROM before_snapshot THEN RAISE EXCEPTION 'publication_installer_schema_changed' USING ERRCODE='55000';END IF;
 after_details:=pg_temp.publication_schema_details();
 SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]') INTO remaining FROM
  jsonb_array_elements(after_details->'triggers') WITH ORDINALITY input(value,ordinal) WHERE value->>'oid'<>trigger_record.oid::text;
 after_details:=jsonb_set(after_details,'{triggers}',remaining);
 IF after_details IS DISTINCT FROM before_details THEN RAISE EXCEPTION 'publication_installer_successor_changed' USING ERRCODE='55000';END IF;
 PERFORM pg_temp.publication_assert_expected_functions();
 INSERT INTO publication_verified_table_snapshot SELECT pg_temp.publication_table_snapshot();
END $after$;

